                            Exercise(id: "de-read-anzeige-wohnung-q2", kind: "choice", prompt: "Warum ist sie ruhig ?", options: ["Balkon zum Innenhof", "Im Erdgeschoss", "Keine Nachbarn", "Auf dem Land"], answers: ["Balkon zum Innenhof"], explain: "Balkon zum Innenhof, deshalb ruhig."),
                            Exercise(id: "de-read-anzeige-wohnung-q3", kind: "written", prompt: "Wie weit ist die U-Bahn ?", options: [], answers: ["fünf minuten", "5 minuten", "fuenf minuten"], explain: "Die U-Bahn ist fünf Minuten entfernt."),
