                            Exercise(id: "de-read-anzeige-wohnung-q5", kind: "choice", prompt: "Wer wird bevorzugt ?", options: ["Jemand, der von zu Hause arbeitet", "Studierende", "Familien mit Kindern", "Rentner"], answers: ["Jemand, der von zu Hause arbeitet"], explain: "Wer von zu Hause arbeitet, wird bevorzugt.")], skills: ["reading:detail", "reading:inference", "grammar:comparatives"], exposureSkills: ["grammar:superlatives"]),
    ReadingText(id: "de-read-unvergessliche-reise", languageID: "de", title: "Die unvergessliche Reise", level: "B1", topic: "reisen", unitID: "de-foundations-u6",
        text: "Letzten Sommer habe ich die Reise gemacht, von der ich immer geträumt habe: fünfzehn Tage in Peru. Ich war schon in Mexiko und Argentinien, aber Südamerika hat mich wieder überrascht. Am dritten Tag bin ich zum Machu Picchu hochgestiegen. Es gab Nebel, deshalb hat man am Anfang nichts gesehen. Dann ist die Sonne langsam herausgekommen und die ganze Stadt ist erschienen. Ich habe nichts gesagt; ich bin nur dageblieben. Im Rückzugszug habe ich eine Familie aus Cusco kennengelernt, und sie haben mich zum Essen eingeladen. « Reisende sagen immer dasselbe », hat die Oma gelacht, « aber diese Suppe ist echt ». Sie hatte recht: es war das beste Essen der Reise. Seitdem, wenn jemand nach einem Reiseziel fragt, sage ich Peru.",
        questions: [
                            Exercise(id: "de-read-unvergessliche-reise-q1", kind: "choice", prompt: "Wie lange dauerte die Reise ?", options: ["Fünfzehn Tage", "Zehn Tage", "Ein Monat", "Drei Tage"], answers: ["Fünfzehn Tage"], explain: "Fünfzehn Tage in Peru."),
                            Exercise(id: "de-read-unvergessliche-reise-q2", kind: "written", prompt: "In welchen Ländern war er schon ?", options: [], answers: ["mexiko und argentinien"], explain: "Ich war schon in Mexiko und Argentinien."),
                            Exercise(id: "de-read-unvergessliche-reise-q3", kind: "choice", prompt: "Warum hat man am Anfang nichts gesehen ?", options: ["Wegen des Nebels", "Weil er geschlossen war", "Wegen starken Regens", "Weil es Nacht war"], answers: ["Wegen des Nebels"], explain: "Es gab Nebel, deshalb hat man nichts gesehen."),
                            Exercise(id: "de-read-unvergessliche-reise-q4", kind: "choice", prompt: "Mit wem hat er gegessen ?", options: ["Mit einer Familie aus Cusco", "Mit der Oma vom Hotel", "Allein", "Mit Freunden aus dem Zug"], answers: ["Mit einer Familie aus Cusco"], explain: "Eine Familie aus Cusco hat mich zum Essen eingeladen."),
                            Exercise(id: "de-read-unvergessliche-reise-q5", kind: "written", prompt: "Was sagt er jetzt, wenn jemand nach einem Reiseziel fragt ?", options: [], answers: ["peru"], explain: "Ich sage Peru.")], skills: ["reading:inference", "grammar:present-perfect", "grammar:connectors", "vocab:travel"]),
    ReadingText(id: "de-read-kolumne-autofrei", languageID: "de", title: "Kolumne: Autofrei!", level: "B2", topic: "meinung", unitID: "de-foundations-u8",
        text: "Ich finde, wir sollten die Innenstadt autofrei machen. Einerseits würde der Lärm sinken: Die Anwohner des Platzes fordern seit Jahren Ruhe. Andererseits würde die Verschmutzung sinken – sie übersteigt längst die erlaubten Grenzen. Es stimmt, dass der Handel Kunden verlieren fürchtet, aber die Zahlen anderer Städte sagen das Gegenteil: Wo das Auto verschwindet, gehen die Leute mehr spazieren und kaufen mehr. Die Firma, deren Bericht letzten Monat veröffentlicht wurde, hat 15 % mehr Umsatz in autofreien Straßen berechnet. Aus all dem verteidige ich die Maßnahme: Hätten wir den Mut, sie ein Jahr zu versuchen, wollten wir nie zurück.",
        questions: [
                            Exercise(id: "de-read-kolumne-autofrei-q1", kind: "choice", prompt: "Was ist die These der Kolumne ?", options: ["Innenstadt autofrei", "Autobahn verbreitern", "Fahrräder verbieten", "Parkhaus bauen"], answers: ["Innenstadt autofrei"], explain: "« Wir sollten die Innenstadt autofrei machen »."),
                            Exercise(id: "de-read-kolumne-autofrei-q2", kind: "written", prompt: "Was übersteigt längst die Grenzen ?", options: [], answers: ["die verschmutzung"], explain: "Die Verschmutzung übersteigt die Grenzen."),
                            Exercise(id: "de-read-kolumne-autofrei-q3", kind: "choice", prompt: "Wovor hat der Handel Angst ?", options: ["Kunden verlieren", "Mehr Steuern zahlen", "Im Sommer schließen", "Umziehen"], answers: ["Kunden verlieren"], explain: "Er fürchtet, Kunden zu verlieren."),
                            Exercise(id: "de-read-kolumne-autofrei-q4", kind: "written", prompt: "Wie viel mehr Umsatz in autofreien Straßen ?", options: [], answers: ["15%", "15 %", "fünfzehn prozent"], explain: "15 % mehr Umsatz."),
                            Exercise(id: "de-read-kolumne-autofrei-q5", kind: "choice", prompt: "Was schlägt der Autor am Ende vor ?", options: ["Ein Jahr versuchen", "Den Plan vergessen", "Mehr bestrafen", "Nochmal wählen"], answers: ["Ein Jahr versuchen"], explain: "« …sie ein Jahr zu versuchen ».")], skills: ["reading:inference", "writing:argument", "grammar:connectors", "grammar:second-conditional"]),
    ReadingText(id: "de-read-essay-stadt", languageID: "de", title: "Essay: Die kompakte Stadt", level: "C1", topic: "stadt", unitID: "de-foundations-u9",
        text: "Ob Großstadt oder Kleinstadt – die Frage klingt alt, doch sie verdient Nuancen. Befürworter der Großstadt verweisen auf Chancen und Vielfalt: Wer dort lebt, findet Arbeit, Kultur und Menschen, die anders denken. Kritiker halten dagegen, dass Mieten steigen und Nachbarschaften anonym werden. Zwar bietet die Kleinstadt Ruhe und günstigen Boden, aber sie kostet oft Mobilität: Wer überallhin fahren muss, verliert Zeit. Aus meiner Sicht entscheidet weniger die Größe als das Angebot: gute Nahversorgung, sichere Radwege, bezahlbare Räume. Sozusagen ist die ideale Stadt die, die Kompromisse überhaupt erst möglich macht. Zusammenfassend bleibt: Statt Ideale zu predigen, sollten Kommunen messen, was die Bewohner tatsächlich brauchen, und genau danach planen. Wer so vorgeht, gewinnt in beiden Welten etwas.",
        questions: [
                            Exercise(id: "de-read-essay-stadt-q1", kind: "choice", prompt: "Welchen Vorwurf erheben Kritiker gegen die Großstadt ?", options: ["Mieten steigen, Nachbarschaften werden anonym", "Es fehlt an Kultur", "Die Arbeit ist langweilig", "Alle denken gleich"], answers: ["Mieten steigen, Nachbarschaften werden anonym"], explain: "« …dass Mieten steigen und Nachbarschaften anonym werden »."),
                            Exercise(id: "de-read-essay-stadt-q2", kind: "written", prompt: "Was kostet die Kleinstadt laut Text oft ?", options: [], answers: ["mobilität", "mobilitat"], explain: "« …aber sie kostet oft Mobilität »."),
                            Exercise(id: "de-read-essay-stadt-q3", kind: "choice", prompt: "Worauf kommt es laut Text weniger an ?", options: ["Auf die Größe", "Auf die Nahversorgung", "Auf sichere Radwege", "Auf bezahlbare Räume"], answers: ["Auf die Größe"], explain: "« …entscheidet weniger die Größe als das Angebot »."),
                            Exercise(id: "de-read-essay-stadt-q4", kind: "written", prompt: "Was sollten Kommunen laut Text tun ?", options: [], answers: ["messen, was die bewohner brauchen", "messen was die bewohner tatsächlich brauchen", "messen was bewohner tatsachlich brauchen"], explain: "« …sollten Kommunen messen, was die Bewohner tatsächlich brauchen »."),
                            Exercise(id: "de-read-essay-stadt-q5", kind: "choice", prompt: "Welche Funktion hat « Sozusagen » im Text ?", options: ["Es markiert eine Formulierung mit Abstand", "Es leitet einen Widerspruch ein", "Es nennt eine Quelle", "Es beendet das Essay"], answers: ["Es markiert eine Formulierung mit Abstand"], explain: "« sozusagen » verallgemeinert mit Vorsicht.")], skills: ["reading:inference", "grammar:connectors", "writing:argument", "function:express-opinion"]),
    ReadingText(id: "de-read-rezension-buch", languageID: "de", title: "Rezension: Raus aus dem Hamsterrad", level: "C1", topic: "kultur", unitID: "de-foundations-u9",
        text: "Die Debatte « Raus aus dem Hamsterrad » verspricht viel – und hält mehr, als der Titel ahnen lässt. Die Autorin, Ökonomin und ehemalige Journalistin, verbindet Reportagen mit Daten: Zunächst porträtiert sie vier Berufstätige, danach weitet sie den Blick auf Arbeitszeitgesetze. Zwar klingen die Kapitel über Erschöpfung manchmal belehrend, aber die ehrlichen Interviews gleichen das aus. Besonders gelungen ist das Mitteldrittel: Dort zeigt sie, wie eine Fabrik ohne Heroismus auf vier Tage umstellte – keine Revolution, sozusagen Buchführung mit Menschenverstand. Weniger überzeugt das Schlusskapitel, das unbedingt werden will, wo Differenz nötig wäre. Aus meiner Sicht lohnt sich das Buch trotzdem, gerade für Leser, die nuancierte Argumente statt Parolen suchen. Zusammenfassend: eine etwas zu lange, doch selten faire Auseinandersetzung mit unserer Arbeitszeit.",
        questions: [
                            Exercise(id: "de-read-rezension-buch-q1", kind: "choice", prompt: "Wie bewertet die Rezensentin das Schlusskapitel ?", options: ["Es will unbedingt sein, wo Differenz nötig wäre", "Es ist besonders gelungen", "Es fehlt vollständig", "Es ist zu kurz geraten"], answers: ["Es will unbedingt sein, wo Differenz nötig wäre"], explain: "« …das unbedingt werden will, wo Differenz nötig wäre »."),
                            Exercise(id: "de-read-rezension-buch-q2", kind: "written", prompt: "Welches Beispiel zeigt das Mitteldrittel ?", options: [], answers: ["eine fabrik, die auf vier tage umstellte", "eine fabrik auf vier tage", "eine fabrik"], explain: "« …wie eine Fabrik … auf vier Tage umstellte »."),
                            Exercise(id: "de-read-rezension-buch-q3", kind: "choice", prompt: "Was gleicht die schwächeren Kapitel aus ?", options: ["Die ehrlichen Interviews", "Die Datenlage", "Die Titelwahl", "Die Arbeitszeitgesetze"], answers: ["Die ehrlichen Interviews"], explain: "« …aber die ehrlichen Interviews gleichen das aus »."),
                            Exercise(id: "de-read-rezension-buch-q4", kind: "written", prompt: "Für welche Leser lohnt sich das Buch laut Text ?", options: [], answers: ["leser, die nuancierte argumente suchen", "leser die nuancierte argumente statt parolen suchen"], explain: "« …für Leser, die nuancierte Argumente statt Parolen suchen »."),
                            Exercise(id: "de-read-rezension-buch-q5", kind: "choice", prompt: "Welches Urteil steht im letzten Satz ?", options: ["Etwas zu lang, doch selten fair", "Radikal und revolutionär", "Kurz und präzise", "Belehrend und unfair"], answers: ["Etwas zu lang, doch selten fair"], explain: "« eine etwas zu lange, doch selten faire Auseinandersetzung ».")], skills: ["reading:inference", "reading:scan", "vocab:collocations", "function:express-opinion"]),
    ReadingText(id: "de-read-brief-leitung", languageID: "de", title: "Brief an die Leitung", level: "C1", topic: "arbeit", unitID: "de-foundations-u9",
        text: "Sehr geehrte Frau Mertens,\n\nich wende mich heute an Sie, weil ich eine Anregung aus dem Support-Team weiterleiten möchte. Das Team schlägt vor, die Schichtpläne künftig zwei Wochen im Voraus zu veröffentlichen. Zwar ist das derzeit aus organisatorischen Gründen schwierig, jedoch berichten mehrere Kolleginnen, dass kurzfristige Änderungen die Kinderbetreuung belasten. Aus meiner Sicht wäre ein Kompromiss denkbar: feste Grundschichten, die nur in Ausnahmefällen wechseln. Ich wollte mich zudem erkundigen, ob Sie ein kurzes Gespräch in der nächsten Woche einträumen könnten; dabei können wir die Details gerne klären. Ich danke Ihnen im Voraus für Ihre Rückmeldung und stehe für Rückfragen selbstverständlich zur Verfügung.\n\nMit freundlichen Grüßen,\nJonas Berger",
        questions: [
                            Exercise(id: "de-read-brief-leitung-q1", kind: "choice", prompt: "Was schlägt das Team vor ?", options: ["Schichtpläne zwei Wochen im Voraus veröffentlichen", "Das Team verkleinern", "Die Kinderbetreuung übernehmen", "Alle Schichten streichen"], answers: ["Schichtpläne zwei Wochen im Voraus veröffentlichen"], explain: "« …die Schichtpläne künftig zwei Wochen im Voraus zu veröffentlichen »."),
                            Exercise(id: "de-read-brief-leitung-q2", kind: "written", prompt: "Was belasten kurzfristige Änderungen laut Brief ?", options: [], answers: ["die kinderbetreuung", "kinderbetreuung"], explain: "« …dass kurzfristige Änderungen die Kinderbetreuung belasten »."),
                            Exercise(id: "de-read-brief-leitung-q3", kind: "written", prompt: "Welchen Kompromiss schlägt Jonas vor ?", options: [], answers: ["feste grundschichten", "feste grundschichten, die nur in ausnahmefällen wechseln", "feste grundschichten, die nur in ausnahmefaellen wechseln"], explain: "« feste Grundschichten, die nur in Ausnahmefällen wechseln »."),
                            Exercise(id: "de-read-brief-leitung-q4", kind: "choice", prompt: "Warum schreibt Jonas ?", options: ["Um eine Anregung weiterzugeben und ein Gespräch vorzuschlagen", "Um zu kündigen", "Um eine Rechnung zu klären", "Um Urlaub zu beantragen"], answers: ["Um eine Anregung weiterzugeben und ein Gespräch vorzuschlagen"], explain: "Anregung + Gesprächsbitte sind der Zweck des Briefs."),
                            Exercise(id: "de-read-brief-leitung-q5", kind: "written", prompt: "Welche formelle Grußformel steht am Ende ?", options: [], answers: ["mit freundlichen grüßen", "mit freundlichen grussen"], explain: "« Mit freundlichen Grüßen » – Standard am Briefende.")], skills: ["reading:detail", "vocab:work", "grammar:connectors", "function:express-opinion"]),
    ReadingText(id: "de-read-anzeige-mitbewohner", languageID: "de", title: "Anzeige: Mitbewohner gesucht", level: "A1", topic: "Wohnen", unitID: "de-foundations-u10",
        text: "Zimmer frei! Ich suche einen Mitbewohner für meine Wohnung. Die Wohnung liegt im zweiten Stock und hat vier Zimmer. Dein Zimmer ist 18 Quadratmeter groß und sehr hell. Es gibt eine Küche, ein Bad und einen kleinen Balkon. Auf dem Balkon stehen zwei Stühle. Ich heiße Anna, bin 27 Jahre alt und arbeite als Verkäuferin. Ich bin ruhig und ordentlich. Mein Sofa ist alt, aber gemütlich. Schreib mir!",
        questions: [
                            Exercise(id: "de-read-anzeige-mitbewohner-q1", kind: "choice", prompt: "Was sucht Anna ?", options: ["Einen Mitbewohner", "Eine neue Wohnung", "Einen Job", "Ein Sofa"], answers: ["Einen Mitbewohner"], explain: "Ich suche einen Mitbewohner für meine Wohnung."),
                            Exercise(id: "de-read-anzeige-mitbewohner-q2", kind: "written", prompt: "Wie groß ist das Zimmer ?", options: [], answers: ["18 quadratmeter", "achtzehn quadratmeter", "18 qm"], explain: "Dein Zimmer ist 18 Quadratmeter groß."),
                            Exercise(id: "de-read-anzeige-mitbewohner-q3", kind: "choice", prompt: "Was gibt es auf dem Balkon ?", options: ["Zwei Stühle", "Ein Sofa", "Einen Tisch", "Blumen"], answers: ["Zwei Stühle"], explain: "Auf dem Balkon stehen zwei Stühle."),
                            Exercise(id: "de-read-anzeige-mitbewohner-q4", kind: "written", prompt: "Wie alt ist Anna ?", options: [], answers: ["27", "27 jahre", "sie ist 27 jahre alt"], explain: "Anna ist 27 Jahre alt."),
                            Exercise(id: "de-read-anzeige-mitbewohner-q5", kind: "choice", prompt: "Wie ist Anna ?", options: ["Ruhig und ordentlich", "Laut und unordentlich", "Nett, aber laut", "Sehr sportlich"], answers: ["Ruhig und ordentlich"], explain: "Ich bin ruhig und ordentlich.")], skills: ["reading:detail", "reading:scan", "grammar:possessives", "vocab:home", "function:describe-people"]),
    ReadingText(id: "de-read-nachricht-gruppe", languageID: "de", title: "Nachrichten fürs Wochenende", level: "A1", topic: "Wochenende", unitID: "de-foundations-u13",
        text: "Gruppe „Wochenende“ — Kim: Es regnet am Samstag. Ich bleibe zu Hause und lese. Ich lese immer am Wochenende. Sam: Ich koche gern. Wer kommt zum Essen ? Wir kochen um 18 Uhr. Mia: Ich bin dabei! Ich spiele oft Volleyball, aber am Samstag nie. Im Sommer spiele ich jeden Tag. Sam: Super. Bis Samstag! — Kim: Ich komme auch. Bis dann!",
        questions: [
                            Exercise(id: "de-read-nachricht-gruppe-q1", kind: "choice", prompt: "Wie ist das Wetter am Samstag ?", options: ["Es regnet", "Es schneit", "Es ist sonnig", "Es ist warm"], answers: ["Es regnet"], explain: "Kim: Es regnet am Samstag."),
                            Exercise(id: "de-read-nachricht-gruppe-q2", kind: "written", prompt: "Was macht Mia oft ?", options: [], answers: ["volleyball", "sie spielt volleyball", "volleyball spielen"], explain: "Ich spiele oft Volleyball, aber am Samstag nie."),
                            Exercise(id: "de-read-nachricht-gruppe-q3", kind: "choice", prompt: "Wann kocht Sam ?", options: ["Um 18 Uhr", "Um 8 Uhr", "Am Morgen", "Um 20 Uhr"], answers: ["Um 18 Uhr"], explain: "Wir kochen um 18 Uhr."),
                            Exercise(id: "de-read-nachricht-gruppe-q4", kind: "written", prompt: "Was macht Kim immer am Wochenende ?", options: [], answers: ["lesen", "sie liest", "kim liest"], explain: "Ich lese immer am Wochenende."),
                            Exercise(id: "de-read-nachricht-gruppe-q5", kind: "choice", prompt: "Wer kommt zum Essen ?", options: ["Kim und Mia", "Nur Mia", "Niemand", "Sam und Kim"], answers: ["Kim und Mia"], explain: "Mia: Ich bin dabei! — Kim: Ich komme auch.")], skills: ["reading:detail", "reading:scan", "vocab:hobbies", "vocab:daily-routine", "grammar:frequency-adverbs"]),
    ReadingText(id: "de-read-fahrplan-ubahn", languageID: "de", title: "Fahrplan der U2", level: "A1", topic: "Fahrplan", unitID: "de-foundations-u14",
        text: "U2: Ruhleben — Pankow. Fahrplan von Montag bis Freitag. Die erste Bahn fährt um 4:30 Uhr. Danach kommt alle fünf Minuten eine Bahn. Von Gleis 2 fährt die Bahn um 8:00, 8:05 und 8:10 Uhr. Nach 20 Uhr kommt alle zehn Minuten eine Bahn. Die letzte Bahn fährt um 1:00 Uhr. Eine Fahrkarte kostet 3 Euro 50. Du kaufst sie vor der Fahrt am Automaten.",
        questions: [
                            Exercise(id: "de-read-fahrplan-ubahn-q1", kind: "choice", prompt: "Wann fährt die erste Bahn ?", options: ["Um 4:30 Uhr", "Um 8:00 Uhr", "Um 1:00 Uhr", "Um 20 Uhr"], answers: ["Um 4:30 Uhr"], explain: "Die erste Bahn fährt um 4:30 Uhr."),
                            Exercise(id: "de-read-fahrplan-ubahn-q2", kind: "written", prompt: "Von welchem Gleis fährt die Bahn am Morgen ?", options: [], answers: ["gleis 2", "von gleis 2"], explain: "Von Gleis 2 fährt die Bahn um 8:00, 8:05 und 8:10 Uhr."),
                            Exercise(id: "de-read-fahrplan-ubahn-q3", kind: "choice", prompt: "Wann fährt die letzte Bahn ?", options: ["Um 1:00 Uhr", "Um 4:30 Uhr", "Um 8:10 Uhr", "Um 20:10 Uhr"], answers: ["Um 1:00 Uhr"], explain: "Die letzte Bahn fährt um 1:00 Uhr."),
                            Exercise(id: "de-read-fahrplan-ubahn-q4", kind: "written", prompt: "Was kostet eine Fahrkarte ?", options: [], answers: ["3 euro 50", "drei euro fünfzig", "drei euro funfzig", "3,50 euro"], explain: "Eine Fahrkarte kostet 3 Euro 50."),
                            Exercise(id: "de-read-fahrplan-ubahn-q5", kind: "choice", prompt: "Wie oft kommt eine Bahn nach 20 Uhr ?", options: ["Alle zehn Minuten", "Alle fünf Minuten", "Alle zwanzig Minuten", "Um 1:00 Uhr"], answers: ["Alle zehn Minuten"], explain: "Nach 20 Uhr kommt alle zehn Minuten eine Bahn.")], skills: ["reading:detail", "reading:scan", "vocab:transport", "function:tell-time"]),
    ReadingText(id: "de-read-nachrichtenverlauf", languageID: "de", title: "Der Nachrichtenverlauf", level: "A2", topic: "nachrichten", unitID: "de-foundations-u17",
        text: "Gruppe « Emmas Geburtstag », Samstagvormittag. Paul: « Hallo ihr zwei ! Habt ihr das Kochbuch schon gekauft ? » Mia: « Ja, gestern gekauft. Ich werde es heute einpacken. Und du bringst die Getränke ? » Paul: « Klar. Anna kann leider nicht kommen. Sie schreibt: Schade, ich muss arbeiten, weil ein Kunde kommt. » Mia: « Mmh, schade. Sie kommt doch sonst immer. » Paul: « Vielleicht geht es am Sonntag — ich frage nach. » Mia: « Gute Idee ! Ich werde dann den Kuchen holen. Bis heute Abend ! » Paul: « Bis dann ! Emma weiß von nichts. »",
        questions: [
                            Exercise(id: "de-read-nachrichtenverlauf-q1", kind: "choice", prompt: "Was wurde schon gekauft ?", options: ["Das Kochbuch", "Der Kuchen", "Die Getränke", "Ballons"], answers: ["Das Kochbuch"], explain: "« Habt ihr das Kochbuch schon gekauft ? » — « Ja, gestern gekauft »."),
                            Exercise(id: "de-read-nachrichtenverlauf-q2", kind: "written", prompt: "Was wird Mia heute einpacken ?", options: [], answers: ["das kochbuch", "das buch"], explain: "« Ich werde es heute einpacken » — das Kochbuch."),
                            Exercise(id: "de-read-nachrichtenverlauf-q3", kind: "choice", prompt: "Warum kommt Anna nicht ?", options: ["Sie muss arbeiten", "Sie ist krank", "Sie hat keine Zeit für die Gruppe", "Sie weiß von nichts"], answers: ["Sie muss arbeiten"], explain: "« Ich muss arbeiten, weil ein Kunde kommt »."),
                            Exercise(id: "de-read-nachrichtenverlauf-q4", kind: "choice", prompt: "Was fragt Paul bei Anna nach ?", options: ["Ob es am Sonntag geht", "Ob sie den Kuchen holt", "Ob sie das Kochbuch kauft", "Ob sie Getränke bringt"], answers: ["Ob es am Sonntag geht"], explain: "« Vielleicht geht es am Sonntag — ich frage nach »."),
                            Exercise(id: "de-read-nachrichtenverlauf-q5", kind: "written", prompt: "Wer holt den Kuchen ?", options: [], answers: ["mia"], explain: "« Ich werde dann den Kuchen holen », schreibt Mia.")], skills: ["reading:detail", "reading:inference", "vocab:social-expressions", "grammar:going-to"]),
    ReadingText(id: "de-read-bewertung-defekt", languageID: "de", title: "Die Online-Bewertung", level: "A2", topic: "bewertung", unitID: "de-foundations-u20",
        text: "« Ich habe den Wasserkocher WK200 im Mai gekauft. Nach zwei Wochen ist er kaputtgegangen: Das Gerät ging einfach nicht mehr an. Ich habe am Freitag beim Kundendienst angerufen und die Rechnung per E-Mail geschickt. Am Montag kam schon ein Paket: ein neues Gerät, kostenlos, mit einer kleinen Entschuldigung. Das neue Gerät läuft seit einem Monat ohne Probleme. Deshalb gibt es trotzdem vier Sterne: Kaputt war ärgerlich, aber der Service war wirklich schnell. Wer einen günstigen Wasserkocher sucht, ist hier gut aufgehoben — der Kundendienst macht den Unterschied. »",
        questions: [
                            Exercise(id: "de-read-bewertung-defekt-q1", kind: "choice", prompt: "Was hat die Kundin im Mai gekauft ?", options: ["Einen Wasserkocher", "Eine Kaffeemaschine", "Einen Fernseher", "Eine Lampe"], answers: ["Einen Wasserkocher"], explain: "« Ich habe den Wasserkocher WK200 im Mai gekauft. »"),
                            Exercise(id: "de-read-bewertung-defekt-q2", kind: "written", prompt: "Was ist nach zwei Wochen passiert ?", options: [], answers: ["er ist kaputtgegangen", "das gerät ist kaputtgegangen", "das geraet ist kaputt gegangen", "er ist kaputt gegangen"], explain: "« Nach zwei Wochen ist er kaputtgegangen. »"),
                            Exercise(id: "de-read-bewertung-defekt-q3", kind: "choice", prompt: "Wann hat die Kundin den Kundendienst angerufen ?", options: ["Am Freitag", "Am Montag", "Im Mai", "Nach einem Monat"], answers: ["Am Freitag"], explain: "« Ich habe am Freitag beim Kundendienst angerufen … »"),
                            Exercise(id: "de-read-bewertung-defekt-q4", kind: "choice", prompt: "Was war im Paket vom Montag ?", options: ["Ein neues Gerät", "Ihr Geld", "Nur eine Entschuldigung", "Nur die Rechnung"], answers: ["Ein neues Gerät"], explain: "« Am Montag kam schon ein Paket: ein neues Gerät, kostenlos. »"),
                            Exercise(id: "de-read-bewertung-defekt-q5", kind: "written", prompt: "Warum gibt es trotzdem vier Sterne ?", options: [], answers: ["der service war schnell", "weil der service schnell war", "der service war wirklich schnell"], explain: "« Kaputt war ärgerlich, aber der Service war wirklich schnell. »")], skills: ["reading:detail", "reading:inference", "function:solve-problems", "grammar:past-simple-regular"]),
    ReadingText(id: "de-read-kofferliste", languageID: "de", title: "Ninas Kofferliste", level: "A2", topic: "reisen", unitID: "de-foundations-u25",
        text: "Am Samstag fliegt Nina nach Lissabon. Am Abend vorher schreibt sie eine Liste, denn sie will nichts vergessen. In den Koffer kommen fünf T-Shirts, zwei Hosen, ein leichtes Kleid, eine Regenjacke und ihre guten Schuhe. An Dokumente denkt sie besonders: Reisepass, Ausweis und die Buchungsbestätigung kommen in die Handtasche. Handy und Ladegerät gehören auch hinein. Nina wird schon am Abend packen, denn am Morgen hat sie keine Zeit. Der Koffer ist klein, deshalb nimmt sie nur das Wichtigste mit. Die Sonnencreme kauft sie noch am Flughafen. Vor der Tür kontrolliert sie alles zweimal — den Reisepass hat sie letztes Mal fast vergessen !",
        questions: [
                            Exercise(id: "de-read-kofferliste-q1", kind: "choice", prompt: "Wann fliegt Nina nach Lissabon ?", options: ["Am Samstag", "Am Sonntag", "Am Freitag", "Heute"], answers: ["Am Samstag"], explain: "Am Samstag fliegt Nina nach Lissabon."),
                            Exercise(id: "de-read-kofferliste-q2", kind: "choice", prompt: "Wo kommen die Dokumente hin ?", options: ["In die Handtasche", "In den großen Koffer", "In die Jackentasche", "Ins Hotel"], answers: ["In die Handtasche"], explain: "Reisepass, Ausweis und die Buchungsbestätigung kommen in die Handtasche."),
                            Exercise(id: "de-read-kofferliste-q3", kind: "written", prompt: "Was kauft Nina noch am Flughafen ?", options: [], answers: ["sonnencreme", "die sonnencreme"], explain: "Die Sonnencreme kauft sie noch am Flughafen."),
                            Exercise(id: "de-read-kofferliste-q4", kind: "choice", prompt: "Warum packt Nina schon am Abend ?", options: ["Am Morgen hat sie keine Zeit", "Der Koffer ist zu groß", "Sie fliegt früher", "Der Flug geht am Abend"], answers: ["Am Morgen hat sie keine Zeit"], explain: "Nina wird schon am Abend packen, denn am Morgen hat sie keine Zeit."),
                            Exercise(id: "de-read-kofferliste-q5", kind: "written", prompt: "Was hat sie letztes Mal fast vergessen ?", options: [], answers: ["den reisepass", "ihren reisepass", "den pass"], explain: "Den Reisepass hat sie letztes Mal fast vergessen !")], skills: ["reading:detail", "grammar:going-to", "vocab:travel", "vocab:transport"]),
    ReadingText(id: "de-read-nachbarschaftsplakat", languageID: "de", title: "Mehr Grün im Viertel", level: "B1", topic: "stadt", unitID: "de-foundations-u26",
        text: "« Mehr Grün im Viertel ! » steht auf dem Plakat am Supermarkt. Eine Bürgerinitiative will den Parkplatz an der Post in einen kleinen Park verwandeln. Einerseits verlieren wir zwanzig Parkplätze, andererseits gewinnen wir vierzig Bäume, Bänke und einen Spielplatz. « Autos können überall parken, aber hier gibt es keinen grünen Ort », sagt die Sprecherin. Die Gegner sind anderer Meinung: Der Parkplatz ist morgens voll, und die Geschäfte brauchen ihre Kunden. Die Initiative schlägt vor, dass die Stadt in der Seitenstraße zusätzliche Stellplätze baut. Bis Ende des Monats brauchen die Gründer fünfhundert Unterschriften — dann muss der Stadtrat über den Vorschlag sprechen. Wer unterschreiben will, findet das Plakat bis Sonntag am Supermarkt.",
        questions: [
                            Exercise(id: "de-read-nachbarschaftsplakat-q1", kind: "choice", prompt: "Was will die Bürgerinitiative ?", options: ["Einen Park statt des Parkplatzes", "Mehr Parkplätze", "Einen neuen Supermarkt", "Ein Rathaus"], answers: ["Einen Park statt des Parkplatzes"], explain: "Sie will den Parkplatz an der Post in einen kleinen Park verwandeln."),
                            Exercise(id: "de-read-nachbarschaftsplakat-q2", kind: "choice", prompt: "Was ist das Argument der Gegner ?", options: ["Der Parkplatz ist morgens voll", "Es gibt zu viele Bäume", "Der Spielplatz ist teuer", "Die Post schließt"], answers: ["Der Parkplatz ist morgens voll"], explain: "Der Parkplatz ist morgens voll, und die Geschäfte brauchen ihre Kunden."),
                            Exercise(id: "de-read-nachbarschaftsplakat-q3", kind: "written", prompt: "Wie viele Unterschriften braucht die Initiative ?", options: [], answers: ["500", "fünfhundert", "fuenfhundert"], explain: "Bis Ende des Monats brauchen die Gründer fünfhundert Unterschriften."),
                            Exercise(id: "de-read-nachbarschaftsplakat-q4", kind: "choice", prompt: "Was passiert bei fünfhundert Unterschriften ?", options: ["Der Stadtrat muss über den Vorschlag sprechen", "Der Park wird sofort gebaut", "Die Initiative bekommt Geld", "Die Geschäfte schließen"], answers: ["Der Stadtrat muss über den Vorschlag sprechen"], explain: "Dann muss der Stadtrat über den Vorschlag sprechen."),
                            Exercise(id: "de-read-nachbarschaftsplakat-q5", kind: "written", prompt: "Wo kann man bis Sonntag unterschreiben ?", options: [], answers: ["am supermarkt", "beim supermarkt"], explain: "Wer unterschreiben will, findet das Plakat bis Sonntag am Supermarkt.")], skills: ["reading:inference", "grammar:connectors", "function:express-opinion", "writing:argument"]),
    ReadingText(id: "de-read-hobbys-anna", languageID: "de", title: "Annas Woche", level: "A1", topic: "hobbys", unitID: "de-foundations-u27",
        text: "Anna ist 24 Jahre alt und kommt aus Leipzig. Sie arbeitet als Verkäuferin. In ihrer Freizeit spielt sie gern Gitarre und liest gern Krimis. Am Samstag geht sie mit Freunden in ein Café. Sie kocht nicht gern — ihr Freund kocht fantastisch ! Am Sonntag schläft Anna lange und fährt dann mit dem Fahrrad an den See. Im Winter geht sie oft schwimmen, im Sommer spielt sie Volleyball im Park. Was machst du gern ? Schreib Anna eine Nachricht !",
        questions: [
                            Exercise(id: "de-read-hobbys-anna-q1", kind: "choice", prompt: "Woher kommt Anna ?", options: ["Aus Leipzig", "Aus Berlin", "Aus Wien", "Aus Hamburg"], answers: ["Aus Leipzig"], explain: "« Anna … kommt aus Leipzig. »"),
                            Exercise(id: "de-read-hobbys-anna-q2", kind: "written", prompt: "Was spielt Anna gern ?", options: [], answers: ["gitarre", "sie spielt gitarre"], explain: "« In ihrer Freizeit spielt sie gern Gitarre. »"),
                            Exercise(id: "de-read-hobbys-anna-q3", kind: "choice", prompt: "Wer kocht bei Anna ?", options: ["Ihr Freund", "Anna", "Ihre Mutter", "Niemand"], answers: ["Ihr Freund"], explain: "« …ihr Freund kocht fantastisch ! »"),
                            Exercise(id: "de-read-hobbys-anna-q4", kind: "written", prompt: "Was macht Anna am Sonntag ?", options: [], answers: ["sie schlaeft lange und faehrt an den see", "sie schläft lange und fährt an den see", "sie schläft lange und fährt mit dem fahrrad an den see"], explain: "« Am Sonntag schläft Anna lange und fährt dann mit dem Fahrrad an den See. »"),
                            Exercise(id: "de-read-hobbys-anna-q5", kind: "choice", prompt: "Was macht Anna im Sommer im Park ?", options: ["Sie spielt Volleyball", "Sie schwimmt", "Sie liest Krimis", "Sie arbeitet"], answers: ["Sie spielt Volleyball"], explain: "« Im Sommer spielt sie Volleyball im Park. »")], skills: ["reading:detail", "vocab:hobbies", "grammar:present-simple"]),
    ReadingText(id: "de-read-markt-preise", languageID: "de", title: "Am Markt bei Frau Öz", level: "A1", topic: "einkaufen", unitID: "de-foundations-u5",
        text: "Der Markt ist jeden Samstag von 8 bis 14 Uhr offen. Am Stand von Frau Öz gibt es Obst und Gemüse: Äpfel kosten 2 Euro 50 pro Kilo, Bananen 1 Euro 90, Tomaten nur 2 Euro. Sie sind heute günstig. Käse vom Bauern kostet 8 Euro pro Packung, frischer Fisch 12 Euro. Brot gibt es beim Stand nebenan. Kinder bekommen einen Apfel gratis. Frau Öz verkauft gern und viel: Am Mittag sind die Tomaten oft schon weg. Komm früh !",
        questions: [
                            Exercise(id: "de-read-markt-preise-q1", kind: "written", prompt: "Wie viel kostet ein Kilo Tomaten ?", options: [], answers: ["2 euro", "zwei euro"], explain: "« Tomaten nur 2 Euro. »"),
                            Exercise(id: "de-read-markt-preise-q2", kind: "choice", prompt: "Was kostet ein Kilo Bananen ?", options: ["1 Euro 90", "2 Euro 50", "1 Euro", "3 Euro"], answers: ["1 Euro 90"], explain: "« Bananen 1 Euro 90. »"),
                            Exercise(id: "de-read-markt-preise-q3", kind: "choice", prompt: "Wie lange ist der Markt offen ?", options: ["8 bis 14 Uhr", "7 bis 12 Uhr", "9 bis 15 Uhr", "8 bis 18 Uhr"], answers: ["8 bis 14 Uhr"], explain: "« Der Markt ist jeden Samstag von 8 bis 14 Uhr offen. »"),
                            Exercise(id: "de-read-markt-preise-q4", kind: "written", prompt: "Was bekommen Kinder gratis ?", options: [], answers: ["einen apfel", "ein apfel", "apfel"], explain: "« Kinder bekommen einen Apfel gratis. »"),
                            Exercise(id: "de-read-markt-preise-q5", kind: "choice", prompt: "Wann sind die Tomaten oft schon weg ?", options: ["Am Mittag", "Am Morgen", "Um 8 Uhr", "Nie"], answers: ["Am Mittag"], explain: "« Am Mittag sind die Tomaten oft schon weg. »")], skills: ["reading:scan", "vocab:food", "function:go-shopping"]),
    ReadingText(id: "de-read-bewerbung-lea", languageID: "de", title: "Leas Bewerbung", level: "B1", topic: "arbeit", unitID: "de-foundations-u21",
        text: "Betreff: Bewerbung als Praktikantin im Marketing — Liebe Frau Berger, ich habe Ihre Anzeige auf der Jobbörse gesehen und interessiere mich sehr für die Stelle. Seit zwei Jahren studiere ich Medienmanagement in Münster; im Sommer habe ich ein Praktikum bei einer kleinen Agentur gemacht. Dort habe ich Social-Media-Kanäle betreut und zwei Kampagnen mitgeplant. Meine Professorin, Frau Krause, hat mich auf Ihre Firma aufmerksam gemacht — man sagt, bei Ihnen wird Teamarbeit großgeschrieben. Gerne schicke ich Ihnen meine Zeugnisse und Arbeitsproben. Über ein persönliches Gespräch freue ich mich sehr. Passt es Ihnen nächste Woche vormittags ? Mit freundlichen Grüßen, Lea Hoffmann",
        questions: [
                            Exercise(id: "de-read-bewerbung-lea-q1", kind: "choice", prompt: "Um welche Stelle geht es ?", options: ["Praktikum im Marketing", "Festanstellung als Designerin", "Stelle als Professorin", "Ausbildung im Vertrieb"], answers: ["Praktikum im Marketing"], explain: "« Bewerbung als Praktikantin im Marketing »."),
                            Exercise(id: "de-read-bewerbung-lea-q2", kind: "written", prompt: "Was hat Lea im Sommer gemacht ?", options: [], answers: ["ein praktikum", "sie hat ein praktikum gemacht", "ein praktikum bei einer agentur"], explain: "« Im Sommer habe ich ein Praktikum bei einer kleinen Agentur gemacht. »"),
                            Exercise(id: "de-read-bewerbung-lea-q3", kind: "choice", prompt: "Wer hat sie auf die Firma aufmerksam gemacht ?", options: ["Frau Krause", "Frau Berger", "Eine Freundin", "Der Chef"], answers: ["Frau Krause"], explain: "« Meine Professorin, Frau Krause, hat mich auf Ihre Firma aufmerksam gemacht. »"),
                            Exercise(id: "de-read-bewerbung-lea-q4", kind: "choice", prompt: "Wann möchte Lea zum Gespräch kommen ?", options: ["Nächste Woche vormittags", "Heute Nachmittag", "Nächsten Montag abends", "In zwei Wochen"], answers: ["Nächste Woche vormittags"], explain: "« Passt es Ihnen nächste Woche vormittags ? »"),
                            Exercise(id: "de-read-bewerbung-lea-q5", kind: "written", prompt: "Was schickt Lea gern mit ?", options: [], answers: ["zeugnisse und arbeitsproben", "ihre zeugnisse und arbeitsproben"], explain: "« Gerne schicke ich Ihnen meine Zeugnisse und Arbeitsproben. »")], skills: ["reading:detail", "writing:email", "function:talk-about-work"]),
    ReadingText(id: "de-read-falsche-nummer", languageID: "de", title: "Die Nachricht an die falsche Nummer", level: "B1", topic: "erlebnisse", unitID: "de-foundations-u18",
        text: "Es war ein grauer Dienstag, als Miriam eine Nachricht bekam: « Hallo Oma, ich habe meinen Schlüssel verloren. Bist du zu Hause ? » Die Nummer kannte sie nicht. Statt die Nachricht zu löschen, antwortete sie: « Ich bin leider nicht deine Oma, aber ich mache Tee. Komm trotzdem ! » Eine Stunde später stand Jonas vor ihrer Tür, müde und ratlos. Sie tranken Tee, redeten zwei Stunden — und lachten viel. Am Abend fand Jonas den Schlüssel in seiner Jackentasche: Er war nie verloren gewesen. Aber er sagt heute, die falsche Nummer sei der beste Fehler seines Jahres. Die beiden sind seitdem gute Freunde.",
        questions: [
                            Exercise(id: "de-read-falsche-nummer-q1", kind: "choice", prompt: "Was stand in der Nachricht ?", options: ["Ein verlorener Schlüssel", "Eine Einladung zum Kaffee", "Ein Jobangebot", "Ein Umzug"], answers: ["Ein verlorener Schlüssel"], explain: "« Ich habe meinen Schlüssel verloren. Bist du zu Hause ? »"),
                            Exercise(id: "de-read-falsche-nummer-q2", kind: "written", prompt: "Was machte Miriam statt die Nachricht zu löschen ?", options: [], answers: ["sie antwortete", "sie hat geantwortet"], explain: "« Statt die Nachricht zu löschen, antwortete sie. »"),
                            Exercise(id: "de-read-falsche-nummer-q3", kind: "choice", prompt: "Wie lange redeten die beiden beim ersten Mal ?", options: ["Zwei Stunden", "Eine Stunde", "Zwanzig Minuten", "Den ganzen Abend"], answers: ["Zwei Stunden"], explain: "« Sie tranken Tee, redeten zwei Stunden — und lachten viel. »"),
                            Exercise(id: "de-read-falsche-nummer-q4", kind: "choice", prompt: "Wo war der Schlüssel wirklich ?", options: ["In Jonas' Jackentasche", "Bei der Oma", "Im Café", "Unter dem Tisch"], answers: ["In Jonas' Jackentasche"], explain: "« …fand Jonas den Schlüssel in seiner Jackentasche: Er war nie verloren gewesen. »"),
                            Exercise(id: "de-read-falsche-nummer-q5", kind: "written", prompt: "Was sagt Jonas über die falsche Nummer ?", options: [], answers: ["der beste fehler seines jahres", "sie sei der beste fehler seines jahres"], explain: "« …die falsche Nummer sei der beste Fehler seines Jahres. »")], skills: ["reading:inference", "function:tell-a-story", "grammar:connectors"]),
    ReadingText(id: "de-read-leserbrief-handy", languageID: "de", title: "Leserbrief: Das Handy gehört nicht in die Schulbank", level: "B2", topic: "meinung", unitID: "de-foundations-u8",
        text: "Sehr geehrte Redaktion, immer wieder fordern Politiker ein Handyverbot an Schulen — und ich widerspreche. Zugegeben: Wer während des Unterrichts scrollt, lernt weniger; das zeigen die Studien aus Nachbarländern deutlich. Aber ein generelles Verbot verfehlt das Ziel. Wer seinen Schülern konzentriertes Arbeiten beibringen will, muss ihnen Verantwortung geben, nicht Verbote. An unserer Schule regeln die Klassen selbst, wann das Handy weggepackt wird — die Lehrkräfte beraten nur noch. Die Ergebnisse sind erstaunlich: weniger Konflikte, mehr Eigenverantwortung. Statt Verbote zu verschärfen, sollten wir digitale Bildung stärken. Ein Kind, das nie gelernt hat, mit dem Handy umzugehen, wird auch ohne Verbot abgelenkt sein — nur klüger ist es nicht geworden. Ich freue mich auf die Diskussion. Markus Vogel, Lehrer aus Essen",
        questions: [
                            Exercise(id: "de-read-leserbrief-handy-q1", kind: "choice", prompt: "Was ist die These des Briefes ?", options: ["Kein generelles Handyverbot", "Mehr Verbote an Schulen", "Handys sofort verbieten", "Handys für alle Fächer"], answers: ["Kein generelles Handyverbot"], explain: "« …fordern Politiker ein Handyverbot an Schulen — und ich widerspreche. »"),
                            Exercise(id: "de-read-leserbrief-handy-q2", kind: "written", prompt: "Was zeigen die Studien aus Nachbarländern ?", options: [], answers: ["wer im unterricht scrollt lernt weniger", "wer waehrend des unterrichts scrollt lernt weniger", "scrollende schueler lernen weniger"], explain: "« Wer während des Unterrichts scrollt, lernt weniger. »"),
                            Exercise(id: "de-read-leserbrief-handy-q3", kind: "choice", prompt: "Wie regelt die Schule des Autors das Handy ?", options: ["Die Klassen selbst regeln es", "Die Polizei kontrolliert", "Ein Verbot seit diesem Jahr", "Die Eltern sammeln die Handys"], answers: ["Die Klassen selbst regeln es"], explain: "« …regeln die Klassen selbst, wann das Handy weggepackt wird. »"),
                            Exercise(id: "de-read-leserbrief-handy-q4", kind: "choice", prompt: "Was sollen Schulen laut Autor stattdessen stärken ?", options: ["Digitale Bildung", "Sportunterricht", "Disziplinarstrafen", "Alte Medien"], answers: ["Digitale Bildung"], explain: "« Statt Verbote zu verschärfen, sollten wir digitale Bildung stärken. »"),
                            Exercise(id: "de-read-leserbrief-handy-q5", kind: "written", prompt: "Welche Ergebnisse nennt der Autor ?", options: [], answers: ["weniger konflikte, mehr eigenverantwortung", "weniger konflikte und mehr eigenverantwortung"], explain: "« Die Ergebnisse sind erstaunlich: weniger Konflikte, mehr Eigenverantwortung. »")], skills: ["reading:inference", "writing:argument", "grammar:connectors", "grammar:second-conditional"]),
    ReadingText(id: "de-read-nachricht-radwege", languageID: "de", title: "Stadt verzögert Radwege-Ausbau", level: "B2", topic: "nachrichten", unitID: "de-foundations-u8",
        text: "Wie die Stadtverwaltung am Dienstag mitteilte, wird der geplante Ausbau der Radwege um mindestens ein Jahr verschoben. Der Grund: Die Baufirma, deren Angebot eigentlich günstig war, habe die Unterlagen unvollständig eingereicht. Deshalb müsse neu ausgeschrieben werden. Kritik kommt aus dem Stadtrat: Die Opposition spricht von einem verpatzten Projekt und fordert einen Untersuchungsausschuss. Die Verkehrsplanerin Dr. Steiner verteidigt den Zeitplan: Sicherheit gehe vor Tempo, ein falscher Vertrag würde am Ende Millionen kosten. Gleichzeitig bestätigte sie, dass die Baukosten bereits um acht Prozent gestiegen sind. Radverbände zeigen sich enttäuscht; sie verweisen auf andere Städte, in denen ähnliche Projekte schneller umgesetzt wurden. Der Rat will in der nächsten Sitzung über den neuen Zeitplan entscheiden. Ein Baubeginn vor dem kommenden Frühjahr gilt als unwahrscheinlich.",
        questions: [
                            Exercise(id: "de-read-nachricht-radwege-q1", kind: "choice", prompt: "Um wie viel wird der Ausbau verschoben ?", options: ["Mindestens ein Jahr", "Mindestens zwei Jahre", "Drei Monate", "Gar nicht"], answers: ["Mindestens ein Jahr"], explain: "« …wird der geplante Ausbau der Radwege um mindestens ein Jahr verschoben. »"),
                            Exercise(id: "de-read-nachricht-radwege-q2", kind: "written", prompt: "Warum muss neu ausgeschrieben werden ?", options: [], answers: ["die unterlagen waren unvollständig", "die unterlagen waren unvollstaendig", "die baufirma hat die unterlagen unvollständig eingereicht"], explain: "« …habe die Unterlagen unvollständig eingereicht. Deshalb müsse neu ausgeschrieben werden. »"),
                            Exercise(id: "de-read-nachricht-radwege-q3", kind: "choice", prompt: "Was fordert die Opposition ?", options: ["Einen Untersuchungsausschuss", "Mehr Parkplätze", "Den Rücktritt der Planerin", "Schnellere Kosten"], answers: ["Einen Untersuchungsausschuss"], explain: "« Die Opposition spricht von einem verpatzten Projekt und fordert einen Untersuchungsausschuss. »"),
                            Exercise(id: "de-read-nachricht-radwege-q4", kind: "choice", prompt: "Wie viel sind die Baukosten gestiegen ?", options: ["Um acht Prozent", "Um achtzehn Prozent", "Um fünf Prozent", "Gar nicht"], answers: ["Um acht Prozent"], explain: "« …dass die Baukosten bereits um acht Prozent gestiegen sind. »"),
                            Exercise(id: "de-read-nachricht-radwege-q5", kind: "written", prompt: "Wann gilt ein Baubeginn als unwahrscheinlich ?", options: [], answers: ["vor dem kommenden fruehjahr", "vor dem frühjahr", "vor dem kommenden frühjahr"], explain: "« Ein Baubeginn vor dem kommenden Frühjahr gilt als unwahrscheinlich. »")], skills: ["reading:detail", "grammar:passive-intro", "grammar:reported-speech-basic"]),
    ReadingText(id: "en-read-neighbour-note", languageID: "en", title: "A note from your neighbour", level: "A1", topic: "home", unitID: "en-foundations-u2",
        text: "Hi! I'm Marta, from flat 4B. I'm your new neighbour. I'm a nurse, and I work at the city hospital on Mondays, Tuesdays and weekends. My cat's name is Luna — she's grey and very friendly, but please don't feed her! My number is 655 214 890. Call me if there's any problem with the building. The lift is very old, so please close both doors. Thank you — and welcome! Let's have a coffee one day. Marta",
        questions: [
                            Exercise(id: "en-read-neighbour-note-q1", kind: "choice", prompt: "Where is Marta from?", options: ["Flat 4B", "Flat 2A", "The city hospital", "The ground floor"], answers: ["Flat 4B"], explain: "She writes: I'm Marta, from flat 4B."),
                            Exercise(id: "en-read-neighbour-note-q2", kind: "choice", prompt: "When does Marta work?", options: ["Mondays, Tuesdays and weekends", "Only at night", "Every morning", "On Fridays"], answers: ["Mondays, Tuesdays and weekends"], explain: "She works on Mondays, Tuesdays and weekends."),
                            Exercise(id: "en-read-neighbour-note-q3", kind: "written", prompt: "What is her cat's name?", options: [], answers: ["luna"], explain: "Her cat's name is Luna."),
                            Exercise(id: "en-read-neighbour-note-q4", kind: "choice", prompt: "What does she ask about the lift?", options: ["Close both doors", "Don't use it", "Clean it every week", "Call her before using it"], answers: ["Close both doors"], explain: "The lift is old, so please close both doors."),
                            Exercise(id: "en-read-neighbour-note-q5", kind: "choice", prompt: "What does Marta suggest at the end?", options: ["Having a coffee one day", "Feeding the cat", "A building meeting", "Nothing"], answers: ["Having a coffee one day"], explain: "She writes: Let's have a coffee one day.")], skills: ["reading:detail", "reading:scan", "grammar:possessives", "vocab:home"]),
    ReadingText(id: "en-read-bus-12", languageID: "en", title: "Bus number 12", level: "A1", topic: "transport", unitID: "en-foundations-u4",
        text: "BUS 12 — CITY CENTRE — AIRPORT. First bus: 6:10. Last bus: 23:40. Buses leave every 20 minutes from Station Square. A single ticket is 2 euros; a day ticket is 5 euros. You can buy tickets from the driver or from the machine at the stop. The bus to the airport takes about 35 minutes. Big suitcases are free, but dogs need a ticket! The night bus N12 leaves at 1:20 and 3:20, from the same stop. For information, call 900 12 12 12 or ask at the station office (open 7:00–21:00).",
        questions: [
                            Exercise(id: "en-read-bus-12-q1", kind: "written", prompt: "What time is the first bus?", options: [], answers: ["6:10", "at 6:10", "six ten"], explain: "The first bus is at 6:10."),
                            Exercise(id: "en-read-bus-12-q2", kind: "choice", prompt: "How often do buses leave?", options: ["Every 20 minutes", "Every hour", "Every 35 minutes", "Twice a day"], answers: ["Every 20 minutes"], explain: "Buses leave every 20 minutes from Station Square."),
                            Exercise(id: "en-read-bus-12-q3", kind: "choice", prompt: "How much is a day ticket?", options: ["5 euros", "2 euros", "12 euros", "Free"], answers: ["5 euros"], explain: "A day ticket is 5 euros."),
                            Exercise(id: "en-read-bus-12-q4", kind: "choice", prompt: "Who needs a ticket?", options: ["Dogs", "Children", "People with suitcases", "Students"], answers: ["Dogs"], explain: "Suitcases are free, but dogs need a ticket!"),
                            Exercise(id: "en-read-bus-12-q5", kind: "written", prompt: "How long does the airport bus take?", options: [], answers: ["35 minutes", "about 35 minutes", "35 min"], explain: "The bus to the airport takes about 35 minutes.")], skills: ["reading:scan", "reading:detail", "vocab:transport", "listening:number-time"]),
    ReadingText(id: "en-read-annas-week", languageID: "en", title: "Anna's week", level: "A1", topic: "routine", unitID: "en-foundations-u3",
        text: "Anna works in a bookshop from Tuesday to Saturday. On Mondays she doesn't work — she cleans her flat in the morning and plays tennis with her sister in the afternoon. She always gets up at seven and walks to work; the bookshop opens at nine. In the evening she cooks, but on Thursdays she eats with her parents. On Sundays the bookshop is closed, and Anna likes to sleep late, read in the park and call her grandmother. Her grandmother always asks the same question: 'Do you eat enough fruit, Anna?' And Anna always says yes.",
        questions: [
                            Exercise(id: "en-read-annas-week-q1", kind: "choice", prompt: "When does Anna work?", options: ["Tuesday to Saturday", "Monday to Friday", "Every day", "Only weekends"], answers: ["Tuesday to Saturday"], explain: "She works from Tuesday to Saturday."),
                            Exercise(id: "en-read-annas-week-q2", kind: "written", prompt: "What does she do on Monday afternoons?", options: [], answers: ["plays tennis", "she plays tennis", "play tennis with her sister"], explain: "She plays tennis with her sister."),
                            Exercise(id: "en-read-annas-week-q3", kind: "choice", prompt: "How does she go to work?", options: ["She walks", "By bus", "By bike", "By car"], answers: ["She walks"], explain: "She always gets up at seven and walks to work."),
                            Exercise(id: "en-read-annas-week-q4", kind: "choice", prompt: "When does she eat with her parents?", options: ["On Thursdays", "On Mondays", "Every evening", "On Sundays"], answers: ["On Thursdays"], explain: "On Thursdays she eats with her parents."),
                            Exercise(id: "en-read-annas-week-q5", kind: "written", prompt: "Who always asks about fruit?", options: [], answers: ["her grandmother", "grandmother", "her grandma"], explain: "Her grandmother always asks the same question.")], skills: ["reading:detail", "reading:gist", "grammar:frequency-adverbs", "vocab:daily-routine"]),
    ReadingText(id: "en-read-lost-dog", languageID: "en", title: "The poster on the tree", level: "A1", topic: "town",
        text: "LOST DOG — HAVE YOU SEEN TOBY? Toby is a small brown dog. He is eight years old, and he is very friendly, but he is old and a little deaf — he doesn't hear very well. He ran away from Elm Street on Friday evening. He has got a red collar with a phone number. Toby is afraid of loud noises, so please don't chase him. If you see him, please call Sandra on 611 404 404 (day or night). There is a reward: 100 euros. Thank you for helping Toby come home!",
        questions: [
                            Exercise(id: "en-read-lost-dog-q1", kind: "written", prompt: "What is the dog's name?", options: [], answers: ["toby"], explain: "The dog's name is Toby."),
                            Exercise(id: "en-read-lost-dog-q2", kind: "choice", prompt: "What does Toby look like?", options: ["Small and brown", "Big and black", "White and old", "Brown and young"], answers: ["Small and brown"], explain: "Toby is a small brown dog."),
                            Exercise(id: "en-read-lost-dog-q3", kind: "choice", prompt: "Why shouldn't you chase him?", options: ["He is afraid of loud noises", "He is very fast", "He bites", "He is sleeping"], answers: ["He is afraid of loud noises"], explain: "Toby is afraid of loud noises, so please don't chase him."),
                            Exercise(id: "en-read-lost-dog-q4", kind: "written", prompt: "When did he run away?", options: [], answers: ["on friday evening", "friday evening", "friday"], explain: "He ran away from Elm Street on Friday evening."),
                            Exercise(id: "en-read-lost-dog-q5", kind: "choice", prompt: "What does Toby have got?", options: ["A red collar with a phone number", "A blue jacket", "A name tag on his ear", "Nothing"], answers: ["A red collar with a phone number"], explain: "He has got a red collar with a phone number.")], skills: ["reading:detail", "reading:inference", "grammar:can", "vocab:town"]),
    ReadingText(id: "en-read-cafe-menu", languageID: "en", title: "The little café menu", level: "A1", topic: "food",
        text: "THE LITTLE CAFÉ — OPEN 7:30 TO 18:00, MONDAY TO SATURDAY. Coffee: espresso 1.20 — latte 1.80 — hot chocolate 2.50. Breakfast (until 12:00): toast with tomato 2.20 — croissant 1.50 — full breakfast with eggs, bacon and juice 6.90. Lunch: soup of the day 3.50 — cheese sandwich 4.20 — chicken salad 5.90 — today's special: fish and rice 7.50. Cakes: apple cake 2.80 — lemon cake 2.80. We have free water — just ask! Dogs are welcome on the terrace. Card payments from 3 euros. Follow us online for the soup of the day!",
        questions: [
                            Exercise(id: "en-read-cafe-menu-q1", kind: "choice", prompt: "When is the café open?", options: ["7:30 to 18:00, Monday to Saturday", "Every day until midnight", "Only in the morning", "Sundays too"], answers: ["7:30 to 18:00, Monday to Saturday"], explain: "It is open 7:30 to 18:00, Monday to Saturday."),
                            Exercise(id: "en-read-cafe-menu-q2", kind: "written", prompt: "How much is a latte?", options: [], answers: ["1.80", "1,80", "one euro eighty"], explain: "A latte is 1.80."),
                            Exercise(id: "en-read-cafe-menu-q3", kind: "choice", prompt: "What time does breakfast end?", options: ["At 12:00", "At 7:30", "At 18:00", "All day"], answers: ["At 12:00"], explain: "Breakfast is served until 12:00."),
                            Exercise(id: "en-read-cafe-menu-q4", kind: "choice", prompt: "Which lunch costs 7.50?", options: ["Fish and rice", "Cheese sandwich", "Chicken salad", "Soup of the day"], answers: ["Fish and rice"], explain: "Today's special — fish and rice — is 7.50."),
                            Exercise(id: "en-read-cafe-menu-q5", kind: "choice", prompt: "What is free in the café?", options: ["Water", "Coffee", "Cakes", "Wifi"], answers: ["Water"], explain: "We have free water — just ask!")], skills: ["reading:scan", "reading:detail", "vocab:food", "function:order-food"]),
    ReadingText(id: "en-read-postcard-london", languageID: "en", title: "A postcard from London", level: "A1", topic: "travel", unitID: "en-foundations-now",
        text: "Dear Paco, greetings from London! I'm writing this from a small café near the river. It's raining (of course!), so I'm wearing my new blue coat. My friend Clara is sitting next to me and planning our afternoon. This morning we are visiting the British Museum — it's free! — and this afternoon we're walking to Big Ben. In the evening, Clara's cousin is cooking dinner for us. London is expensive, but the museums are free and the parks are beautiful. I'm learning a lot of English every day. See you on Sunday! Elena",
        questions: [
                            Exercise(id: "en-read-postcard-london-q1", kind: "choice", prompt: "Where is Elena writing from?", options: ["A small café near the river", "The British Museum", "Her hotel", "Big Ben"], answers: ["A small café near the river"], explain: "She is writing from a small café near the river."),
                            Exercise(id: "en-read-postcard-london-q2", kind: "written", prompt: "What's the weather doing?", options: [], answers: ["it's raining", "it is raining", "raining"], explain: "It's raining — of course!"),
                            Exercise(id: "en-read-postcard-london-q3", kind: "choice", prompt: "What is she wearing?", options: ["A new blue coat", "An old red coat", "A yellow scarf", "A green hat"], answers: ["A new blue coat"], explain: "She's wearing her new blue coat."),
                            Exercise(id: "en-read-postcard-london-q4", kind: "choice", prompt: "What are they doing this morning?", options: ["Visiting the British Museum", "Cooking dinner", "Walking to Big Ben", "Shopping"], answers: ["Visiting the British Museum"], explain: "This morning they are visiting the British Museum."),
                            Exercise(id: "en-read-postcard-london-q5", kind: "choice", prompt: "Who is cooking dinner?", options: ["Clara's cousin", "Elena", "Clara", "Paco"], answers: ["Clara's cousin"], explain: "In the evening, Clara's cousin is cooking dinner for them.")], skills: ["reading:gist", "grammar:present-continuous", "vocab:travel", "vocab:weather"]),
    ReadingText(id: "en-read-flat-advert", languageID: "en", title: "Two flats, one advert", level: "A2", topic: "home",
        text: "FLAT A — Ríos 14, 3rd floor. 65 m², two bedrooms, one bathroom. Modern kitchen, small balcony, 4th floor without lift. €790/month. Quiet street, 10 minutes from the university by bike. Perfect for students or a young couple. Flat B — Avda del Sol 3, 1st floor WITH lift. 80 m², three bedrooms, bright living room, older building but recently painted. €950/month. 5 minutes from the metro. The agency says: 'Flat A is smaller but cheaper; Flat B is more comfortable and better connected. Flat A gets more sun in the afternoon; Flat B is quieter at night. Both are available from the 1st. Visits on Saturdays, 10:00–14:00. Call 91 555 0199 for more information.'",
        questions: [
                            Exercise(id: "en-read-flat-advert-q1", kind: "choice", prompt: "Which flat is bigger?", options: ["Flat B", "Flat A", "They're the same", "The advert doesn't say"], answers: ["Flat B"], explain: "Flat B is 80 m²; Flat A is 65 m²."),
                            Exercise(id: "en-read-flat-advert-q2", kind: "written", prompt: "How much is Flat A per month?", options: [], answers: ["790 euros", "€790", "790"], explain: "Flat A is €790/month."),
                            Exercise(id: "en-read-flat-advert-q3", kind: "choice", prompt: "Which flat has a lift?", options: ["Flat B", "Flat A", "Neither", "Both"], answers: ["Flat B"], explain: "Flat B is on the 1st floor WITH lift; Flat A is 4th floor without lift."),
                            Exercise(id: "en-read-flat-advert-q4", kind: "choice", prompt: "What does the advert say about Flat A in the afternoon?", options: ["It gets more sun", "It's quieter", "It's hotter", "It's noisier"], answers: ["It gets more sun"], explain: "Flat A gets more sun in the afternoon."),
                            Exercise(id: "en-read-flat-advert-q5", kind: "written", prompt: "When can you visit the flats?", options: [], answers: ["saturdays 10:00-14:00", "on saturdays", "saturday mornings"], explain: "Visits on Saturdays, 10:00–14:00.")], skills: ["reading:detail", "reading:scan", "grammar:comparatives", "grammar:superlatives", "vocab:home"]),
    ReadingText(id: "en-read-weekend-list", languageID: "en", title: "What's on this weekend", level: "A2", topic: "free time",
        text: "CITY WEEKEND GUIDE — SATURDAY & SUNDAY. SATURDAY: Free yoga in Central Park at 9:00 (bring your own mat). Farmers' market at the old port, 8:00–14:00 — the strawberries are the best in the region! River boat tour every hour, €6. SUNDAY: Photography exhibition at the Modern Museum — free entry before 12:00. Charity run: 5 or 10 km, start at 10:30 from the Town Hall. You should register online before Saturday night. Evening open-air cinema at 21:30 — tonight's film is a classic; blankets are free, hot drinks cost €1. Rain plan: all Sunday activities move to the Cultural Centre. Have a great weekend!",
        questions: [
                            Exercise(id: "en-read-weekend-list-q1", kind: "choice", prompt: "What time does free yoga start on Saturday?", options: ["At 9:00", "At 8:00", "At 10:30", "At 21:30"], answers: ["At 9:00"], explain: "Free yoga in Central Park at 9:00."),
                            Exercise(id: "en-read-weekend-list-q2", kind: "written", prompt: "According to the guide, what are the best strawberries in the region?", options: [], answers: ["the farmers market", "farmers market", "the market at the old port"], explain: "The farmers' market strawberries are the best in the region."),
                            Exercise(id: "en-read-weekend-list-q3", kind: "choice", prompt: "When is the museum free?", options: ["Before 12:00 on Sunday", "All weekend", "Never", "On Saturday morning"], answers: ["Before 12:00 on Sunday"], explain: "Free entry before 12:00."),
                            Exercise(id: "en-read-weekend-list-q4", kind: "written", prompt: "What should you do before Saturday night for the charity run?", options: [], answers: ["register online", "register", "you should register online"], explain: "You should register online before Saturday night."),
                            Exercise(id: "en-read-weekend-list-q5", kind: "choice", prompt: "What happens if it rains on Sunday?", options: ["Activities move to the Cultural Centre", "Everything is cancelled", "The cinema closes", "The run is shorter"], answers: ["Activities move to the Cultural Centre"], explain: "The rain plan: all Sunday activities move indoors.")], skills: ["reading:scan", "reading:detail", "grammar:going-to", "grammar:modal-should", "vocab:hobbies"]),
    ReadingText(id: "en-read-doctor-advice", languageID: "en", title: "The doctor's advice", level: "A2", topic: "health",
        text: "Patient information sheet — Tiredness. Are you sleeping badly? Many office workers feel tired all week. Our doctors say: You shouldn't drink coffee after four o'clock. You should go to bed at the same time every night — your body loves routine. You mustn't use screens in bed: the light tells your brain it's daytime. You don't have to sleep eight hours exactly — seven can be enough if it's good sleep. Exercise helps, but not just before bed: a walk at lunchtime is better than a run at ten at night. If you're still tired after two weeks of good habits, you should book an appointment. Sleep well!",
        questions: [
                            Exercise(id: "en-read-doctor-advice-q1", kind: "choice", prompt: "When shouldn't you drink coffee?", options: ["After four o'clock", "In the morning", "Before lunch", "With food"], answers: ["After four o'clock"], explain: "You shouldn't drink coffee after four o'clock."),
                            Exercise(id: "en-read-doctor-advice-q2", kind: "written", prompt: "What mustn't you do in bed?", options: [], answers: ["use screens", "use screens in bed", "look at screens"], explain: "You mustn't use screens in bed."),
                            Exercise(id: "en-read-doctor-advice-q3", kind: "choice", prompt: "How much sleep do you have to get?", options: ["Seven can be enough", "Exactly eight hours", "Nine hours", "Ten hours"], answers: ["Seven can be enough"], explain: "You don't have to sleep eight hours — seven is fine if it's good sleep."),
                            Exercise(id: "en-read-doctor-advice-q4", kind: "choice", prompt: "When is exercise better?", options: ["A walk at lunchtime", "A run at ten at night", "Never", "Just before bed"], answers: ["A walk at lunchtime"], explain: "A walk at lunchtime is better than a run at night."),
                            Exercise(id: "en-read-doctor-advice-q5", kind: "written", prompt: "What should you do if good habits don't work after two weeks?", options: [], answers: ["book an appointment", "book a doctors appointment", "see a doctor", "you should book an appointment"], explain: "You should book an appointment.")], skills: ["reading:detail", "grammar:modal-should", "grammar:modal-must-have-to", "vocab:health"]),
    ReadingText(id: "en-read-complaint-email", languageID: "en", title: "A short complaint email", level: "A2", topic: "problems",
        text: "Subject: Order 4492 — wrong size. Dear Customer Service, I ordered a winter jacket (size M, order 4492) on 3 October, and it arrived on Thursday. Unfortunately, you sent size S instead of M. I checked the box and the label — both say S. I like the jacket and I want to keep it, so I would like to exchange it for the correct size. Should I send the small one back first, or do you send the new one and collect the other? The return service near me is only open in the mornings, so a home collection would be easier. I have to say the delivery was very fast — that part was perfect! I look forward to your reply. Best regards, Daniel Ortiz (customer since 2021)",
        questions: [
                            Exercise(id: "en-read-complaint-email-q1", kind: "choice", prompt: "What was wrong with the order?", options: ["The size", "The colour", "The price", "The delivery day"], answers: ["The size"], explain: "They sent size S instead of M."),
                            Exercise(id: "en-read-complaint-email-q2", kind: "choice", prompt: "What does Daniel want?", options: ["To exchange it for the correct size", "His money back", "A discount", "A different jacket"], answers: ["To exchange it for the correct size"], explain: "He likes the jacket and wants to exchange it."),
                            Exercise(id: "en-read-complaint-email-q3", kind: "written", prompt: "What question does Daniel ask about the return?", options: [], answers: ["should he send it back first", "send back first or home collection", "who collects the small one"], explain: "Should he send it first, or do they collect it?"),
                            Exercise(id: "en-read-complaint-email-q4", kind: "choice", prompt: "What was perfect, according to Daniel?", options: ["The delivery", "The price", "The box", "The label"], answers: ["The delivery"], explain: "He has to admit: the delivery was very fast."),
                            Exercise(id: "en-read-complaint-email-q5", kind: "written", prompt: "How long has Daniel been a customer?", options: [], answers: ["since 2021", "five years", "since two thousand twenty one"], explain: "Customer since 2021.")], skills: ["reading:detail", "function:solve-problems", "grammar:modal-should", "grammar:modal-must-have-to", "writing:email"], exposureSkills: ["grammar:past-simple-irregular"]),
    ReadingText(id: "en-read-hotel-review", languageID: "en", title: "A review: The Glass House Hotel", level: "B1", topic: "travel",
        text: "★★★☆☆ The Glass House Hotel looks spectacular online, and to be fair, the reality is close: the glass roof over the lobby is stunning, and our room, which faced the harbour, had the best view of the week. However, several things annoyed me. Although the website promises 'quiet rooms', ours was above the bar, and the music went on until one in the morning. The breakfast, which is served until ten, ran out of almost everything by nine on both mornings. The staff, who were genuinely kind, tried to help — they moved us on the second night and offered free coffee. Would I return? If they soundproof the bar, yes. If not, I'll pay ten euros more for the hotel next door, which, according to friends, is quieter and includes breakfast.",
        questions: [
                            Exercise(id: "en-read-hotel-review-q1", kind: "choice", prompt: "What did the reviewer love about the room?", options: ["The view of the harbour", "The glass roof", "The bar downstairs", "The breakfast"], answers: ["The view of the harbour"], explain: "Their room faced the harbour and had the best view of the week."),
                            Exercise(id: "en-read-hotel-review-q2", kind: "written", prompt: "Why didn't they sleep well?", options: [], answers: ["the music from the bar", "the bar music", "music until one in the morning"], explain: "The room was above the bar; music until one."),
                            Exercise(id: "en-read-hotel-review-q3", kind: "choice", prompt: "What did the staff do?", options: ["They moved them and offered free coffee", "Nothing", "They refunded the night", "They closed the bar"], answers: ["They moved them and offered free coffee"], explain: "The staff, who were genuinely kind, moved them on the second night."),
                            Exercise(id: "en-read-hotel-review-q4", kind: "choice", prompt: "What will make the reviewer return?", options: ["Soundproofing the bar", "A discount", "A better view", "An earlier breakfast"], answers: ["Soundproofing the bar"], explain: "If they soundproof the bar, yes."),
                            Exercise(id: "en-read-hotel-review-q5", kind: "written", prompt: "According to friends, what is the hotel next door like?", options: [], answers: ["quieter and includes breakfast", "quieter", "quieter and with breakfast included"], explain: "Quieter and includes breakfast.")], skills: ["reading:inference", "grammar:relative-clauses", "grammar:first-conditional", "grammar:connectors", "vocab:travel"]),
    ReadingText(id: "en-read-remote-work", languageID: "en", title: "Is remote work working?", level: "B1", topic: "work",
        text: "Five years ago, most offices insisted that great work needed a shared room. Today, that idea is under review. Companies which moved to hybrid schedules report fewer sick days and lower costs; employees save hours of commuting every week, and many say they are more productive at home. However, the picture is not simple. New employees who have never met their teams in person often feel invisible, and creative work — the kind that grows from accidental corridor conversations — seems harder online. Although younger workers usually prefer flexibility, some admit that home offices blur the line between life and work until answering emails at midnight feels normal again. Perhaps the honest answer is that remote work works when the work is remote-shaped: independent, measured by results, written down. For everything else, the corridor still has value.",
        questions: [
                            Exercise(id: "en-read-remote-work-q1", kind: "choice", prompt: "What do companies with hybrid schedules report?", options: ["Fewer sick days and lower costs", "Higher costs", "Worse productivity", "Nothing"], answers: ["Fewer sick days and lower costs"], explain: "They report fewer sick days and lower costs."),
                            Exercise(id: "en-read-remote-work-q2", kind: "written", prompt: "Who often feels invisible?", options: [], answers: ["new employees", "new employees who have never met their teams", "new people"], explain: "New employees who have never met their teams in person."),
                            Exercise(id: "en-read-remote-work-q3", kind: "choice", prompt: "What kind of work seems harder online?", options: ["Creative work", "Administrative work", "Written work", "Independent work"], answers: ["Creative work"], explain: "Work that grows from corridor conversations seems harder online."),
                            Exercise(id: "en-read-remote-work-q4", kind: "written", prompt: "What negative habit can return with home offices?", options: [], answers: ["answering emails at midnight", "answering emails late at night", "working at midnight"], explain: "Answering emails at midnight can feel normal again."),
                            Exercise(id: "en-read-remote-work-q5", kind: "choice", prompt: "When does remote work work, according to the article?", options: ["When the work is remote-shaped", "Never", "Always", "Only for managers"], answers: ["When the work is remote-shaped"], explain: "Independent, measured by results, written down.")], skills: ["reading:inference", "grammar:relative-clauses", "grammar:connectors", "grammar:present-perfect", "vocab:work"]),
    ReadingText(id: "en-read-missing-keys", languageID: "en", title: "The missing keys", level: "B1", topic: "stories",
        text: "Marta was making coffee when she realised the flat was silent — the specific, heavy silence of a missing object. Her keys, which always lived in the blue bowl by the door, were gone. She looked in her coat, in yesterday's bag, under the sofa where small things liked to disappear. Nothing. While she was searching, her phone buzzed: a message from Diego, her downstairs neighbour. 'Are you missing something shiny? A little thief brought me a present.' His cat, Luna, had a habit of collecting small metal objects, and although Marta had never caught her in the act, the evidence was now clear: three keys, a bottle opener and last winter's missing earring. Marta went downstairs, laughed until her sides hurt, and installed a hook high on the wall. The bowl stayed empty from that day; Luna, however, kept bringing gifts.",
        questions: [
                            Exercise(id: "en-read-missing-keys-q1", kind: "choice", prompt: "What was Marta doing when she noticed the silence?", options: ["Making coffee", "Searching the sofa", "Reading a message", "Going downstairs"], answers: ["Making coffee"], explain: "She was making coffee when she realised."),
                            Exercise(id: "en-read-missing-keys-q2", kind: "written", prompt: "Where did the keys usually live?", options: [], answers: ["in the blue bowl", "the blue bowl by the door", "the blue bowl"], explain: "They always lived in the blue bowl by the door."),
                            Exercise(id: "en-read-missing-keys-q3", kind: "choice", prompt: "Who took the keys?", options: ["Diego's cat", "Diego", "A neighbour", "Nobody knows"], answers: ["Diego's cat"], explain: "Luna, the downstairs cat, collected small metal objects."),
                            Exercise(id: "en-read-missing-keys-q4", kind: "written", prompt: "Name one other thing Luna had taken.", options: [], answers: ["a bottle opener", "an earring", "last winter's missing earring", "three keys"], explain: "Three keys, a bottle opener and an earring."),
                            Exercise(id: "en-read-missing-keys-q5", kind: "choice", prompt: "What was Marta's solution?", options: ["A hook high on the wall", "A new bowl", "A locked box", "She locked Luna out"], answers: ["A hook high on the wall"], explain: "She installed a hook high on the wall."),
                            Exercise(id: "en-read-missing-keys-q6", kind: "choice", prompt: "Did Luna stop bringing gifts?", options: ["No — she kept bringing them", "Yes, immediately", "Yes, after a week", "The text doesn't say"], answers: ["No — she kept bringing them"], explain: "Luna, however, kept bringing gifts.")], skills: ["reading:detail", "grammar:past-continuous", "grammar:relative-clauses", "grammar:connectors", "function:tell-a-story"]),
    ReadingText(id: "en-read-meetup-email", languageID: "en", title: "Planning the alumni meetup", level: "B1", topic: "plans",
        text: "Subject: Alumni meetup — your vote needed! Hi everyone, Great news: 34 of you answered the survey, so we're finally organising the spring meetup. The Terraza del Río, which most of you recommended, has availability on 14 or 21 June. If we choose the 14th, we'll have the terrace to ourselves but we'll have to finish by midnight. If we choose the 21st, it's shared with another group, although the music usually stops earlier. Several of you asked about a pre-dinner walk — if enough people arrive by 19:30, we'll do the river route first (about 40 minutes, flat and easy). Please vote by Friday. If fewer than twenty people vote, we'll postpone to September and I'll donate the deposit to the class fund! Looking forward to it, Bea",
        questions: [
                            Exercise(id: "en-read-meetup-email-q1", kind: "choice", prompt: "Which venue did most people recommend?", options: ["Terraza del Río", "The class fund", "The river route", "A shared hall"], answers: ["Terraza del Río"], explain: "The Terraza del Río, which most of you recommended."),
                            Exercise(id: "en-read-meetup-email-q2", kind: "choice", prompt: "What is the downside of the 14th?", options: ["They must finish by midnight", "Another group shares it", "No terrace", "It's in September"], answers: ["They must finish by midnight"], explain: "On the 14th they have the terrace to themselves but finish by midnight."),
                            Exercise(id: "en-read-meetup-email-q3", kind: "written", prompt: "What do they plan to do if enough people arrive by 19:30?", options: [], answers: ["the river route", "do the river route first", "walk the river route"], explain: "They'll do the river route first."),
                            Exercise(id: "en-read-meetup-email-q4", kind: "choice", prompt: "What happens if fewer than twenty people vote?", options: ["The meetup moves to September", "Bea chooses the date", "The venue decides", "Nothing"], answers: ["The meetup moves to September"], explain: "They'll postpone to September and donate the deposit."),
                            Exercise(id: "en-read-meetup-email-q5", kind: "written", prompt: "How long is the river walk?", options: [], answers: ["about 40 minutes", "40 minutes", "forty minutes"], explain: "About 40 minutes, flat and easy.")], skills: ["reading:detail", "grammar:first-conditional", "grammar:connectors", "writing:email"]),
    ReadingText(id: "en-read-ai-emails-debate", languageID: "en", title: "Should AI write our emails?", level: "B2", topic: "work",
        text: "Last quarter, our company quietly enabled an AI assistant for all internal email. The results were measured, and they are worth reporting precisely. Response times improved by roughly a third, and — perhaps surprisingly — politeness increased: messages drafted by the assistant contain fewer blunt openings and more complete sentences. However, two problems are emerging. First, readers are starting to discount the politeness; when everyone sounds courteous, courtesy stops carrying information. Second, and more seriously, responsibility is blurring. When a wrong figure was sent to a client last month, three people said some version of 'the assistant wrote it.' The tool was not to blame, of course — the signature was. My position is therefore narrow but firm: let the assistant draft, but the name at the bottom owns every word. We are testing a one-line disclosure at the end of assisted emails, and if trust metrics hold, we will keep it. If they do not, we will rethink — in our own words.",
        questions: [
                            Exercise(id: "en-read-ai-emails-debate-q1", kind: "written", prompt: "By how much did response times improve?", options: [], answers: ["roughly a third", "about a third", "a third"], explain: "Response times improved by roughly a third."),
                            Exercise(id: "en-read-ai-emails-debate-q2", kind: "choice", prompt: "What surprising effect did the assistant have?", options: ["Politeness increased", "Emails got shorter", "People wrote less", "Costs fell"], answers: ["Politeness increased"], explain: "Messages contained fewer blunt openings and more complete sentences."),
                            Exercise(id: "en-read-ai-emails-debate-q3", kind: "choice", prompt: "What happens when everyone sounds courteous?", options: ["Courtesy stops carrying information", "Emails get longer", "Nothing", "People write more"], answers: ["Courtesy stops carrying information"], explain: "Discounted politeness carries less meaning."),
                            Exercise(id: "en-read-ai-emails-debate-q4", kind: "choice", prompt: "What is the author's firm position?", options: ["The signature owns every word", "Ban the assistant", "AI should write everything", "No disclosure needed"], answers: ["The signature owns every word"], explain: "Let it draft, but the name at the bottom owns every word."),
                            Exercise(id: "en-read-ai-emails-debate-q5", kind: "written", prompt: "What will they do if trust metrics do not hold?", options: [], answers: ["rethink", "they will rethink in their own words", "rethink the policy"], explain: "If they do not, they will rethink — in their own words.")], skills: ["reading:inference", "grammar:passive-intro", "grammar:connectors", "grammar:first-conditional", "writing:argument"]),
    ReadingText(id: "en-read-market-report", languageID: "en", title: "Quarter in brief: the coffee market", level: "B2", topic: "business",
        text: "Summary for internal circulation — Q3. Prices rose considerably in the first half of the quarter, driven by weather rather than demand: the frost in July affected the two largest producing regions, which together account for roughly 55% of exports. Demand, by contrast, was flat. Supermarket own-brand lines were the least affected, arguably because their contracts are fixed annually; speciality roasters, which buy on the spot market, reported increases of up to forty per cent. It is widely believed that small cafés absorb such increases poorly, and our survey offers some support: 62% said they would rather reduce opening hours than raise the price of an espresso. Looking ahead, futures suggest a partial correction by December, although this depends on rainfall in August. We therefore recommend hedging half of Q4 volume now and reviewing the remainder in October. As ever, this report is a snapshot, not a guarantee.",
        questions: [
                            Exercise(id: "en-read-market-report-q1", kind: "choice", prompt: "What drove prices up?", options: ["Weather", "Demand", "New cafés", "Export taxes"], answers: ["Weather"], explain: "The July frost, not demand — demand was flat."),
                            Exercise(id: "en-read-market-report-q2", kind: "written", prompt: "How much of exports do the two largest regions account for?", options: [], answers: ["roughly 55%", "55%", "about 55 percent"], explain: "Roughly 55% of exports."),
                            Exercise(id: "en-read-market-report-q3", kind: "choice", prompt: "Which buyers were least affected?", options: ["Supermarket own brands", "Speciality roasters", "Small cafés", "Futures traders"], answers: ["Supermarket own brands"], explain: "Arguably because their contracts are fixed annually."),
                            Exercise(id: "en-read-market-report-q4", kind: "written", prompt: "What would 62% of small cafés rather do?", options: [], answers: ["Reduce opening hours"], explain: "Rather than raise the price of an espresso."),
                            Exercise(id: "en-read-market-report-q5", kind: "choice", prompt: "What does the report recommend for Q4?", options: ["Hedging half the volume now", "Waiting until December", "Buying nothing", "Raising prices by 40%"], answers: ["Hedging half the volume now"], explain: "Hedge half now, review the rest in October.")], skills: ["reading:inference", "grammar:passive-intro", "grammar:relative-clauses", "grammar:connectors", "function:express-opinion"]),
    ReadingText(id: "en-read-op-ed-cities", languageID: "en", title: "Op-ed: the fifteen-minute fantasy", level: "C1", topic: "town",
        text: "The fifteen-minute city is, depending on who you ask, the future of urban life or a conspiracy with better branding. Strip away the noise, however, and the concept is almost disappointingly modest: housing, work, school and groceries within a short walk. That this modesty has been received as tyranny says less about urbanism than about the era in which it landed. Critics are right about one thing, though — proximity is a luxury good. The neighbourhoods that already deliver it are the most expensive in every city that measures, and a plan that paints a café on a map does not lower the rent. Arguably, then, the real fifteen-minute policy is not zoning but housing: build where people want to live, and the walk to the bakery takes care of itself. None of this makes the idea wrong. It makes it insufficient — which, in a field allergic to nuance, is already an unpopular position.",
        questions: [
                            Exercise(id: "en-read-op-ed-cities-q1", kind: "choice", prompt: "How does the author characterise the fifteen-minute city concept itself?", options: ["Almost disappointingly modest", "A conspiracy", "The future of urban life", "Tyranny"], answers: ["Almost disappointingly modest"], explain: "Strip away the noise and the concept is almost disappointingly modest."),
                            Exercise(id: "en-read-op-ed-cities-q2", kind: "choice", prompt: "What do critics get right, according to the author?", options: ["Proximity is a luxury good", "Zoning is evil", "Cafés ruin cities", "Nothing"], answers: ["Proximity is a luxury good"], explain: "Critics are right about one thing: the neighbourhoods that deliver it are the most expensive."),
                            Exercise(id: "en-read-op-ed-cities-q3", kind: "written", prompt: "What does the author call the real fifteen-minute policy?", options: [], answers: ["housing", "build where people want to live"], explain: "Not zoning but housing: build where people want to live."),
                            Exercise(id: "en-read-op-ed-cities-q4", kind: "written", prompt: "What is the author's final judgement of the idea?", options: [], answers: ["insufficient, not wrong", "it makes the idea insufficient"], explain: "It makes the idea insufficient — which is already unpopular."),
                            Exercise(id: "en-read-op-ed-cities-q5", kind: "choice", prompt: "What does 'a field allergic to nuance' imply?", options: ["Urbanism debates reject subtle positions", "Urbanists have allergies", "Cities cause allergies", "Nuance is common"], answers: ["Urbanism debates reject subtle positions"], explain: "Allergic to nuance = the field dislikes intermediate positions.")], skills: ["reading:inference", "grammar:connectors", "function:express-opinion", "writing:argument", "vocab:town"]),
    ReadingText(id: "en-read-policy-memo", languageID: "en", title: "Internal memo: hybrid policy review", level: "C1", topic: "work",
        text: "MEMO — For internal circulation. Re: Hybrid working policy, phase two review. 1. Purpose. This memo summarises the findings of the phase-two review and sets out recommendations for the coming financial year. 2. Findings. Office attendance has averaged 2.3 days per week against a target of three, a shortfall attributable primarily to Wednesdays, which function in practice as a de facto remote day. Cross-team collaboration, as measured by shared project hours, has declined 12% year on year; within-team collaboration is unchanged. Exit interviews cite flexibility as the single most valued benefit (cited by 71% of leavers, compared with 34% for compensation). 3. Recommendations. It is recommended that: (a) Wednesday be designated a full on-site day with team-led programming; (b) the target be revised to an average, not a minimum; (c) the policy be reviewed again in twelve months. 4. Caveat. Attendance data was collected via badge swipes and may undercount presence in non-badged areas.",
        questions: [
                            Exercise(id: "en-read-policy-memo-q1", kind: "written", prompt: "What is the average office attendance against the target?", options: [], answers: ["2.3 days per week against a target of three", "2.3 days", "2,3 days"], explain: "2.3 days per week against a target of three."),
                            Exercise(id: "en-read-policy-memo-q2", kind: "choice", prompt: "What is the primary cause of the shortfall?", options: ["Wednesdays functioning as a remote day", "Bad weather", "The badge system", "Low pay"], answers: ["Wednesdays functioning as a remote day"], explain: "A shortfall attributable primarily to Wednesdays."),
                            Exercise(id: "en-read-policy-memo-q3", kind: "choice", prompt: "What do exit interviews cite as the most valued benefit?", options: ["Flexibility", "Compensation", "Laptops", "Wednesdays"], answers: ["Flexibility"], explain: "Flexibility: 71% of leavers, compared with 34% for compensation."),
                            Exercise(id: "en-read-policy-memo-q4", kind: "written", prompt: "Name one of the three recommendations.", options: [], answers: ["wednesday be designated a full on-site day", "the target be revised to an average", "the policy be reviewed again in twelve months"], explain: "Any of (a), (b) or (c)."),
                            Exercise(id: "en-read-policy-memo-q5", kind: "choice", prompt: "What caveat does the memo admit?", options: ["Badge data may undercount presence", "The survey was fake", "There is no data", "The target was met"], answers: ["Badge data may undercount presence"], explain: "Badge swipes miss non-badged areas.")], skills: ["reading:scan", "reading:detail", "grammar:passive-intro", "vocab:work", "writing:email"]),
    ReadingText(id: "en-read-neighbourhood-blog", languageID: "en", title: "Neighbourhood notes: Maple Street", level: "A1", topic: "town",
        text: "Welcome to Maple Street! Our street is small but friendly. There is a bakery on the corner — the bread is very good. There are two schools and a small park with ten trees. There isn't a cinema, but the library is open on Saturdays. The chemist's is next to the park. Everything is near the bus stop. Our neighbours are friendly and quiet. On Saturdays there is a small market with fruit and flowers. Come and visit!",
        questions: [
                            Exercise(id: "en-read-neighbourhood-blog-q1", kind: "choice", prompt: "What is on the corner?", options: ["A bakery", "A cinema", "A school", "A market"], answers: ["A bakery"], explain: "There is a bakery on the corner."),
                            Exercise(id: "en-read-neighbourhood-blog-q2", kind: "written", prompt: "How many trees are in the park?", options: [], answers: ["ten", "10"], explain: "A small park with ten trees."),
                            Exercise(id: "en-read-neighbourhood-blog-q3", kind: "choice", prompt: "When is the library open?", options: ["On Saturdays", "Every day", "Never", "On Sundays"], answers: ["On Saturdays"], explain: "The library is open on Saturdays."),
                            Exercise(id: "en-read-neighbourhood-blog-q4", kind: "choice", prompt: "Where is the chemist's?", options: ["Next to the park", "On the corner", "Near the school", "Far away"], answers: ["Next to the park"], explain: "The chemist's is next to the park."),
                            Exercise(id: "en-read-neighbourhood-blog-q5", kind: "choice", prompt: "What is there on Saturdays?", options: ["A small market", "A cinema", "A party", "Nothing"], answers: ["A small market"], explain: "Fruit and flowers — the Saturday market.")], skills: ["vocab:town", "grammar:there-is-are", "reading:detail", "function:ask-simple-questions"]),
    ReadingText(id: "en-read-tuscany-note", languageID: "en", title: "A very short travel story", level: "B1", topic: "travel",
        text: "The lock wouldn't turn. That was the first sign. My Airbnb host had sent four codes for one door, and none of them worked. It was 30 degrees, my phone had 4% battery, and a man with a dog was watching me from a window. I typed a message to the host: 'I'm outside, the codes don't work.' Three dots. Nothing. Ten minutes later the dog man opened the door downstairs. 'You must be the Tuscany guest,' he said, in perfect English. 'My daughter manages the flat. Come up, have some water.' By the time I got inside, we had laughed about the codes twice, and he had given me two plums from his tree. Some arrivals are better than the photos.",
        questions: [
                            Exercise(id: "en-read-tuscany-note-q1", kind: "choice", prompt: "What is the first sign of trouble?", options: ["The lock wouldn't turn", "The host's message", "The dog", "The heat"], answers: ["The lock wouldn't turn"], explain: "Open in the middle: the lock wouldn't turn."),
                            Exercise(id: "en-read-tuscany-note-q2", kind: "written", prompt: "How many codes did the host send?", options: [], answers: ["four", "4"], explain: "Four codes for one door."),
                            Exercise(id: "en-read-tuscany-note-q3", kind: "choice", prompt: "What was the phone's battery?", options: ["4%", "40%", "Full", "Dead"], answers: ["4%"], explain: "My phone had 4% battery."),
                            Exercise(id: "en-read-tuscany-note-q4", kind: "written", prompt: "What did the dog man give the guest?", options: [], answers: ["two plums", "plums", "some plums"], explain: "Two plums from his tree."),
                            Exercise(id: "en-read-tuscany-note-q5", kind: "choice", prompt: "What is the closing thought?", options: ["Some arrivals are better than the photos", "Never use Airbnb", "Tuscany is far", "Dogs are friendly"], answers: ["Some arrivals are better than the photos"], explain: "One line, reflective, light.")], skills: ["reading:inference", "grammar:past-continuous", "function:tell-a-story", "grammar:connectors", "writing:story"]),
    ReadingText(id: "en-read-opinion-ai-art", languageID: "en", title: "Opinion: AI art is still art", level: "B2", topic: "work",
        text: "The argument against AI art is always the same: a machine cannot feel, therefore it cannot create. But this argument proves too much. If feeling is the requirement, then we must also reject photography (the camera does not feel), digital painting (the software does not feel) and, arguably, most commissioned work (the painter does not always feel either). What matters is not the tool but the intention behind it. A person who writes a prompt, curates the output, revises, and presents the result is making choices. Those choices may be good or bad — that is a separate question. But they are choices, and choices are the raw material of art. The real threat is not AI art; it is the flood of mediocre AI art that drowns the genuinely interesting work. The solution is curation, not prohibition.",
        questions: [
                            Exercise(id: "en-read-opinion-ai-art-q1", kind: "choice", prompt: "What is the standard argument against AI art?", options: ["A machine cannot feel, so it cannot create", "AI art is too expensive", "AI art is too fast", "Nobody likes it"], answers: ["A machine cannot feel, so it cannot create"], explain: "A machine cannot feel, therefore it cannot create."),
                            Exercise(id: "en-read-opinion-ai-art-q2", kind: "choice", prompt: "What does the author say the argument proves too much?", options: ["It would also reject photography and digital painting", "It proves AI is bad", "It proves artists are wrong", "Nothing"], answers: ["It would also reject photography and digital painting"], explain: "The camera doesn't feel either."),
                            Exercise(id: "en-read-opinion-ai-art-q3", kind: "written", prompt: "What matters more than the tool?", options: [], answers: ["the intention behind it"], explain: "What matters is the intention, not the tool."),
                            Exercise(id: "en-read-opinion-ai-art-q4", kind: "written", prompt: "What are the raw material of art?", options: [], answers: ["choices"], explain: "Choices are the raw material of art."),
                            Exercise(id: "en-read-opinion-ai-art-q5", kind: "choice", prompt: "What is the real threat?", options: ["The flood of mediocre AI art", "AI art itself", "Prohibition", "Traditional artists"], answers: ["The flood of mediocre AI art"], explain: "The flood drowns the genuinely interesting work."),
                            Exercise(id: "en-read-opinion-ai-art-q6", kind: "choice", prompt: "What solution does the author propose?", options: ["Curation, not prohibition", "Banning AI art", "More AI art", "Higher prices"], answers: ["Curation, not prohibition"], explain: "Curation, not prohibition.")], skills: ["reading:inference", "grammar:connectors", "function:express-opinion", "writing:argument", "grammar:passive-intro"]),
    ReadingText(id: "en-read-policy-report", languageID: "en", title: "Policy report: libraries in the digital age", level: "C1", topic: "work",
        text: "1. Scope. This report examines the role of public libraries in municipalities with populations exceeding 50,000, drawing on data from 340 institutions across 12 countries collected between 2022 and 2025. 2. Principal findings. Contrary to widespread assumptions, circulation of physical books has declined by only 8% since 2022, while attendance at non-book events (workshops, language exchanges, coding clubs) has increased by 210% over the same period. Libraries that rebranded as 'community hubs' saw a 34% increase in first-time visitors; those that maintained a traditional focus saw a 14% decrease. It should be noted, however, that the rebranding group also received 40% more funding on average, making causality difficult to establish. 3. Limitations. The data excludes rural libraries and does not distinguish between scheduled and walk-in attendance. 4. Recommendation. Municipalities should fund libraries as social infrastructure rather than as book warehouses, and should commission a follow-up study with better attendance methodology.",
        questions: [
                            Exercise(id: "en-read-policy-report-q1", kind: "choice", prompt: "How much has physical book circulation declined?", options: ["8% since 2022", "80% since 2022", "It has increased", "It has not changed"], answers: ["8% since 2022"], explain: "Contrary to assumptions, only 8% decline."),
                            Exercise(id: "en-read-policy-report-q2", kind: "written", prompt: "By how much have non-book events increased?", options: [], answers: ["210%"], explain: "Attendance at non-book events has increased by 210%."),
                            Exercise(id: "en-read-policy-report-q3", kind: "choice", prompt: "What happened to libraries that rebranded as community hubs?", options: ["34% more first-time visitors", "34% fewer visitors", "No change", "They closed"], answers: ["34% more first-time visitors"], explain: "A 34% increase in first-time visitors."),
                            Exercise(id: "en-read-policy-report-q4", kind: "choice", prompt: "What limitation does the report admit?", options: ["Rebranding libraries received 40% more funding", "The data is fake", "Libraries refused to participate", "No limitation"], answers: ["Rebranding libraries received 40% more funding"], explain: "More funding makes causality difficult to establish."),
                            Exercise(id: "en-read-policy-report-q5", kind: "choice", prompt: "What does the report recommend?", options: ["Fund libraries as social infrastructure", "Close libraries", "Buy more books", "Stop funding"], answers: ["Fund libraries as social infrastructure"], explain: "Fund as social infrastructure, not book warehouses."),
                            Exercise(id: "en-read-policy-report-q6", kind: "written", prompt: "What data does the report exclude?", options: [], answers: ["rural libraries"], explain: "The data excludes rural libraries.")], skills: ["reading:inference", "reading:scan", "grammar:passive-intro", "grammar:connectors", "writing:argument"]),
    ReadingText(id: "es-read-grupo-caminata", languageID: "es", title: "El grupo de caminata", level: "A1", topic: "salud", unitID: "es-foundations-u2",
        text: "Los martes, el barrio organiza una caminata gratis. Empieza a las nueve en la plaza y termina en el río. El grupo es mixto: hay estudiantes, familias y jubilados. Nadie corre; la idea es caminar y hablar. Al final, los que quieren desayunan juntos en un bar del mercado. Marta va desde hace un mes y ya tiene tres amigos nuevos. Dice que es la hora más tranquila de su semana.",
        questions: [
                            Exercise(id: "es-read-grupo-caminata-q1", kind: "choice", prompt: "¿Cuándo es la caminata?", options: ["Los martes", "Los lunes", "Los sábados", "Todos los días"], answers: ["Los martes"], explain: "Los martes, el barrio organiza una caminata gratis."),
                            Exercise(id: "es-read-grupo-caminata-q2", kind: "written", prompt: "¿A qué hora empieza?", options: [], answers: ["a las nueve", "las nueve", "nueve"], explain: "Empieza a las nueve en la plaza."),
                            Exercise(id: "es-read-grupo-caminata-q3", kind: "choice", prompt: "¿Quién va al grupo?", options: ["Estudiantes, familias y jubilados", "Solo estudiantes", "Solo jubilados", "Solo familias"], answers: ["Estudiantes, familias y jubilados"], explain: "El grupo es mixto."),
                            Exercise(id: "es-read-grupo-caminata-q4", kind: "choice", prompt: "¿Qué hacen al final los que quieren?", options: ["Desayunan juntos", "Corren al río", "Vuelven a casa", "Toman el autobús"], answers: ["Desayunan juntos"], explain: "Desayunan juntos en un bar del mercado."),
                            Exercise(id: "es-read-grupo-caminata-q5", kind: "written", prompt: "¿Cuánto tiempo lleva Marta?", options: [], answers: ["un mes", "1 mes"], explain: "Marta va desde hace un mes.")], skills: ["reading:detail", "reading:scan", "grammar:present-simple", "vocab:daily-routine"]),
    ReadingText(id: "es-read-piso-luz", languageID: "es", title: "El anuncio del piso", level: "A2", topic: "pisos", unitID: "es-foundations-u7",
        text: "Piso luminoso de dos habitaciones en alquiler desde septiembre. Está en la tercera planta, con ascensor, y tiene un balcón que da al patio, así que es tranquilo. El salón es más grande que la cocina, pero la cocina tiene ventana. El barrio tiene mercado los sábados y la parada del metro está a cinco minutos. No es el más barato de la zona, pero es el mejor iluminado. Se pide un mes de fianza y se prefiere a alguien que trabaje desde casa, como los dueños actuales.",
        questions: [
                            Exercise(id: "es-read-piso-luz-q1", kind: "choice", prompt: "¿Cuándo está disponible?", options: ["Desde septiembre", "Desde agosto", "Ahora mismo", "En enero"], answers: ["Desde septiembre"], explain: "En alquiler desde septiembre."),
                            Exercise(id: "es-read-piso-luz-q2", kind: "choice", prompt: "¿Por qué es tranquilo?", options: ["Da al patio", "Está en la planta baja", "No tiene vecinos", "Está en el campo"], answers: ["Da al patio"], explain: "El balcón da al patio, así que es tranquilo."),
                            Exercise(id: "es-read-piso-luz-q3", kind: "written", prompt: "¿A cuántos minutos está el metro?", options: [], answers: ["cinco minutos", "5 minutos", "cinco"], explain: "La parada del metro está a cinco minutos."),
                            Exercise(id: "es-read-piso-luz-q4", kind: "choice", prompt: "¿Cómo es comparado con la zona?", options: ["No es el más barato, pero sí el mejor iluminado", "Es el más barato", "Es el peor iluminado", "Es el más pequeño"], answers: ["No es el más barato, pero sí el mejor iluminado"], explain: "No es el más barato de la zona, pero es el mejor iluminado."),
                            Exercise(id: "es-read-piso-luz-q5", kind: "choice", prompt: "¿A quién prefieren los dueños?", options: ["A alguien que trabaje desde casa", "A estudiantes", "A familias con niños", "A jubilados"], answers: ["A alguien que trabaje desde casa"], explain: "Se prefiere a alguien que trabaje desde casa.")], skills: ["reading:detail", "reading:inference", "grammar:comparatives"], exposureSkills: ["grammar:superlatives"]),
    ReadingText(id: "es-read-viaje-inolvidable", languageID: "es", title: "El viaje inolvidable", level: "B1", topic: "viajes", unitID: "es-foundations-u5",
        text: "El verano pasado hice el viaje que más había soñado: quince días en Perú. Ya había visitado México y Argentina, pero Sudamérica todavía me sorprendió. El tercer día subí al Machu Picchu. Había niebla, así que al principio no se veía nada. Después, poco a poco, salió el sol y apareció la ciudad entera. No dije nada; me quedé mirando. Conocí a una familia de Cusco en el tren de vuelta, y me invitaron a cenar. «Los viajeros siempre dicen lo mismo», se rió la abuela, «pero esta sopa es de verdad». Tenía razón: fue la mejor cena del viaje. Desde entonces, cada vez que alguien pregunta por un destino, yo digo Perú.",
        questions: [
                            Exercise(id: "es-read-viaje-inolvidable-q1", kind: "choice", prompt: "¿Cuánto duró el viaje?", options: ["Quince días", "Diez días", "Un mes", "Tres días"], answers: ["Quince días"], explain: "Quince días en Perú."),
                            Exercise(id: "es-read-viaje-inolvidable-q2", kind: "written", prompt: "¿Qué países había visitado antes?", options: [], answers: ["mexico y argentina", "méxico y argentina"], explain: "Ya había visitado México y Argentina."),
                            Exercise(id: "es-read-viaje-inolvidable-q3", kind: "choice", prompt: "¿Por qué no se veía nada al principio?", options: ["Había niebla", "Estaba cerrado", "Llovía mucho", "Era de noche"], answers: ["Había niebla"], explain: "Había niebla, así que al principio no se veía nada."),
                            Exercise(id: "es-read-viaje-inolvidable-q4", kind: "choice", prompt: "¿Con quién cenó el narrador?", options: ["Con una familia de Cusco", "Con la abuela del hotel", "Solo", "Con amigos del tren"], answers: ["Con una familia de Cusco"], explain: "Conocí a una familia de Cusco y me invitaron a cenar."),
                            Exercise(id: "es-read-viaje-inolvidable-q5", kind: "written", prompt: "¿Qué dice ahora cuando le preguntan por un destino?", options: [], answers: ["peru", "perú", "yo digo peru", "digo peru"], explain: "Cada vez que alguien pregunta, yo digo Perú.")], skills: ["reading:inference", "grammar:present-perfect", "grammar:connectors", "vocab:travel"]),
    ReadingText(id: "es-read-columna-peatonal", languageID: "es", title: "Columna: peatonalicemos", level: "B2", topic: "opinión", unitID: "es-foundations-u9",
        text: "Creo que deberíamos peatonalizar el centro. Por un lado, bajaría el ruido: los vecinos de la plaza llevan años pidiendo silencio. Por otro lado, bajaría la contaminación, que ya supera los límites legales. Es cierto que el comercio teme perder clientes, pero los datos de otras ciudades dicen lo contrario: donde el coche desaparece, la gente camina más y compra más. La empresa cuyo informe publicaron el mes pasado calculó un 15 % más de ventas en calles sin tráfico. Por todo ello, defiendo la medida: si tuviéramos el valor de probarlo un año, no querríamos volver atrás.",
        questions: [
                            Exercise(id: "es-read-columna-peatonal-q1", kind: "choice", prompt: "¿Cuál es la tesis de la columna ?", options: ["Peatonalizar el centro", "Ampliar la autopista", "Prohibir bicis", "Construir un parking"], answers: ["Peatonalizar el centro"], explain: "« Creo que deberíamos peatonalizar el centro »."),
                            Exercise(id: "es-read-columna-peatonal-q2", kind: "written", prompt: "¿Qué supera los límites legales ?", options: [], answers: ["la contaminacion", "la contaminación"], explain: "La contaminación ya supera los límites legales."),
                            Exercise(id: "es-read-columna-peatonal-q3", kind: "choice", prompt: "¿Qué teme el comercio ?", options: ["Perder clientes", "Pagar más impuestos", "Cerrar en verano", "Mudar de ciudad"], answers: ["Perder clientes"], explain: "El comercio teme perder clientes."),
                            Exercise(id: "es-read-columna-peatonal-q4", kind: "written", prompt: "¿Cuánto más venderían las calles sin tráfico ?", options: [], answers: ["15%", "un 15%", "quince por ciento", "15 por ciento"], explain: "Un 15 % más de ventas."),
                            Exercise(id: "es-read-columna-peatonal-q5", kind: "choice", prompt: "¿Qué propone la autora al final ?", options: ["Probarlo un año", "Olvidar el plan", "Multar más", "Votar de nuevo"], answers: ["Probarlo un año"], explain: "« Si tuviéramos el valor de probarlo un año ».")], skills: ["reading:inference", "writing:argument", "grammar:connectors", "grammar:second-conditional"]),
    ReadingText(id: "es-read-ensayo-ciudad", languageID: "es", title: "La ciudad de quince minutos", level: "C1", topic: "opinión", unitID: "es-foundations-u10",
        text: "La ciudad de los quince minutos es, por así decirlo, una promesa modesta: nada de coches voladores, solo vida cercana. Para empezar, acercar los servicios reduce el desplazamiento obligatorio; en segundo lugar, la calle recupera su papel de lugar de encuentro. No obstante, el ensayo tiene un punto ciego: quien no puede pagarse un piso en el centro queda fuera del mapa. Desde mi punto de vista, la medida solo funciona si va acompañada de vivienda asequible; de lo contrario, es un lujo con lema. Por otra parte, no todo es economía: hay vecindarios que ya viven a escala humana sin haberlo planeado. En resumen, merece la pena intentarlo, siempre que la palabra clave no sea « minutos », sino « vecindario ».",
        questions: [
                            Exercise(id: "es-read-ensayo-ciudad-q1", kind: "choice", prompt: "¿Qué riesgo ve el autor en la medida ?", options: ["Que puede volverse un lujo", "Que promete coches voladores", "Que es demasiado modesta", "Que odia los minutos"], answers: ["Que puede volverse un lujo"], explain: "Sin vivienda asequible, « es un lujo con lema »."),
                            Exercise(id: "es-read-ensayo-ciudad-q2", kind: "written", prompt: "¿Qué necesita la medida para funcionar, según el autor ?", options: [], answers: ["vivienda asequible", "la vivienda asequible"], explain: "« Solo funciona si va acompañada de vivienda asequible »."),
                            Exercise(id: "es-read-ensayo-ciudad-q3", kind: "choice", prompt: "¿Cuál es la palabra clave final del ensayo ?", options: ["Vecindario", "Minutos", "Lema", "Mapa"], answers: ["Vecindario"], explain: "« No sea 'minutos', sino 'vecindario' »."),
                            Exercise(id: "es-read-ensayo-ciudad-q4", kind: "choice", prompt: "¿Qué ejemplo da de vida ya a escala humana ?", options: ["Vecindarios no planificados", "El centro pagado", "Los coches voladores", "El desplazamiento obligatorio"], answers: ["Vecindarios no planificados"], explain: "« Hay vecindarios que ya viven a escala humana sin haberlo planeado »."),
                            Exercise(id: "es-read-ensayo-ciudad-q5", kind: "written", prompt: "¿Cómo califica el autor la promesa de los quince minutos ?", options: [], answers: ["modesta", "una promesa modesta", "promesa modesta"], explain: "« Una promesa modesta », dice desde el principio.")], skills: ["reading:inference", "writing:argument", "grammar:connectors", "vocab:collocations"]),
    ReadingText(id: "es-read-carta-directiva", languageID: "es", title: "Carta de la dirección", level: "C1", topic: "empresa", unitID: "es-foundations-u10",
        text: "Estimado equipo: les escribimos para compartir la reorganización del próximo trimestre. Para empezar, agradecerles el esfuerzo del último ciclo: los indicadores han mejorado notablemente. No obstante, el contexto exige ajustes. En primer lugar, consolidaremos los dos departamentos comerciales en una sola dirección; en segundo lugar, el trabajo en remoto quedará limitado a dos días semanales, salvo acuerdo contrario con el responsable de cada área. Somos conscientes de que, en cierto modo, la medida reduce la autonomía ganada; por otra parte, evita una reducción de plantilla, que era la alternativa sobre la mesa. Les convocamos a una asamblea el jueves a las once para responder a sus preguntas. Quedamos a su disposición. La dirección.",
        questions: [
                            Exercise(id: "es-read-carta-directiva-q1", kind: "choice", prompt: "¿Qué cambia en el trabajo en remoto ?", options: ["Dos días semanales como máximo", "Se prohibe del todo", "Pasa a ser obligatorio cinco días", "Depende de cada ministerio"], answers: ["Dos días semanales como máximo"], explain: "« Quedará limitado a dos días semanales »."),
                            Exercise(id: "es-read-carta-directiva-q2", kind: "choice", prompt: "¿Qué evita la dirección con la medida ?", options: ["Una reducción de plantilla", "Una asamblea el jueves", "La flexibilidad semanal", "Los indicadores del ciclo"], answers: ["Una reducción de plantilla"], explain: "« Por otra parte, evita una reducción de plantilla »."),
                            Exercise(id: "es-read-carta-directiva-q3", kind: "written", prompt: "¿Cuándo convoca la dirección a la asamblea ?", options: [], answers: ["el jueves a las once", "jueves a las once", "el jueves"], explain: "Les convocan el jueves a las once."),
                            Exercise(id: "es-read-carta-directiva-q4", kind: "choice", prompt: "¿Qué reconoce la dirección sobre la medida ?", options: ["Que reduce la autonomía en cierto modo", "Que sube los indicadores", "Que crea dos direcciones nuevas", "Que no hace falta ninguna medida"], answers: ["Que reduce la autonomía en cierto modo"], explain: "« Somos conscientes de que, en cierto modo, reduce la autonomía ganada »."),
                            Exercise(id: "es-read-carta-directiva-q5", kind: "written", prompt: "¿Quién firma la carta ?", options: [], answers: ["la direccion", "la dirección"], explain: "Firma « La dirección ».")], skills: ["reading:detail", "reading:scan", "vocab:work", "grammar:connectors"]),
    ReadingText(id: "es-read-resena-critica", languageID: "es", title: "Reseña: la exposición « Umbral »", level: "C1", topic: "cultura", unitID: "es-foundations-u10",
        text: "Con « Umbral », la galería Lagarta intenta lo difícil: una exposición sobre el silencio. Para empezar, acierta con el recorrido: de la entrada al fondo, cada sala baja el volumen, y el visitante baja la voz sin que nadie se lo pida. La pieza central — cien radios encendidos que no emiten nada — es, por así decirlo, el ruido hecho ausencia. No obstante, la muestra adolece de pretensión: los carteles explican lo que las obras ya dicen, y lo dicen mejor. Desde mi punto de vista, sobra la mitad de los textos. A esto se añade que el catálogo, carísimo, retoca las fotografías hasta vaciarlas. En resumen: vaya, y pronto; la exposición se sostiene sola, a pesar de quienes la acompañan.",
        questions: [
                            Exercise(id: "es-read-resena-critica-q1", kind: "choice", prompt: "¿Qué opina la crítica de los carteles explicativos ?", options: ["Que sobran en parte", "Que son imprescindibles", "Que deberían ampliarse", "Que son demasiado baratos"], answers: ["Que sobran en parte"], explain: "« Sobra la mitad de los textos: las obras lo dicen mejor »."),
                            Exercise(id: "es-read-resena-critica-q2", kind: "choice", prompt: "¿Qué es la pieza central de la muestra ?", options: ["Cien radios encendidos y mudos", "Una sala a oscuras", "Un catálogo carísimo", "Un cartel explicativo"], answers: ["Cien radios encendidos y mudos"], explain: "« Cien radios encendidos que no emiten nada »."),
                            Exercise(id: "es-read-resena-critica-q3", kind: "written", prompt: "¿Cómo describe la crítica el intento de la galería ?", options: [], answers: ["dificil", "difícil", "un intento dificil", "un intento difícil"], explain: "« Intenta lo difícil: una exposición sobre el silencio »."),
                            Exercise(id: "es-read-resena-critica-q4", kind: "choice", prompt: "¿Qué se deduce sobre el visitante ?", options: ["Que respeta el silencio sin que se lo pidan", "Que habla durante todo el recorrido", "Que se queja del precio del catálogo", "Que entra y sale enseguida"], answers: ["Que respeta el silencio sin que se lo pidan"], explain: "« Baja la voz sin que nadie se lo pida »."),
                            Exercise(id: "es-read-resena-critica-q5", kind: "written", prompt: "¿Qué defecto señala la crítica del catálogo ?", options: [], answers: ["retoca las fotografias", "retoca las fotografías", "retoca las fotos"], explain: "Retoca las fotografías hasta vaciarlas; además, es carísimo.")], skills: ["reading:inference", "function:express-opinion", "grammar:connectors", "vocab:collocations"]),
    ReadingText(id: "es-read-anuncio-companero", languageID: "es", title: "Se busca compañera de piso", level: "A1", topic: "vivienda", unitID: "es-foundations-u11",
        text: "Busco una compañera de piso para un piso en la calle Serrano. El piso tiene tres habitaciones y dos baños. Tu habitación es grande, con una ventana y una mesa. Mi habitación está al lado del salón. En la cocina hay una lavadora nueva. El alquiler es de 350 euros al mes, más la luz y el agua. Busco una persona tranquila y ordenada. Mi nombre es Elena y trabajo en un hospital. ¿Estás interesada? Llama al 602 123 405.",
        questions: [
                            Exercise(id: "es-read-anuncio-companero-q1", kind: "choice", prompt: "¿Cuántas habitaciones tiene el piso?", options: ["Tres", "Dos", "Cuatro", "Una"], answers: ["Tres"], explain: "El piso tiene tres habitaciones y dos baños."),
                            Exercise(id: "es-read-anuncio-companero-q2", kind: "written", prompt: "¿Cómo es la habitación del anuncio?", options: [], answers: ["grande", "es grande", "muy grande"], explain: "Tu habitación es grande, con una ventana y una mesa."),
                            Exercise(id: "es-read-anuncio-companero-q3", kind: "choice", prompt: "¿Dónde está la habitación de Elena?", options: ["Al lado del salón", "Encima de la cocina", "Debajo de la escalera", "Lejos del baño"], answers: ["Al lado del salón"], explain: "Mi habitación está al lado del salón."),
                            Exercise(id: "es-read-anuncio-companero-q4", kind: "written", prompt: "¿Cuánto es el alquiler al mes?", options: [], answers: ["350 euros", "trescientos cincuenta euros", "350"], explain: "El alquiler es de 350 euros al mes."),
                            Exercise(id: "es-read-anuncio-companero-q5", kind: "choice", prompt: "¿Qué persona busca Elena?", options: ["Tranquila y ordenada", "Simpática y ruidosa", "Joven y deportista", "Seria y callada"], answers: ["Tranquila y ordenada"], explain: "Busco una persona tranquila y ordenada.")], skills: ["reading:detail", "reading:scan", "grammar:possessives", "vocab:home", "function:describe-people"]),
    ReadingText(id: "es-read-mensaje-grupo", languageID: "es", title: "Mensajes del grupo", level: "A1", topic: "planes", unitID: "es-foundations-u14",
        text: "Marta: ¡Chicos! El sábado hace sol. ¿Jugamos al tenis en el parque?\nPablo: Me encanta el tenis. Siempre juego los sábados.\nAna: Yo a veces juego, pero el sábado trabajo por la mañana. ¿Y el domingo?\nMarta: El domingo perfecto. Yo siempre nado por la mañana, pero por la tarde estoy libre.\nPablo: Yo nunca trabajo los domingos. ¿Quedamos a las cinco?\nAna: Vale, a las cinco. Yo llevo el café.\nMarta: ¡Perfecto! Nos vemos el domingo a las cinco.",
        questions: [
                            Exercise(id: "es-read-mensaje-grupo-q1", kind: "choice", prompt: "¿Qué día hace sol?", options: ["El sábado", "El domingo", "El lunes", "El viernes"], answers: ["El sábado"], explain: "Marta escribe: el sábado hace sol."),
                            Exercise(id: "es-read-mensaje-grupo-q2", kind: "choice", prompt: "¿Quién siempre juega al tenis los sábados?", options: ["Pablo", "Ana", "Marta", "Nadie"], answers: ["Pablo"], explain: "Pablo: siempre juego los sábados."),
                            Exercise(id: "es-read-mensaje-grupo-q3", kind: "written", prompt: "¿Qué hace siempre Marta por la mañana?", options: [], answers: ["Nada", "nada", "nado"], explain: "Yo siempre nado por la mañana, dice Marta."),
                            Exercise(id: "es-read-mensaje-grupo-q4", kind: "choice", prompt: "¿Quién nunca trabaja los domingos?", options: ["Pablo", "Ana", "Marta", "Todos"], answers: ["Pablo"], explain: "Pablo nunca trabaja los domingos."),
                            Exercise(id: "es-read-mensaje-grupo-q5", kind: "written", prompt: "¿A qué hora quedan el domingo?", options: [], answers: ["A las cinco", "a las cinco", "las cinco"], explain: "Quedamos a las cinco."),
                            Exercise(id: "es-read-mensaje-grupo-q6", kind: "choice", prompt: "¿Qué lleva Ana?", options: ["El café", "El tenis", "La toalla", "El agua"], answers: ["El café"], explain: "Yo llevo el café, dice Ana.")], skills: ["reading:detail", "reading:scan", "vocab:hobbies", "vocab:daily-routine", "grammar:frequency-adverbs"]),
    ReadingText(id: "es-read-horario-metro", languageID: "es", title: "El horario del metro", level: "A1", topic: "transporte", unitID: "es-foundations-u15",
        text: "Este es el horario de la línea dos de metro. El primer tren sale a las seis de la mañana y el último, a las once y media de la noche. Hay un tren cada cinco minutos por la mañana y cada ocho por la tarde. Los fines de semana, el primer tren es a las siete. Para ir al centro, tomas la línea dos en la estación Norte y bajas en la parada Mayor; el viaje dura veinte minutos. Un billete cuesta dos euros y cincuenta.",
        questions: [
                            Exercise(id: "es-read-horario-metro-q1", kind: "choice", prompt: "¿A qué hora sale el último tren?", options: ["A las once y media de la noche", "A las once de la mañana", "A las seis de la mañana", "A las diez y media de la noche"], answers: ["A las once y media de la noche"], explain: "El último tren sale a las once y media de la noche."),
                            Exercise(id: "es-read-horario-metro-q2", kind: "choice", prompt: "¿Cada cuánto hay un tren por la mañana?", options: ["Cada cinco minutos", "Cada ocho minutos", "Cada veinte minutos", "Cada media hora"], answers: ["Cada cinco minutos"], explain: "Hay un tren cada cinco minutos por la mañana."),
                            Exercise(id: "es-read-horario-metro-q3", kind: "written", prompt: "¿A qué hora es el primer tren los fines de semana?", options: [], answers: ["A las siete", "a las siete", "las siete"], explain: "Los fines de semana, el primer tren es a las siete."),
                            Exercise(id: "es-read-horario-metro-q4", kind: "written", prompt: "¿En qué estación tomas la línea dos para ir al centro?", options: [], answers: ["En la estación Norte", "en la estacion norte", "la estación Norte"], explain: "Tomas la línea dos en la estación Norte."),
                            Exercise(id: "es-read-horario-metro-q5", kind: "choice", prompt: "¿Cuánto dura el viaje al centro?", options: ["Veinte minutos", "Cinco minutos", "Ocho minutos", "Diez minutos"], answers: ["Veinte minutos"], explain: "El viaje dura veinte minutos.")], skills: ["reading:detail", "reading:scan", "vocab:transport", "function:tell-time"]),
    ReadingText(id: "es-read-cadena-mensajes", languageID: "es", title: "La cadena de mensajes", level: "A2", topic: "mensajes", unitID: "es-foundations-u18",
        text: "El grupo del insti tiene un chat para organizar el cumpleaños de Nora. Carlos escribe: «El sábado vamos a hacerle una fiesta sorpresa. Yo voy a comprar el pastel». Laura responde: «Perfecto, yo llevo los globos, pero voy a llegar tarde, es que trabajo hasta las ocho». Pablo escribe: «¿Y la música? Llevo el altavoz». Nadie contesta, así que Pablo insiste: «¿Me leéis?». Entonces Nora responde con un emoji de pastel: ella está en el grupo y ya lo sabe. Carlos borra el mensaje… demasiado tarde. El sábado, cuando llega el pastel, Nora sonríe y dice: «¡Qué sorpresa!».",
        questions: [
                            Exercise(id: "es-read-cadena-mensajes-q1", kind: "choice", prompt: "¿Para qué es el chat?", options: ["Para el cumpleaños de Nora", "Para estudiar juntos", "Para organizar un viaje", "Para el partido del sábado"], answers: ["Para el cumpleaños de Nora"], explain: "El chat es para organizar el cumpleaños de Nora."),
                            Exercise(id: "es-read-cadena-mensajes-q2", kind: "choice", prompt: "¿Qué va a comprar Carlos?", options: ["El pastel", "Los globos", "El altavoz", "Las bebidas"], answers: ["El pastel"], explain: "«Yo voy a comprar el pastel»."),
                            Exercise(id: "es-read-cadena-mensajes-q3", kind: "written", prompt: "¿Por qué va a llegar tarde Laura?", options: [], answers: ["porque trabaja hasta las ocho", "trabaja hasta las ocho", "es que trabaja hasta las ocho"], explain: "«Voy a llegar tarde, es que trabajo hasta las ocho»."),
                            Exercise(id: "es-read-cadena-mensajes-q4", kind: "choice", prompt: "¿Cómo se entera Nora de la fiesta?", options: ["Responde en el mismo chat", "Carlos se lo dice", "Lee el pastel", "Laura la llama"], answers: ["Responde en el mismo chat"], explain: "Nora responde con un emoji: está en el grupo y ya lo sabe."),
                            Exercise(id: "es-read-cadena-mensajes-q5", kind: "written", prompt: "¿Qué lleva Pablo a la fiesta?", options: [], answers: ["el altavoz", "El altavoz", "un altavoz"], explain: "«Llevo el altavoz».")], skills: ["reading:detail", "reading:inference", "vocab:social-expressions", "grammar:going-to"]),
    ReadingText(id: "es-read-resena-averia", languageID: "es", title: "La reseña del servicio técnico", level: "A2", topic: "reseñas", unitID: "es-foundations-u21",
        text: "★★★☆☆ Servicio rápido, pero caro. Escribo esta reseña porque mi lavadora se estropeó el sábado. Llamé al servicio técnico el lunes por la mañana y el técnico llegó el martes a las diez. Miró la máquina, cambió una pieza pequeña y la lavadora funcionó otra vez en una hora. El arreglo fue rápido y el técnico fue muy amable. El problema fue el precio: la pieza costó treinta euros y la visita, noventa. Lo recomiendo, pero pide primero el presupuesto.",
        questions: [
                            Exercise(id: "es-read-resena-averia-q1", kind: "choice", prompt: "¿Cuál era la avería?", options: ["La lavadora se estropeó", "El teléfono se rompió", "La nevera dejó de funcionar", "La luz se fue"], answers: ["La lavadora se estropeó"], explain: "Escribo esta reseña porque mi lavadora se estropeó el sábado."),
                            Exercise(id: "es-read-resena-averia-q2", kind: "written", prompt: "¿Qué día llegó el técnico?", options: [], answers: ["el martes", "martes", "el martes a las diez"], explain: "Llamó el lunes y el técnico llegó el martes a las diez."),
                            Exercise(id: "es-read-resena-averia-q3", kind: "choice", prompt: "¿Qué fue lo mejor del servicio?", options: ["Fue rápido y el técnico, amable", "Fue barato", "Vino el mismo día", "Regaló la pieza"], answers: ["Fue rápido y el técnico, amable"], explain: "El arreglo fue rápido y el técnico fue muy amable."),
                            Exercise(id: "es-read-resena-averia-q4", kind: "choice", prompt: "¿Cuál fue el problema según el autor?", options: ["El precio de la pieza y de la visita", "El técnico llegó tarde", "La lavadora no funcionó", "No atendió el teléfono"], answers: ["El precio de la pieza y de la visita"], explain: "La pieza costó treinta euros y la visita, noventa."),
                            Exercise(id: "es-read-resena-averia-q5", kind: "written", prompt: "¿Qué recomienda el autor pedir antes del arreglo?", options: [], answers: ["el presupuesto", "presupuesto", "primero el presupuesto"], explain: "Lo recomiendo, pero pide primero el presupuesto.")], skills: ["reading:detail", "reading:inference", "function:solve-problems", "grammar:past-simple-regular"]),
    ReadingText(id: "es-read-lista-maleta", languageID: "es", title: "La lista de la maleta", level: "A2", topic: "viajes", unitID: "es-foundations-u26",
        text: "Lista de la maleta: viaje a Roma. Mañana viajamos a Roma. La maleta va a llevar:\n— Ropa ligera: tres camisetas, un jersey y un chubasquero, porque puede llover.\n— Documentos: pasaportes, tarjetas de embarque y el seguro de viaje. No olvidar.\n— Tecnología: cargador, adaptador y auriculares.\n— Otros: paraguas pequeño, guía de Roma y una bolsa para la ropa sucia.\nLos líquidos van en la maleta grande, no en la pequeña, porque el control del aeropuerto no acepta botes de más de cien mililitros.\nMamá revisa la lista mañana a las seis y media. ¡No olvidar el adaptador!",
        questions: [
                            Exercise(id: "es-read-lista-maleta-q1", kind: "choice", prompt: "¿A dónde viajan mañana?", options: ["A Roma", "A Lisboa", "A París", "A Madrid"], answers: ["A Roma"], explain: "Mañana viajamos a Roma."),
                            Exercise(id: "es-read-lista-maleta-q2", kind: "written", prompt: "¿Por qué llevan chubasquero?", options: [], answers: ["porque puede llover", "puede llover", "por la lluvia"], explain: "Un jersey y un chubasquero, porque puede llover."),
                            Exercise(id: "es-read-lista-maleta-q3", kind: "choice", prompt: "¿Qué documentos van a llevar?", options: ["Pasaportes y tarjetas de embarque", "DNI y carnet de conducir", "Solo el seguro", "Visados y billetes impresos"], answers: ["Pasaportes y tarjetas de embarque"], explain: "Documentos: pasaportes, tarjetas de embarque y el seguro de viaje."),
                            Exercise(id: "es-read-lista-maleta-q4", kind: "choice", prompt: "¿Dónde van los líquidos y por qué?", options: ["En la maleta grande: el control no acepta botes grandes en la pequeña", "En la maleta pequeña: pesan menos", "En el bolsillo: es más rápido", "En una bolsa de tela"], answers: ["En la maleta grande: el control no acepta botes grandes en la pequeña"], explain: "Los líquidos van en la maleta grande, no en la pequeña, porque el control del aeropuerto no acepta botes de más de cien mililitros."),
                            Exercise(id: "es-read-lista-maleta-q5", kind: "written", prompt: "¿A qué hora revisa mamá la lista?", options: [], answers: ["a las seis y media", "seis y media", "a las 6 y media"], explain: "Mamá revisa la lista mañana a las seis y media.")], skills: ["reading:detail", "reading:inference", "grammar:going-to", "vocab:travel"]),
    ReadingText(id: "es-read-cartel-vecinal", languageID: "es", title: "Carta abierta a los vecinos", level: "B1", topic: "barrio", unitID: "es-foundations-u27",
        text: "CARTA ABIERTA A LOS VECINOS. Queridos vecinos: desde la asociación proponemos peatonalizar la calle del Mercado los sábados por la mañana. ¿Por qué? Primero, porque el mercado ha crecido y la calle ya no respira: hay demasiado tráfico en pocas horas. Además, los niños no pueden jugar ni cruzar tranquilos. Por eso pedimos: una zona peatonal de nueve a dos, más árboles y bancos nuevos, y carril bici en la avenida. Sabemos que algunos comercios temen perder clientes, pero en otros barrios la experiencia ha sido positiva: la gente pasea más y compra más. Firma la carta en el centro cívico o responde a este anuncio. Entre todos, la calle que queremos empieza en nuestra puerta.",
        questions: [
                            Exercise(id: "es-read-cartel-vecinal-q1", kind: "choice", prompt: "¿Qué propone la asociación?", options: ["Peatonalizar la calle del Mercado los sábados", "Cerrar el mercado", "Quitar los árboles", "Ampliar la avenida"], answers: ["Peatonalizar la calle del Mercado los sábados"], explain: "Proponemos peatonalizar la calle del Mercado los sábados por la mañana."),
                            Exercise(id: "es-read-cartel-vecinal-q2", kind: "written", prompt: "¿Por qué no pueden cruzar los niños tranquilos?", options: [], answers: ["porque hay demasiado tráfico", "por el tráfico", "demasiado tráfico"], explain: "Hay demasiado tráfico en pocas horas."),
                            Exercise(id: "es-read-cartel-vecinal-q3", kind: "choice", prompt: "¿Qué piden exactamente?", options: ["Zona peatonal, árboles, bancos y carril bici", "Solo más aparcamiento", "Un mercado cubierto", "Más semáforos"], answers: ["Zona peatonal, árboles, bancos y carril bici"], explain: "Pedimos: una zona peatonal de nueve a dos, más árboles y bancos nuevos, y carril bici."),
                            Exercise(id: "es-read-cartel-vecinal-q4", kind: "choice", prompt: "¿Qué temen algunos comercios?", options: ["Perder clientes", "Pagar más impuestos", "Perder el local", "El ruido"], answers: ["Perder clientes"], explain: "Algunos comercios temen perder clientes."),
                            Exercise(id: "es-read-cartel-vecinal-q5", kind: "choice", prompt: "¿Qué argumento usa la carta para tranquilizar a los comercios?", options: ["En otros barrios la gente pasea y compra más", "El ayuntamiento pagará una ayuda", "Los clientes son todos vecinos", "El mercado se cierra antes"], answers: ["En otros barrios la gente pasea y compra más"], explain: "En otros barrios la experiencia ha sido positiva: la gente pasea más y compra más."),
                            Exercise(id: "es-read-cartel-vecinal-q6", kind: "written", prompt: "¿Dónde puedes firmar la carta?", options: [], answers: ["en el centro cívico", "centro cívico", "el centro civico"], explain: "Firma la carta en el centro cívico o responde a este anuncio.")], skills: ["reading:inference", "reading:detail", "function:express-opinion", "writing:argument"]),
    ReadingText(id: "es-read-dia-abuelo", languageID: "es", title: "Un día con el abuelo", level: "A1", topic: "rutina", unitID: "es-foundations-u2",
        text: "El abuelo Ramón se levanta a las seis y media, siempre antes que el sol. Prepara un café solo y lee el periódico en la cocina, en silencio. A las ocho pasea por el parque con su perro Toby; allí saluda a todos los jardineros. Por la tarde cuida su huerto: tomates, lechugas y una higuera muy vieja. Los domingos, sus nietos comen en su casa y él cocina su famosa tortilla. Dice que el secreto de la vida es la rutina: cada cosa a su hora.",
        questions: [
                            Exercise(id: "es-read-dia-abuelo-q1", kind: "choice", prompt: "¿A qué hora se levanta el abuelo?", options: ["A las seis y media", "A las siete", "A las ocho", "A las nueve"], answers: ["A las seis y media"], explain: "Se levanta a las seis y media, siempre antes que el sol."),
                            Exercise(id: "es-read-dia-abuelo-q2", kind: "written", prompt: "¿Cómo se llama su perro?", options: [], answers: ["toby", "Toby"], explain: "Pasea por el parque con su perro Toby."),
                            Exercise(id: "es-read-dia-abuelo-q3", kind: "choice", prompt: "¿Qué hace por la tarde?", options: ["Cuida su huerto", "Duerme la siesta", "Ve la tele", "Va al bar"], answers: ["Cuida su huerto"], explain: "Por la tarde cuida su huerto."),
                            Exercise(id: "es-read-dia-abuelo-q4", kind: "choice", prompt: "¿Qué cocina los domingos para sus nietos?", options: ["Una tortilla", "Una paella", "Una sopa", "Galletas"], answers: ["Una tortilla"], explain: "Cocina su famosa tortilla."),
                            Exercise(id: "es-read-dia-abuelo-q5", kind: "written", prompt: "¿Qué lee por la mañana?", options: [], answers: ["el periódico", "el periodico", "el diario"], explain: "Lee el periódico en la cocina, en silencio.")], skills: ["reading:detail", "grammar:present-simple", "vocab:daily-routine", "vocab:family"]),
    ReadingText(id: "es-read-receta-tortilla", languageID: "es", title: "La tortilla de la casa", level: "A1", topic: "comida", unitID: "es-foundations-u3",
        text: "La tortilla de patatas es el plato favorito de mi familia. En casa la prepara mi madre, y es muy fácil. Primero, pelamos cuatro patatas y las cortamos en trozos pequeños. Después, freímos las patatas con aceite en una sartén grande. Batimos cinco huevos en un plato y mezclamos todo con sal. Por último, cocinamos la mezcla en la sartén unos minutos por cada lado. En mi casa la comemos con pan y tomate. ¡Está riquísima!",
        questions: [
                            Exercise(id: "es-read-receta-tortilla-q1", kind: "choice", prompt: "¿Cuál es el plato favorito de la familia?", options: ["La tortilla de patatas", "La paella", "La sopa", "El gazpacho"], answers: ["La tortilla de patatas"], explain: "La tortilla de patatas es el plato favorito de mi familia."),
                            Exercise(id: "es-read-receta-tortilla-q2", kind: "written", prompt: "¿Cuántas patatas pela?", options: [], answers: ["cuatro", "4"], explain: "Primero, pelamos cuatro patatas."),
                            Exercise(id: "es-read-receta-tortilla-q3", kind: "choice", prompt: "¿Con qué fríe las patatas?", options: ["Con aceite", "Con mantequilla", "Con agua", "Con sal"], answers: ["Con aceite"], explain: "Freímos las patatas con aceite en una sartén grande."),
                            Exercise(id: "es-read-receta-tortilla-q4", kind: "written", prompt: "¿Cuántos huevos bate?", options: [], answers: ["cinco", "5"], explain: "Batimos cinco huevos en un plato."),
                            Exercise(id: "es-read-receta-tortilla-q5", kind: "choice", prompt: "¿Con qué comen la tortilla en su casa?", options: ["Con pan y tomate", "Con arroz", "Con ensalada", "Con patatas fritas"], answers: ["Con pan y tomate"], explain: "En mi casa la comemos con pan y tomate.")], skills: ["reading:scan", "reading:detail", "vocab:food", "grammar:present-simple"]),
    ReadingText(id: "es-read-primera-semana", languageID: "es", title: "Mi primera semana", level: "B1", topic: "trabajo", unitID: "es-foundations-u22",
        text: "Mi primera semana en la oficina ha sido un torbellino. El lunes llegué tan temprano que nadie estaba todavía; el edificio no abría hasta las ocho. Desde entonces he aprendido tres cosas. Primera: preguntar no es debilidad; he evitado dos errores grandes gracias a mis preguntas «tontas». Segunda: el café de la máquina está sobrevalorado, pero las conversaciones junto a la máquina no; ahí he conocido a medio equipo. Tercera: por eso he dejado de comer frente al ordenador; bajar a la plaza con los compañeros enseña más que diez reuniones. Todavía no he firmado ningún proyecto grande, pero ya me siento parte del lugar. El viernes, cuando he apagado el ordenador, he sonreído.",
        questions: [
                            Exercise(id: "es-read-primera-semana-q1", kind: "written", prompt: "¿Qué ha sido la primera semana?", options: [], answers: ["un torbellino", "torbellino"], explain: "Mi primera semana en la oficina ha sido un torbellino."),
                            Exercise(id: "es-read-primera-semana-q2", kind: "choice", prompt: "¿Cómo llegó el lunes?", options: ["Tan temprano que nadie estaba", "A las nueve en punto", "Después del café", "A mediodía"], answers: ["Tan temprano que nadie estaba"], explain: "Llegué tan temprano que nadie estaba todavía."),
                            Exercise(id: "es-read-primera-semana-q3", kind: "choice", prompt: "¿Qué ha evitado gracias a preguntar?", options: ["Dos errores grandes", "La reunión del viernes", "El café de la máquina", "El tráfico"], answers: ["Dos errores grandes"], explain: "He evitado dos errores grandes gracias a mis preguntas «tontas»."),
                            Exercise(id: "es-read-primera-semana-q4", kind: "written", prompt: "¿Dónde ha conocido a medio equipo?", options: [], answers: ["junto a la máquina de café", "junto a la máquina", "junto a la maquina"], explain: "Las conversaciones junto a la máquina le han servido para conocer a medio equipo."),
                            Exercise(id: "es-read-primera-semana-q5", kind: "choice", prompt: "¿Qué ha dejado de hacer?", options: ["Comer frente al ordenador", "Ir a la plaza", "Preguntar dudas", "Tomar café"], answers: ["Comer frente al ordenador"], explain: "Por eso he dejado de comer frente al ordenador."),
                            Exercise(id: "es-read-primera-semana-q6", kind: "choice", prompt: "¿Cómo se siente al final de la semana?", options: ["Parte del lugar", "Un extraño", "Cansado y triste", "Sin energía"], answers: ["Parte del lugar"], explain: "Todavía no ha firmado nada grande, pero ya se siente parte del lugar.")], skills: ["reading:detail", "grammar:present-perfect", "function:talk-about-work", "grammar:connectors"]),
    ReadingText(id: "es-read-blog-bici", languageID: "es", title: "Bici o coche: mi experimento", level: "B1", topic: "ciudad", unitID: "es-foundations-u27",
        text: "Durante años cogí el coche para todo: al trabajo, al gimnasio, incluso a la panadería de la esquina. El mes pasado hice un experimento: dejé el coche aparcado y me moví en bici. Los resultados me han sorprendido. He tardado casi lo mismo en llegar al trabajo, porque el atasco ya no cuenta. He gastado menos dinero en gasolina y he dormido mejor. Sin embargo, no todo ha sido perfecto: un día llovió muchísimo y llegué empapado a una reunión. Además, el carril bici desaparece justamente en las calles más peligrosas. Aun así, no pienso volver atrás: la ciudad se ve distinta cuando la recorres a pedales.",
        questions: [
                            Exercise(id: "es-read-blog-bici-q1", kind: "choice", prompt: "¿Qué experimento hizo el autor?", options: ["Ir en bici durante un mes", "Vender el coche", "Ir andando al trabajo", "Comprar una moto"], answers: ["Ir en bici durante un mes"], explain: "Dejó el coche aparcado y se movió en bici durante un mes."),
                            Exercise(id: "es-read-blog-bici-q2", kind: "written", prompt: "¿Cuánto ha tardado en llegar al trabajo?", options: [], answers: ["casi lo mismo", "lo mismo"], explain: "Ha tardado casi lo mismo, porque el atasco ya no cuenta."),
                            Exercise(id: "es-read-blog-bici-q3", kind: "choice", prompt: "¿Qué ventaja menciona el texto?", options: ["Ha dormido mejor", "Ha llegado antes al gimnasio", "Ha conocido gente nueva", "Ha adelgazado"], answers: ["Ha dormido mejor"], explain: "He gastado menos dinero en gasolina y he dormido mejor."),
                            Exercise(id: "es-read-blog-bici-q4", kind: "choice", prompt: "¿Qué pasó el día de lluvia?", options: ["Llegó empapado a una reunión", "Perdió la bici", "Se quedó en casa", "Rompió el móvil"], answers: ["Llegó empapado a una reunión"], explain: "Un día llovió muchísimo y llegó empapado a una reunión."),
                            Exercise(id: "es-read-blog-bici-q5", kind: "written", prompt: "¿Qué desaparece en las calles más peligrosas?", options: [], answers: ["el carril bici", "carril bici", "el carril"], explain: "El carril bici desaparece en las calles más peligrosas."),
                            Exercise(id: "es-read-blog-bici-q6", kind: "choice", prompt: "¿Qué decide al final?", options: ["No volver atrás", "Volver al coche", "Comprar dos bicis", "Ir en patinete"], answers: ["No volver atrás"], explain: "Aun así, no piensa volver atrás.")], skills: ["reading:detail", "reading:inference", "grammar:present-perfect", "grammar:connectors"]),
    ReadingText(id: "es-read-columna-ia", languageID: "es", title: "Columna: algoritmos que deciden", level: "B2", topic: "actualidad", unitID: "es-foundations-u9",
        text: "Cada vez más decisiones que nos afectan las toman sistemas automáticos: a qué empleo se nos convoca, a qué crédito accedemos, qué noticia leemos. Los bancos afirman que los algoritmos son neutrales; la experiencia demuestra lo contrario: un sistema entrenado con datos del pasado reproduce los sesgos que escondían esos datos. Si quisiéramos evitarlo, habría que abrir la caja negra: que cualquier persona afectada pudiera conocer y discutir los criterios con los que ha sido evaluada. Algunos países ya lo han regulado; otros se esconden detrás de la innovación. La tecnología no es destino: es una elección colectiva. La pregunta no es lo que las máquinas pueden hacer, sino lo que decidimos que hagan. Esa decisión, todavía, es nuestra.",
        questions: [
                            Exercise(id: "es-read-columna-ia-q1", kind: "choice", prompt: "¿Qué decisiones toman ya los algoritmos?", options: ["Empleo, crédito y noticias", "Los precios del supermercado", "El tiempo que hará", "Los exámenes de escuela"], answers: ["Empleo, crédito y noticias"], explain: "A qué empleo se nos convoca, a qué crédito accedemos, qué noticia leemos."),
                            Exercise(id: "es-read-columna-ia-q2", kind: "written", prompt: "¿Qué reproducen los sistemas entrenados con datos del pasado?", options: [], answers: ["los sesgos", "sesgos", "los prejuicios"], explain: "Un sistema entrenado con datos del pasado reproduce los sesgos que escondían esos datos."),
                            Exercise(id: "es-read-columna-ia-q3", kind: "choice", prompt: "¿Qué haría falta, según la autora, para evitar los sesgos?", options: ["Abrir la caja negra", "Prohibir los bancos", "Esperar diez años", "Comprar más datos"], answers: ["Abrir la caja negra"], explain: "Habría que abrir la caja negra: conocer y discutir los criterios."),
                            Exercise(id: "es-read-columna-ia-q4", kind: "written", prompt: "¿Con qué se esconden algunos países?", options: [], answers: ["detrás de la innovación", "la innovación", "detras de la innovacion"], explain: "Otros países se esconden detrás de la innovación."),
                            Exercise(id: "es-read-columna-ia-q5", kind: "choice", prompt: "¿Cómo describe la autora la tecnología?", options: ["Una elección colectiva", "Un destino inevitable", "Un juego peligroso", "Una moda pasajera"], answers: ["Una elección colectiva"], explain: "La tecnología no es destino: es una elección colectiva.")], skills: ["reading:inference", "writing:argument", "grammar:passive-intro", "grammar:second-conditional"]),
    ReadingText(id: "es-read-carta-vivienda", languageID: "es", title: "Carta al director: vivienda", level: "B2", topic: "opinión", unitID: "es-foundations-u8",
        text: "Señor director: su editorial de ayer sostiene que la crisis de vivienda se arregla sola, con paciencia y mercado. Me permito discrepar. Mientras se construyen decenas de miles de pisos de lujo, personas con trabajos estables viven en pisos que ni siquiera son suyos y que se comen la mitad de su sueldo. La vivienda, que debería ser un derecho, se ha convertido en activo financiero. Yo no demonizaría al propietario pequeño, que alquila una herencia; señalaría al especulador, cuyo negocio depende de que los precios suban siempre. Si graváramos las viviendas vacías y liberáramos suelo público, el mapa cambiaría en dos años. No pido milagros: pido decisiones. Las ciudades no se arreglan solas; las arreglamos quienes las habitamos.",
        questions: [
                            Exercise(id: "es-read-carta-vivienda-q1", kind: "choice", prompt: "¿Qué sostiene el editorial que la carta critica?", options: ["La crisis se arregla sola", "Hay que construir más pisos de lujo", "Los sueldos deben subir", "Hay que prohibir alquilar"], answers: ["La crisis se arregla sola"], explain: "Su editorial sostiene que la crisis de vivienda se arregla sola."),
                            Exercise(id: "es-read-carta-vivienda-q2", kind: "written", prompt: "¿En qué se ha convertido la vivienda?", options: [], answers: ["en activo financiero", "activo financiero", "un activo financiero"], explain: "La vivienda se ha convertido en activo financiero."),
                            Exercise(id: "es-read-carta-vivienda-q3", kind: "choice", prompt: "¿A quién no demoniza la carta?", options: ["Al propietario pequeño", "Al especulador", "A los bancos", "A los inquilinos"], answers: ["Al propietario pequeño"], explain: "Yo no demonizaría al propietario pequeño, que alquila una herencia."),
                            Exercise(id: "es-read-carta-vivienda-q4", kind: "written", prompt: "¿De qué depende el negocio del especulador?", options: [], answers: ["de que los precios suban", "los precios suban", "que suban los precios"], explain: "Su negocio depende de que los precios suban siempre."),
                            Exercise(id: "es-read-carta-vivienda-q5", kind: "choice", prompt: "¿Qué propone la autora?", options: ["Gravar viviendas vacías y liberar suelo público", "Congelar los alquileres para siempre", "Construir solo pisos de lujo", "Esperar al mercado"], answers: ["Gravar viviendas vacías y liberar suelo público"], explain: "Si graváramos las viviendas vacías y liberáramos suelo público, el mapa cambiaría."),
                            Exercise(id: "es-read-carta-vivienda-q6", kind: "choice", prompt: "¿Cómo termina la carta?", options: ["Las arreglamos quienes las habitamos", "El gobierno lo resolverá", "Con paciencia se arregla", "Nada se puede hacer"], answers: ["Las arreglamos quienes las habitamos"], explain: "Las ciudades no se arreglan solas; las arreglamos quienes las habitamos.")], skills: ["reading:inference", "writing:argument", "grammar:second-conditional", "grammar:relative-clauses"]),
    ReadingText(id: "fr-read-groupe-marche", languageID: "fr", title: "Le groupe de marche", level: "A1", topic: "santé", unitID: "fr-foundations-u2",
        text: "Les mardis, le quartier organise une marche gratuite. Elle commence à neuf heures sur la place et finit au bord du fleuve. Le groupe est mixte : il y a des étudiants, des familles et des retraités. Personne ne court ; l'idée, c'est marcher et parler. À la fin, ceux qui veulent prennent le petit-déjeuner ensemble dans un bar du marché. Camille y va depuis un mois et elle a déjà trois nouveaux amis. Elle dit que c'est le moment le plus tranquille de sa semaine.",
        questions: [
                            Exercise(id: "fr-read-groupe-marche-q1", kind: "choice", prompt: "Quand a lieu la marche ?", options: ["Les mardis", "Les lundis", "Les samedis", "Tous les jours"], answers: ["Les mardis"], explain: "Les mardis, le quartier organise une marche gratuite."),
                            Exercise(id: "fr-read-groupe-marche-q2", kind: "written", prompt: "À quelle heure commence-t-elle ?", options: [], answers: ["a neuf heures", "à neuf heures", "neuf heures"], explain: "Elle commence à neuf heures sur la place."),
                            Exercise(id: "fr-read-groupe-marche-q3", kind: "choice", prompt: "Qui participe ?", options: ["Étudiants, familles et retraités", "Seulement des étudiants", "Seulement des retraités", "Seulement des familles"], answers: ["Étudiants, familles et retraités"], explain: "Le groupe est mixte."),
                            Exercise(id: "fr-read-groupe-marche-q4", kind: "choice", prompt: "Que font ceux qui veulent à la fin ?", options: ["Ils prennent le petit-déjeuner ensemble", "Ils courent au fleuve", "Ils rentrent chez eux", "Ils prennent le bus"], answers: ["Ils prennent le petit-déjeuner ensemble"], explain: "Petit-déjeuner ensemble dans un bar du marché."),
                            Exercise(id: "fr-read-groupe-marche-q5", kind: "written", prompt: "Depuis combien de temps Camille y va-t-elle ?", options: [], answers: ["un mois", "1 mois"], explain: "Camille y va depuis un mois.")], skills: ["reading:detail", "reading:scan", "grammar:present-simple", "vocab:daily-routine"]),
    ReadingText(id: "fr-read-annonce-appart", languageID: "fr", title: "L'annonce de l'appartement", level: "A2", topic: "appartements", unitID: "fr-foundations-u4",
        text: "Appartement lumineux de deux chambres à louer à partir de septembre. Il est au troisième étage, avec ascenseur, et il a un balcon qui donne sur la cour, donc il est calme. Le salon est plus grand que la cuisine, mais la cuisine a une fenêtre. Le quartier a un marché le samedi et la station de métro est à cinq minutes. Ce n'est pas le moins cher du quartier, mais c'est le mieux éclairé. Un mois de caution est demandé, et on préfère quelqu'un qui travaille à la maison, comme les propriétaires actuels.",
        questions: [
                            Exercise(id: "fr-read-annonce-appart-q1", kind: "choice", prompt: "Quand est-il disponible ?", options: ["À partir de septembre", "À partir d'août", "Tout de suite", "En janvier"], answers: ["À partir de septembre"], explain: "À louer à partir de septembre."),
                            Exercise(id: "fr-read-annonce-appart-q2", kind: "choice", prompt: "Pourquoi est-il calme ?", options: ["Il donne sur la cour", "Il est au rez-de-chaussée", "Il n'a pas de voisins", "Il est à la campagne"], answers: ["Il donne sur la cour"], explain: "Le balcon donne sur la cour, donc il est calme."),
                            Exercise(id: "fr-read-annonce-appart-q3", kind: "written", prompt: "À combien de minutes est le métro ?", options: [], answers: ["cinq minutes", "5 minutes", "cinq"], explain: "La station de métro est à cinq minutes."),
                            Exercise(id: "fr-read-annonce-appart-q4", kind: "choice", prompt: "Comment est-il comparé au quartier ?", options: ["Pas le moins cher, mais le mieux éclairé", "Le moins cher", "Le moins éclairé", "Le plus petit"], answers: ["Pas le moins cher, mais le mieux éclairé"], explain: "Pas le moins cher, mais le mieux éclairé."),
                            Exercise(id: "fr-read-annonce-appart-q5", kind: "choice", prompt: "Qui préfèrent les propriétaires ?", options: ["Quelqu'un qui travaille à la maison", "Des étudiants", "Des familles avec enfants", "Des retraités"], answers: ["Quelqu'un qui travaille à la maison"], explain: "On préfère quelqu'un qui travaille à la maison.")], skills: ["reading:detail", "reading:inference", "grammar:comparatives"], exposureSkills: ["grammar:superlatives"]),
    ReadingText(id: "fr-read-voyage-inoubliable", languageID: "fr", title: "Le voyage inoubliable", level: "B1", topic: "voyages", unitID: "fr-foundations-u6",
        text: "L'été dernier, j'ai fait le voyage dont j'avais le plus rêvé : quinze jours au Pérou. J'avais déjà visité le Mexique et l'Argentine, mais l'Amérique du Sud m'a encore surpris. Le troisième jour, je suis monté au Machu Picchu. Il y avait du brouillard, donc au début on ne voyait rien. Puis, peu à peu, le soleil est sorti et la ville entière est apparue. Je n'ai rien dit ; je suis resté à regarder. Dans le train du retour, j'ai rencontré une famille de Cusco, et ils m'ont invité à dîner. « Les voyageurs disent toujours la même chose », a ri la grand-mère, « mais cette soupe est vraie ». Elle avait raison : c'était le meilleur dîner du voyage. Depuis, chaque fois qu'on me demande une destination, je réponds le Pérou.",
        questions: [
                            Exercise(id: "fr-read-voyage-inoubliable-q1", kind: "choice", prompt: "Combien de temps a duré le voyage ?", options: ["Quinze jours", "Dix jours", "Un mois", "Trois jours"], answers: ["Quinze jours"], explain: "Quinze jours au Pérou."),
                            Exercise(id: "fr-read-voyage-inoubliable-q2", kind: "written", prompt: "Quels pays avait-il déjà visités ?", options: [], answers: ["mexique et argentine", "le mexique et l'argentine"], explain: "J'avais déjà visité le Mexique et l'Argentine."),
                            Exercise(id: "fr-read-voyage-inoubliable-q3", kind: "choice", prompt: "Pourquoi ne voyait-on rien au début ?", options: ["Il y avait du brouillard", "C'était fermé", "Il pleuvait fort", "C'était la nuit"], answers: ["Il y avait du brouillard"], explain: "Il y avait du brouillard, donc on ne voyait rien."),
                            Exercise(id: "fr-read-voyage-inoubliable-q4", kind: "choice", prompt: "Avec qui a-t-il dîné ?", options: ["Avec une famille de Cusco", "Avec la grand-mère de l'hôtel", "Seul", "Avec des amis du train"], answers: ["Avec une famille de Cusco"], explain: "J'ai rencontré une famille de Cusco, et ils m'ont invité à dîner."),
                            Exercise(id: "fr-read-voyage-inoubliable-q5", kind: "written", prompt: "Que répond-il maintenant quand on lui demande une destination ?", options: [], answers: ["perou", "perú", "le perou", "le pérou"], explain: "Je réponds le Pérou.")], skills: ["reading:inference", "grammar:present-perfect", "grammar:connectors", "vocab:travel"]),
    ReadingText(id: "fr-read-chronique-pietonne", languageID: "fr", title: "Chronique : piétonnisons", level: "B2", topic: "opinion", unitID: "fr-foundations-u8",
        text: "Je pense qu'on devrait piétonniser le centre. D'un côté, le bruit baisserait : les habitants de la place réclament du calme depuis des années. De l'autre, la pollution baisserait, elle qui dépasse déjà les seuils légaux. C'est vrai que les commerçants craignent de perdre des clients, mais les chiffres d'autres villes disent le contraire : là où la voiture disparaît, les gens marchent plus et achètent plus. La société dont le rapport a été publié le mois dernier a calculé 15 % de ventes en plus dans les rues sans voitures. Pour tout cela, je défends la mesure : si nous avions le courage de l'essayer un an, nous ne voudrions plus revenir en arrière.",
        questions: [
                            Exercise(id: "fr-read-chronique-pietonne-q1", kind: "choice", prompt: "Quelle est la thèse de la chronique ?", options: ["Piétonniser le centre", "Élargir l'autoroute", "Interdire les vélos", "Construire un parking"], answers: ["Piétonniser le centre"], explain: "« Je pense qu'on devrait piétonniser le centre »."),
                            Exercise(id: "fr-read-chronique-pietonne-q2", kind: "written", prompt: "Qu'est-ce qui dépasse les seuils légaux ?", options: [], answers: ["la pollution"], explain: "La pollution dépasse déjà les seuils légaux."),
                            Exercise(id: "fr-read-chronique-pietonne-q3", kind: "choice", prompt: "De quoi les commerçants ont-ils peur ?", options: ["De perdre des clients", "De payer plus d'impôts", "De fermer en été", "De déménager"], answers: ["De perdre des clients"], explain: "Ils craignent de perdre des clients."),
                            Exercise(id: "fr-read-chronique-pietonne-q4", kind: "written", prompt: "Combien de ventes en plus dans les rues sans voitures ?", options: [], answers: ["15%", "15 %", "quinze pour cent"], explain: "15 % de ventes en plus."),
                            Exercise(id: "fr-read-chronique-pietonne-q5", kind: "choice", prompt: "Que propose l'auteur à la fin ?", options: ["L'essayer un an", "Oublier le plan", "Punir plus", "Voter encore"], answers: ["L'essayer un an"], explain: "« Si nous avions le courage de l'essayer un an ».")], skills: ["reading:inference", "writing:argument", "grammar:connectors", "grammar:second-conditional"]),
    ReadingText(id: "fr-read-essai-ville", languageID: "fr", title: "Essai : la ville à hauteur d'homme", level: "C1", topic: "essai", unitID: "fr-foundations-u9",
        text: "Faut-il rendre la ville aux piétons ou aux voitures ? À mon sens, la question est mal posée : il ne s'agit pas d'exclure, mais de hiérarchiser. D'un côté, la voiture occupe un espace rare : une place de parking abrite autant de surface qu'un café. De l'autre, des millions d'habitants en dépendent, faute de transports dignes de ce nom. C'est ici que le débat mérite d'être nuancé. Réduire la place de la voiture n'est pas la supprimer ; c'est, en quelque sorte, lui rendre sa valeur. Les villes qui ont osé — Oslo, Pontevedra — constatent moins d'accidents et des commerces qui résistent. Autrement dit, maîtriser la voiture est un gain pour tous, y compris pour ceux qui conduisent. Encore faut-il investir d'abord dans les bus : sans alternative crédible, chaque contrainte devient une punition.",
        questions: [
                            Exercise(id: "fr-read-essai-ville-q1", kind: "choice", prompt: "Quelle est la thèse de l'essai ?", options: ["Hiérarchiser plutôt qu'exclure", "Interdire les voitures", "Construire plus de parkings", "Supprimer les bus"], answers: ["Hiérarchiser plutôt qu'exclure"], explain: "« Il ne s'agit pas d'exclure, mais de hiérarchiser »."),
                            Exercise(id: "fr-read-essai-ville-q2", kind: "written", prompt: "Qu'abrite une place de parking, selon l'essai ?", options: [], answers: ["autant de surface qu'un cafe", "autant de surface qu'un café", "la surface d'un café"], explain: "« Une place de parking abrite autant de surface qu'un café »."),
                            Exercise(id: "fr-read-essai-ville-q3", kind: "choice", prompt: "Quelles villes sont citées en exemple ?", options: ["Oslo et Pontevedra", "Paris et Lyon", "Oslo et Paris", "Lyon et Pontevedra"], answers: ["Oslo et Pontevedra"], explain: "« Les villes qui ont osé — Oslo, Pontevedra »."),
                            Exercise(id: "fr-read-essai-ville-q4", kind: "choice", prompt: "Que signifie « lui rendre sa valeur » ?", options: ["La voiture redevient utile en étant moins prioritaire", "La voiture disparaît", "Le prix de l'essence baisse", "La voiture reprend la ville"], answers: ["La voiture redevient utile en étant moins prioritaire"], explain: "Réduire sa place n'est pas la supprimer : moins partout, donc mieux utilisée."),
                            Exercise(id: "fr-read-essai-ville-q5", kind: "written", prompt: "Quelle condition l'auteur pose-t-il à la fin ?", options: [], answers: ["investir d'abord dans les bus", "investir dans les bus", "des transports credibles", "une alternative credible"], explain: "« Encore faut-il investir d'abord dans les bus ».")], skills: ["reading:inference", "writing:argument", "grammar:connectors", "vocab:collocations"]),
    ReadingText(id: "fr-read-lettre-direction", languageID: "fr", title: "Lettre de la direction", level: "C1", topic: "travail", unitID: "fr-foundations-u9",
        text: "Chères équipes, chers collaborateurs,\n\nJe vous écris au sujet de l'organisation de la rentrée. Comme vous le savez, nos locaux du boulevard Nord seront rénovés à compter du 3 novembre. Par conséquent, les équipes du deuxième étage rejoindront le site Est, moyennant quelques aménagements que la logistique s'engage à achever avant votre arrivée. Par ailleurs, nous instaurons, à titre expérimental, deux jours de télétravail hebdomadaires ; leurs modalités vous parviendront par le portail interne. Je mesure que ces changements suscitent des questions ; aussi vous invite-je à la réunion d'information du 12 octobre, à 14 heures, salle Hemingway. En résumé : même mission, nouveaux espaces, davantage de souplesse. Je vous remercie de votre confiance et reste à votre disposition.\n\nLa direction",
        questions: [
                            Exercise(id: "fr-read-lettre-direction-q1", kind: "choice", prompt: "Quand les locaux du boulevard Nord seront-ils rénovés ?", options: ["À compter du 3 novembre", "Le 12 octobre", "Avant la rentrée", "En janvier"], answers: ["À compter du 3 novembre"], explain: "« Seront rénovés à compter du 3 novembre »."),
                            Exercise(id: "fr-read-lettre-direction-q2", kind: "written", prompt: "Où iront les équipes du deuxième étage ?", options: [], answers: ["au site est", "le site est", "site est"], explain: "« Les équipes du deuxième étage rejoindront le site Est »."),
                            Exercise(id: "fr-read-lettre-direction-q3", kind: "choice", prompt: "Combien de jours de télétravail sont instaurés ?", options: ["Deux par semaine", "Trois par semaine", "Un par mois", "Aucun"], answers: ["Deux par semaine"], explain: "« Deux jours de télétravail hebdomadaires »."),
                            Exercise(id: "fr-read-lettre-direction-q4", kind: "choice", prompt: "Où se tiendra la réunion d'information ?", options: ["Salle Hemingway", "Site Est", "Boulevard Nord", "En visioconférence"], answers: ["Salle Hemingway"], explain: "« Salle Hemingway » est annoncé en fin de lettre."),
                            Exercise(id: "fr-read-lettre-direction-q5", kind: "choice", prompt: "Quel est le ton de cette lettre ?", options: ["Formel et rassurant", "Familier et direct", "Sec et neutre", "Désolé et défensif"], answers: ["Formel et rassurant"], explain: "« Chères équipes », « je reste à votre disposition », « En résumé » : registre soutenu qui rassure.")], skills: ["reading:detail", "reading:scan", "vocab:work", "vocab:collocations"]),
    ReadingText(id: "fr-read-critique-livre", languageID: "fr", title: "Critique : un premier roman", level: "C1", topic: "littérature", unitID: "fr-foundations-u9",
        text: "Voilà un roman qui aurait pu sombrer dans la sentimentalité ; il s'en sort avec panache. L'auteure y suit trois générations de femmes dans une boulangerie lyonnaise : la grand-mère qui pétrit, la mère qui tient la caisse, la fille qui veut partir. À mon sens, le génie du livre tient à ses silences : rien n'est expliqué, tout est suggéré, à la manière des grandes fresques familiales. On regrettera toutefois une fin expéditive : les dernières pages résolvent en dix lignes ce que trois cents pages avaient patiemment noué. Nuance importante : ce défaut ne ruine pas l'ensemble. En résumé, un premier roman remarquable, moyennant une certaine tolérance pour les fins pressées. Il mérite sa place dans les prix littéraires de la rentrée ; je lirai le suivant, c'est dire.",
        questions: [
                            Exercise(id: "fr-read-critique-livre-q1", kind: "choice", prompt: "Que suit l'auteure dans ce roman ?", options: ["Trois générations de femmes", "Deux frères lyonnais", "Une boulangerie parisienne", "Une mère et son fils"], answers: ["Trois générations de femmes"], explain: "« Trois générations de femmes dans une boulangerie lyonnaise »."),
                            Exercise(id: "fr-read-critique-livre-q2", kind: "choice", prompt: "Que signifie « il s'en sort avec panache » ?", options: ["Le roman évite habilement le piège", "Le roman échoue lamentablement", "L'auteure change de sujet", "Le livre est drôle"], answers: ["Le roman évite habilement le piège"], explain: "Il « aurait pu sombrer » mais il évite la sentimentalité avec brio."),
                            Exercise(id: "fr-read-critique-livre-q3", kind: "written", prompt: "Que regrette la critique ?", options: [], answers: ["une fin expeditive", "une fin expéditive", "une fin trop rapide", "les dernieres pages"], explain: "« On regrettera toutefois une fin expéditive »."),
                            Exercise(id: "fr-read-critique-livre-q4", kind: "choice", prompt: "Quelle nuance la critique apporte-t-elle à ce défaut ?", options: ["Il ne ruine pas l'ensemble", "Il rend le livre inutile", "Il vient de l'éditeur", "Il prouve la mauvaise foi"], answers: ["Il ne ruine pas l'ensemble"], explain: "« Nuance importante : ce défaut ne ruine pas l'ensemble »."),
                            Exercise(id: "fr-read-critique-livre-q5", kind: "choice", prompt: "Quel est le verdict global ?", options: ["Un premier roman remarquable", "Un livre à éviter", "Un ouvrage moyen", "Un essai passionnant"], answers: ["Un premier roman remarquable"], explain: "« En résumé, un premier roman remarquable ».")], skills: ["reading:inference", "reading:detail", "function:express-opinion", "vocab:collocations"]),
    ReadingText(id: "fr-read-annonce-coloc", languageID: "fr", title: "Petite annonce : cherche colocataire", level: "A1", topic: "colocation", unitID: "fr-foundations-u10",
        text: "Cherche colocataire pour un grand appartement près du parc. Il y a trois chambres, une cuisine et un grand salon avec un canapé. Ma chambre est petite ; ta chambre est à côté de la salle de bains. Je m'appelle Julie, je suis étudiante et je suis très sympa. J'aime la musique et le vélo. Le loyer est de quatre cents euros. Il n'y a pas de garage, mais il y a un balcon. Tu es intéressé ? Appelle-moi le soir.",
        questions: [
                            Exercise(id: "fr-read-annonce-coloc-q1", kind: "choice", prompt: "Combien de chambres dans l'appartement ?", options: ["Trois", "Deux", "Quatre", "Une"], answers: ["Trois"], explain: "Il y a trois chambres."),
                            Exercise(id: "fr-read-annonce-coloc-q2", kind: "written", prompt: "Où est la chambre du colocataire ?", options: [], answers: ["à côté de la salle de bains", "a cote de la salle de bains"], explain: "Ta chambre est à côté de la salle de bains."),
                            Exercise(id: "fr-read-annonce-coloc-q3", kind: "choice", prompt: "Comment est Julie ?", options: ["Très sympa", "Très sérieuse", "Très fatiguée", "Timide"], answers: ["Très sympa"], explain: "Je suis très sympa, dit Julie."),
                            Exercise(id: "fr-read-annonce-coloc-q4", kind: "written", prompt: "Quel est le prix du loyer ?", options: [], answers: ["quatre cents euros", "400 euros", "quatre cent euros"], explain: "Le loyer est de quatre cents euros."),
                            Exercise(id: "fr-read-annonce-coloc-q5", kind: "choice", prompt: "Qu'est-ce qu'il n'y a pas ?", options: ["De garage", "De balcon", "De cuisine", "De salon"], answers: ["De garage"], explain: "Il n'y a pas de garage, mais il y a un balcon.")], skills: ["reading:detail", "reading:scan", "grammar:possessives", "vocab:home", "function:describe-people"]),
    ReadingText(id: "fr-read-message-groupe", languageID: "fr", title: "Messages du groupe", level: "A1", topic: "week-end", unitID: "fr-foundations-u13",
        text: "Léa : Salut ! Quel temps demain ?\nKarim : Il fait beau le matin, mais il pleut l'après-midi.\nLéa : Dommage ! Je fais toujours du vélo le samedi matin.\nMai : Moi, je vais à la piscine. Je nage souvent, j'adore l'eau.\nKarim : Moi, je ne lis jamais le week-end. Je joue au foot avec mon frère.\nLéa : Et le dimanche ? Vous aimez cuisiner ?\nMai : Oui ! J'aime faire des crêpes. Vous venez ?\nKarim : Super idée ! À dimanche !",
        questions: [
                            Exercise(id: "fr-read-message-groupe-q1", kind: "choice", prompt: "Quel temps fait-il demain après-midi ?", options: ["Il pleut", "Il neige", "Il fait beau", "Il fait froid"], answers: ["Il pleut"], explain: "Il fait beau le matin, mais il pleut l'après-midi."),
                            Exercise(id: "fr-read-message-groupe-q2", kind: "written", prompt: "Qu'est-ce que Léa fait toujours le samedi matin ?", options: [], answers: ["du vélo", "du velo", "elle fait toujours du vélo", "elle fait toujours du velo"], explain: "Je fais toujours du vélo le samedi matin."),
                            Exercise(id: "fr-read-message-groupe-q3", kind: "choice", prompt: "Où va Mai ?", options: ["À la piscine", "Au parc", "Au marché", "À la maison"], answers: ["À la piscine"], explain: "Moi, je vais à la piscine, écrit Mai."),
                            Exercise(id: "fr-read-message-groupe-q4", kind: "choice", prompt: "Qu'est-ce que Karim fait le week-end ?", options: ["Il joue au foot", "Il nage", "Il lit", "Il fait du vélo"], answers: ["Il joue au foot"], explain: "Je joue au foot avec mon frère."),
                            Exercise(id: "fr-read-message-groupe-q5", kind: "written", prompt: "Qu'est-ce que Mai aime faire ?", options: [], answers: ["faire des crêpes", "faire des crepes", "des crêpes", "des crepes"], explain: "J'aime faire des crêpes, écrit Mai.")], skills: ["reading:detail", "reading:scan", "vocab:hobbies", "vocab:daily-routine", "grammar:frequency-adverbs"]),
    ReadingText(id: "fr-read-horaires-metro", languageID: "fr", title: "Les horaires du métro", level: "A1", topic: "horaires", unitID: "fr-foundations-u14",
        text: "Voici les horaires du métro, ligne 1. Premier départ : six heures. Dernier départ : vingt-trois heures (11 h du soir). Un train part toutes les quatre minutes le matin. La prochaine rame arrive à huit heures et quart. Pour lire l'horaire, regardez la direction : Château de Vincennes ou La Défense. Je prends toujours le métro de huit heures pour aller au travail : il n'est jamais en retard !",
        questions: [
                            Exercise(id: "fr-read-horaires-metro-q1", kind: "choice", prompt: "Le premier départ est à quelle heure ?", options: ["À six heures", "À huit heures", "À onze heures", "À trois heures"], answers: ["À six heures"], explain: "Premier départ : six heures."),
                            Exercise(id: "fr-read-horaires-metro-q2", kind: "choice", prompt: "Le dernier départ est à quelle heure ?", options: ["À vingt-trois heures", "À six heures", "À huit heures et quart", "À midi"], answers: ["À vingt-trois heures"], explain: "Dernier départ : vingt-trois heures, c'est 11 h du soir."),
                            Exercise(id: "fr-read-horaires-metro-q3", kind: "choice", prompt: "Un train part toutes les… ?", options: ["Quatre minutes", "Quatre heures", "Deux minutes", "Dix minutes"], answers: ["Quatre minutes"], explain: "Un train part toutes les quatre minutes le matin."),
                            Exercise(id: "fr-read-horaires-metro-q4", kind: "written", prompt: "La prochaine rame arrive à quelle heure ?", options: [], answers: ["huit heures et quart", "à huit heures et quart", "huit heures et quart (8h15)"], explain: "La prochaine rame arrive à huit heures et quart."),
                            Exercise(id: "fr-read-horaires-metro-q5", kind: "written", prompt: "Quel métro est-ce que l'auteur prend pour aller au travail ?", options: [], answers: ["le métro de huit heures", "le metro de huit heures", "celui de huit heures"], explain: "Je prends toujours le métro de huit heures.")], skills: ["reading:detail", "reading:scan", "vocab:transport", "function:tell-time"]),
    ReadingText(id: "fr-read-fil-de-messages", languageID: "fr", title: "Le fil de messages", level: "A2", topic: "messages", unitID: "fr-foundations-u17",
        text: "Léa : Salut Karim ! On va au ciné samedi, ça te dit ?\nKarim : Dommage, je ne peux pas. Je vais aider ma sœur à déménager.\nLéa : Et Mai, elle vient ?\nKarim : Elle va venir, mais elle préfère la fin de journée.\nLéa : Parfait. On va se retrouver à 19 heures devant le cinéma, puis on va manger une pizza.\nKarim : Super. Et pour l'anniversaire de Mai ? Je vais chercher un livre sur les voyages.\nLéa : Bonne idée ! Moi, je vais lui offrir des fleurs. C'est une surprise !\nKarim : Promis, je ne dis rien. À samedi !",
        questions: [
                            Exercise(id: "fr-read-fil-de-messages-q1", kind: "choice", prompt: "Pourquoi Karim refuse samedi ?", options: ["Il aide sa sœur à déménager", "Il est malade", "Il travaille", "Il n'aime pas le cinéma"], answers: ["Il aide sa sœur à déménager"], explain: "Je vais aider ma sœur à déménager, écrit Karim."),
                            Exercise(id: "fr-read-fil-de-messages-q2", kind: "choice", prompt: "À quelle heure le groupe se retrouve-t-il ?", options: ["À 19 heures", "À 17 heures", "À 21 heures", "À 7 heures"], answers: ["À 19 heures"], explain: "On va se retrouver à 19 heures devant le cinéma."),
                            Exercise(id: "fr-read-fil-de-messages-q3", kind: "written", prompt: "Qu'est-ce que Léa va offrir à Mai ?", options: [], answers: ["des fleurs", "fleurs"], explain: "Moi, je vais lui offrir des fleurs, écrit Léa."),
                            Exercise(id: "fr-read-fil-de-messages-q4", kind: "choice", prompt: "Que va faire Karim pour le cadeau ?", options: ["Il va chercher un livre", "Il va faire un gâteau", "Il va acheter des fleurs", "Il ne donne rien"], answers: ["Il va chercher un livre"], explain: "Je vais chercher un livre sur les voyages."),
                            Exercise(id: "fr-read-fil-de-messages-q5", kind: "choice", prompt: "Pourquoi Léa écrit-elle « C'est une surprise ! » ?", options: ["Mai ne doit pas savoir pour les fleurs", "Léa organise une fête chez elle", "Karim offre aussi des fleurs", "Mai déteste les surprises"], answers: ["Mai ne doit pas savoir pour les fleurs"], explain: "Le cadeau doit rester secret jusqu'à l'anniversaire."),
                            Exercise(id: "fr-read-fil-de-messages-q6", kind: "written", prompt: "Après le film, qu'est-ce que le groupe va manger ?", options: [], answers: ["une pizza", "pizza"], explain: "Puis on va manger une pizza, écrit Léa.")], skills: ["reading:detail", "reading:inference", "vocab:social-expressions", "grammar:going-to"], exposureSkills: ["function:make-suggestions"]),
    ReadingText(id: "fr-read-avis-panne", languageID: "fr", title: "Un vélo, trois étoiles", level: "A2", topic: "avis client", unitID: "fr-foundations-u20",
        text: "Titre : un vélo qui roule… trois semaines\nJ'ai acheté ce vélo électrique le 3 mars. Les deux premières semaines, j'ai fait tous mes trajets avec : super ! Mais la semaine dernière, le vélo est tombé en panne : la batterie ne charge plus. J'ai appelé le service client deux fois. La première fois, personne n'a répondu. La deuxième fois, la vendeuse était gentille : elle m'a proposé un échange sous une semaine. J'attends maintenant. Je mets trois étoiles, parce que le vélo roule très bien… quand il marche !",
        questions: [
                            Exercise(id: "fr-read-avis-panne-q1", kind: "choice", prompt: "Quand est-ce que l'auteur a acheté le vélo ?", options: ["Le 3 mars", "Le 3 mai", "Hier", "La semaine dernière"], answers: ["Le 3 mars"], explain: "J'ai acheté ce vélo électrique le 3 mars."),
                            Exercise(id: "fr-read-avis-panne-q2", kind: "written", prompt: "Qu'est-ce qui ne marche plus sur le vélo ?", options: [], answers: ["la batterie", "la batterie ne charge plus", "batterie"], explain: "Le vélo est tombé en panne : la batterie ne charge plus."),
                            Exercise(id: "fr-read-avis-panne-q3", kind: "choice", prompt: "Combien de fois l'auteur a-t-il appelé le service client ?", options: ["Deux fois", "Une fois", "Trois fois", "Jamais"], answers: ["Deux fois"], explain: "J'ai appelé le service client deux fois."),
                            Exercise(id: "fr-read-avis-panne-q4", kind: "choice", prompt: "Qu'est-ce que la vendeuse a proposé ?", options: ["Un échange sous une semaine", "Un remboursement immédiat", "Un nouveau casque", "Une réparation gratuite sur place"], answers: ["Un échange sous une semaine"], explain: "Elle m'a proposé un échange sous une semaine."),
                            Exercise(id: "fr-read-avis-panne-q5", kind: "choice", prompt: "Pourquoi l'auteur met-il quand même trois étoiles ?", options: ["Le vélo roule très bien quand il marche", "Le service client est très rapide", "Il a reçu un cadeau", "Il n'a pas payé le vélo"], answers: ["Le vélo roule très bien quand il marche"], explain: "Je mets trois étoiles, parce que le vélo roule très bien… quand il marche !")], skills: ["reading:detail", "reading:inference", "function:solve-problems", "grammar:past-simple-regular"], exposureSkills: ["grammar:past-was-were"]),
    ReadingText(id: "fr-read-liste-valise", languageID: "fr", title: "La liste sur le frigo", level: "A2", topic: "voyage", unitID: "fr-foundations-u25",
        text: "Le départ est demain à sept heures. Sur le frigo, la liste de Léa : documents — passeport, billets, carte d'identité ; vêtements — trois t-shirts, un pull léger, le maillot de bain ; tech — chargeurs, adaptateur, écouteurs. Léa coche chaque ligne. Le pull léger, c'est pour le bus climatisé. Le maillot, c'est pour la piscine de l'hôtel. Il ne faut pas oublier le cadeau pour madame Roux : une boîte de thé du marché. Dernière ligne de la liste : « arroser les plantes ? → madame Roux ». Léa laisse un mot avec les clés, vérifie les fenêtres et met son réveil à cinq heures et demie. Tout est prêt pour Lisbonne.",
        questions: [
                            Exercise(id: "fr-read-liste-valise-q1", kind: "choice", prompt: "Quand est le départ ?", options: ["Demain à sept heures", "Ce soir", "Après-demain à cinq heures", "Demain à cinq heures et demie"], answers: ["Demain à sept heures"], explain: "Le départ est demain à sept heures."),
                            Exercise(id: "fr-read-liste-valise-q2", kind: "choice", prompt: "Pourquoi Léa prend-elle un pull léger ?", options: ["Pour le bus climatisé", "Parce qu'il va faire froid", "Pour la piscine", "Pour le marché"], answers: ["Pour le bus climatisé"], explain: "Le pull léger, c'est pour le bus climatisé."),
                            Exercise(id: "fr-read-liste-valise-q3", kind: "written", prompt: "Quel cadeau Léa apporte-t-elle à madame Roux ?", options: [], answers: ["une boîte de thé", "une boite de the", "du thé", "une boîte de thé du marché"], explain: "Une boîte de thé du marché."),
                            Exercise(id: "fr-read-liste-valise-q4", kind: "written", prompt: "À quelle heure est le réveil ?", options: [], answers: ["à cinq heures et demie", "cinq heures et demie", "5 heures et demie"], explain: "Elle met son réveil à cinq heures et demie."),
                            Exercise(id: "fr-read-liste-valise-q5", kind: "choice", prompt: "Qui arrose les plantes ?", options: ["Madame Roux", "Léa", "Le voisin", "Personne"], answers: ["Madame Roux"], explain: "« Arroser les plantes ? → madame Roux ».")], skills: ["reading:detail", "reading:scan", "vocab:travel", "grammar:connectors"]),
    ReadingText(id: "fr-read-affiche-voisins", languageID: "fr", title: "L'affiche sur le palier", level: "B1", topic: "ville", unitID: "fr-foundations-u26",
        text: "Cette semaine, une affiche du conseil fait parler l'immeuble : « Place verte dès le mois prochain ! La place du Marché sera sans voitures le dimanche : dix arbres, des tables, un marché de producteurs locaux. Votez samedi à dix heures. » Au troisième étage, madame Benali trouve l'idée excellente : moins de bruit, plus de tomates fraîches. Chez les Lefèvre, on grogne : le dimanche, c'est justement le jour où ils rentrent en voiture. Au rez-de-chaussée, Julien propose un compromis : sans voitures seulement le matin. Samedi, 78 % votent pour. Depuis, Léa achète son pain là-bas : le quartier respire. Les Lefèvre, eux, ont testé le vélo — et ils ne s'en plaignent pas.",
        questions: [
                            Exercise(id: "fr-read-affiche-voisins-q1", kind: "choice", prompt: "Qu'est-ce qui change le dimanche ?", options: ["La place devient sans voitures", "Le marché ferme", "L'immeuble se réunit", "Les boutiques baissent les prix"], answers: ["La place devient sans voitures"], explain: "La place du Marché sera sans voitures le dimanche."),
                            Exercise(id: "fr-read-affiche-voisins-q2", kind: "written", prompt: "Quand a lieu le vote ?", options: [], answers: ["samedi à dix heures", "samedi a dix heures", "samedi 10 heures"], explain: "Votez samedi à dix heures."),
                            Exercise(id: "fr-read-affiche-voisins-q3", kind: "choice", prompt: "Pourquoi madame Benali soutient-elle le projet ?", options: ["Moins de bruit et des tomates fraîches", "Elle vend des arbres", "Elle déteste les voitures", "Ses enfants jouent là-bas"], answers: ["Moins de bruit et des tomates fraîches"], explain: "Moins de bruit, plus de tomates fraîches."),
                            Exercise(id: "fr-read-affiche-voisins-q4", kind: "written", prompt: "Quel compromis propose Julien ?", options: [], answers: ["sans voitures seulement le matin", "pas de voitures le matin", "sans voiture le matin"], explain: "Sans voitures seulement le matin."),
                            Exercise(id: "fr-read-affiche-voisins-q5", kind: "choice", prompt: "Quel est le résultat du vote ?", options: ["78 % pour", "50 % pour", "Le vote est annulé", "96 % contre"], answers: ["78 % pour"], explain: "Samedi, 78 % votent pour."),
                            Exercise(id: "fr-read-affiche-voisins-q6", kind: "written", prompt: "Comment les Lefèvre vont-ils à la place maintenant ?", options: [], answers: ["à vélo", "a velo", "en vélo", "en velo"], explain: "Les Lefèvre ont testé le vélo — et ils ne s'en plaignent pas.")], skills: ["reading:inference", "reading:detail", "grammar:connectors", "function:express-opinion"]),
    ReadingText(id: "fr-read-journee-mai", languageID: "fr", title: "La journée de Mai", level: "A1", topic: "routine", unitID: "fr-foundations-u2",
        text: "Mai est étudiante à Lyon. Elle se lève à sept heures et quart, même le week-end, parce qu'elle aime les matins tranquilles. D'abord, elle boit un grand thé avec du miel. Ensuite, elle lit dix pages d'un livre : c'est sa petite règle. À huit heures, elle prend le tram avec son voisin Théo, qui parle tout le temps de football. Les cours commencent à huit heures trente et finissent à midi et demi. L'après-midi, elle travaille à la bibliothèque parce que chez elle, il y a trop de bruit. Le soir, elle cuisine avec sa colocataire : elles préparent souvent des pâtes ou une soupe. À dix heures, Mai éteint tout et lit encore quelques pages. Elle dit que sa journée est simple, mais c'est exactement la sienne.",
        questions: [
                            Exercise(id: "fr-read-journee-mai-q1", kind: "choice", prompt: "À quelle heure Mai se lève-t-elle ?", options: ["À sept heures et quart", "À huit heures", "À sept heures", "À midi et demi"], answers: ["À sept heures et quart"], explain: "« Elle se lève à sept heures et quart. »"),
                            Exercise(id: "fr-read-journee-mai-q2", kind: "written", prompt: "Que boit-elle le matin ?", options: [], answers: ["un grand thé", "du thé", "thé avec du miel", "un the"], explain: "« D'abord, elle boit un grand thé avec du miel. »"),
                            Exercise(id: "fr-read-journee-mai-q3", kind: "written", prompt: "Combien de pages lit-elle chaque jour ?", options: [], answers: ["dix", "10", "dix pages"], explain: "« Ensuite, elle lit dix pages d'un livre. »"),
                            Exercise(id: "fr-read-journee-mai-q4", kind: "choice", prompt: "Pourquoi travaille-t-elle à la bibliothèque l'après-midi ?", options: ["Parce qu'il y a trop de bruit chez elle", "Parce que la bibliothèque est gratuite", "Parce que Théo y travaille", "Parce qu'elle n'a pas de cours"], answers: ["Parce qu'il y a trop de bruit chez elle"], explain: "« Parce que chez elle, il y a trop de bruit. »"),
                            Exercise(id: "fr-read-journee-mai-q5", kind: "choice", prompt: "Avec qui cuisine-t-elle le soir ?", options: ["Avec sa colocataire", "Avec Théo", "Avec sa sœur", "Elle cuisine seule"], answers: ["Avec sa colocataire"], explain: "« Le soir, elle cuisine avec sa colocataire. »")], skills: ["reading:detail", "reading:scan", "grammar:third-person-s", "vocab:daily-routine"]),
    ReadingText(id: "fr-read-famille-karim", languageID: "fr", title: "La tribu de Karim", level: "A1", topic: "famille", unitID: "fr-foundations-u12",
        text: "Karim a une grande famille. Son père s'appelle Youssef et travaille dans un garage : il adore les vieilles voitures. Sa mère, Sylvie, est infirmière à l'hôpital Saint-Louis ; elle rentre fatiguée mais elle sourit toujours. Karim a deux sœurs. L'aînée, Nadia, a vingt-quatre ans et vit à Bordeaux avec son copain. La petite, Inès, a neuf ans : elle dessine partout, même sur les murs, dit maman. Il y a aussi le grand-père, Maurice. Il a soixante-dix-huit ans et il raconte les mêmes histoires à chaque déjeuner, mais toute la famille écoute encore. Le dimanche, tout le monde se retrouve chez les parents. Le grand-père apporte son gâteau au chocolat, Nadia téléphone en retard, et Karim met la table. Chacun a sa place, et c'est comme ça qu'ils aiment leur dimanche.",
        questions: [
                            Exercise(id: "fr-read-famille-karim-q1", kind: "choice", prompt: "Quel est le métier du père de Karim ?", options: ["Il travaille dans un garage", "Il est infirmier", "Il est professeur", "Il est à la retraite"], answers: ["Il travaille dans un garage"], explain: "« Son père… travaille dans un garage. »"),
                            Exercise(id: "fr-read-famille-karim-q2", kind: "written", prompt: "Où vit la sœur aînée de Karim ?", options: [], answers: ["à bordeaux", "bordeaux", "a bordeaux", "elle vit à bordeaux"], explain: "« L'aînée, Nadia… vit à Bordeaux. »"),
                            Exercise(id: "fr-read-famille-karim-q3", kind: "written", prompt: "Quel âge a Inès ?", options: [], answers: ["neuf ans", "9 ans", "neuf"], explain: "« La petite, Inès, a neuf ans. »"),
                            Exercise(id: "fr-read-famille-karim-q4", kind: "choice", prompt: "Qu'apporte le grand-père le dimanche ?", options: ["Son gâteau au chocolat", "Des vieilles voitures", "Des dessins", "Du thé"], answers: ["Son gâteau au chocolat"], explain: "« Le grand-père apporte son gâteau au chocolat. »"),
                            Exercise(id: "fr-read-famille-karim-q5", kind: "written", prompt: "Que fait Karim quand toute la famille est réunie ?", options: [], answers: ["il met la table", "met la table", "il met la table", "il aide à mettre la table"], explain: "« Et Karim met la table. »")], skills: ["reading:detail", "reading:scan", "grammar:possessives", "vocab:family"]),
    ReadingText(id: "fr-read-premier-jour-lea", languageID: "fr", title: "Le premier jour de Léa", level: "B1", topic: "travail", unitID: "fr-foundations-u21",
        text: "Léa avait préparé son premier jour au millimètre : tenue repassée, trajet répété, arrivée prévue vingt minutes en avance. Tout s'est effondré à la station République : un dégagement d'urgence a bloqué la ligne pendant quarante minutes. Elle a couru sous la pluie, elle est entrée dans l'agence à neuf heures deux, trempée et rouge. Sa manager, madame Robin, n'a pas bronché : « Vous êtes pile à l'heure pour le café. » Dans l'équipe, tout le monde a vécu la même entrée en matière, dit-elle : Hugo a perdu son badge le premier matin, Karim s'était présenté un jour férié. À la pause déjeuner, Léa a déjà appris les prénoms de huit collègues et l'histoire de la plante verte du hall, morte trois fois et ressuscitée à chaque fois. Le soir, en rentrant, elle a compris quelque chose : elle avait peur de rater ses débuts, mais c'est justement ces débuts ratés qui font partie de l'équipe.",
        questions: [
                            Exercise(id: "fr-read-premier-jour-lea-q1", kind: "choice", prompt: "Qu'est-ce qui a perturbé le trajet de Léa ?", options: ["Un dégagement d'urgence à la station", "Une grève des tramways", "Elle s'est perdue", "Sa tenue n'était pas prête"], answers: ["Un dégagement d'urgence à la station"], explain: "« Un dégagement d'urgence a bloqué la ligne. »"),
                            Exercise(id: "fr-read-premier-jour-lea-q2", kind: "written", prompt: "À quelle heure Léa est-elle arrivée à l'agence ?", options: [], answers: ["à neuf heures deux", "neuf heures deux", "9h02", "a neuf heures deux"], explain: "« Elle est entrée dans l'agence à neuf heures deux. »"),
                            Exercise(id: "fr-read-premier-jour-lea-q3", kind: "choice", prompt: "Comment madame Robin réagit-elle ?", options: ["Avec calme et humour", "Elle la sanctionne", "Elle ne parle pas à Léa", "Elle est furieuse"], answers: ["Avec calme et humour"], explain: "« Vous êtes pile à l'heure pour le café. »"),
                            Exercise(id: "fr-read-premier-jour-lea-q4", kind: "written", prompt: "Quelle erreur Karim avait-il commise à son premier jour ?", options: [], answers: ["il s'était présenté un jour férié", "il était venu un jour férié", "un jour férié", "il s'est présenté un jour férié"], explain: "« Karim s'était présenté un jour férié. »"),
                            Exercise(id: "fr-read-premier-jour-lea-q5", kind: "choice", prompt: "Que comprend Léa à la fin du texte ?", options: ["Les faux pas font partie de l'équipe", "Il ne faut jamais être en retard", "Cette agence n'est pas pour elle", "Les managers sont tous indulgents"], answers: ["Les faux pas font partie de l'équipe"], explain: "« C'est justement ces débuts ratés qui font partie de l'équipe. »")], skills: ["reading:detail", "reading:inference", "vocab:work", "grammar:connectors"]),
    ReadingText(id: "fr-read-fete-rue-ecoles", languageID: "fr", title: "La fête de la rue des Écoles", level: "B1", topic: "ville", unitID: "fr-foundations-u26",
        text: "Le comité des voisins publie son programme : samedi 14 juin, la rue des Écoles sera piétonne de dix heures à vingt-deux heures pour sa fête annuelle. Au programme : un marché des créateurs dès dix heures, un atelier réparation de vélos à quatorze heures, puis le repas partagé à dix-neuf heures — chacun apporte un plat, l'association fournit les tables et les grillades. Nouveauté cette année : la cour de l'école ouvrira ses portes pour un tournoi de pétanque et un coin lecture pour les enfants. Les habitants qui veulent exposer peuvent s'inscrire jusqu'au 7 juin à la boulangerie du coin, qui sert de QG au comité. On cherche encore quatre volontaires pour l'installation des tables le samedi matin : huit heures, café offert. En cas de pluie, la fête sera reportée au samedi suivant, comme l'an dernier. La rue n'attend que vous : venez nombreux, venez curieux.",
        questions: [
                            Exercise(id: "fr-read-fete-rue-ecoles-q1", kind: "written", prompt: "Jusqu'à quelle heure la rue sera-t-elle piétonne ?", options: [], answers: ["vingt-deux heures", "22 heures", "22h", "vingt deux heures"], explain: "« La rue des Écoles sera piétonne de dix heures à vingt-deux heures. »"),
                            Exercise(id: "fr-read-fete-rue-ecoles-q2", kind: "choice", prompt: "Que se passe-t-il à quatorze heures ?", options: ["Un atelier réparation de vélos", "Le repas partagé", "Le marché des créateurs", "Le tournoi de pétanque"], answers: ["Un atelier réparation de vélos"], explain: "« Un atelier réparation de vélos à quatorze heures. »"),
                            Exercise(id: "fr-read-fete-rue-ecoles-q3", kind: "choice", prompt: "Où les habitants peuvent-ils s'inscrire pour exposer ?", options: ["À la boulangerie du coin", "À la mairie", "À l'école", "Sur place, le jour même"], answers: ["À la boulangerie du coin"], explain: "« S'inscrire jusqu'au 7 juin à la boulangerie du coin. »"),
                            Exercise(id: "fr-read-fete-rue-ecoles-q4", kind: "written", prompt: "Combien de volontaires cherche-t-on pour l'installation ?", options: [], answers: ["quatre", "4", "quatre volontaires"], explain: "« On cherche encore quatre volontaires. »"),
                            Exercise(id: "fr-read-fete-rue-ecoles-q5", kind: "choice", prompt: "Que se passe-t-il s'il pleut ?", options: ["La fête est reportée au samedi suivant", "La fête est annulée", "La fête se passe à l'intérieur", "Le programme change seulement"], answers: ["La fête est reportée au samedi suivant"], explain: "« La fête sera reportée au samedi suivant, comme l'an dernier. »")], skills: ["reading:detail", "reading:scan", "function:express-opinion", "grammar:connectors"]),
    ReadingText(id: "fr-read-tribune-trotinettes", languageID: "fr", title: "Tribune : les trottinettes à la croisée des chemins", level: "B2", topic: "opinion", unitID: "fr-foundations-u8",
        text: "Faut-il bannir les trottinettes libres-service de nos villes ? La question mérite mieux qu'un réflexe. D'un côté, le constat est sévère : des engins abandonnés sur les trottoirs, des piétons qui trébuchent, des accidents dont les urgences gardent la trace. De l'autre, la trottinette comble un vide réel : le trajet de trois kilomètres, trop long à pied, trop court en voiture. Si nous supprimions le service sans rien proposer, nous punirions une pratique utile pour des abus réels mais gérables. La solution n'est pas l'interdiction, elle est la discipline : des stations obligatoires, une vitesse bridée dans les zones piétonnes, une amende qui pique pour les dépôts sauvages. Les villes qui ont imposé ces règles constatent des trottoirs rendus aux piétons sans faire disparaître l'offre. Bannissons donc les abus, pas l'objet : c'est le devoir d'une ville qui se veut moderne de corriger avant de condamner.",
        questions: [
                            Exercise(id: "fr-read-tribune-trotinettes-q1", kind: "choice", prompt: "Quelle est la thèse de la tribune ?", options: ["Encadrer les trottinettes plutôt que les interdire", "Interdire immédiatement les trottinettes", "Laisser la situation telle quelle", "Réduire le nombre de piétons"], answers: ["Encadrer les trottinettes plutôt que les interdire"], explain: "« La solution n'est pas l'interdiction, elle est la discipline. »"),
                            Exercise(id: "fr-read-tribune-trotinettes-q2", kind: "written", prompt: "Quel trajet la trottinette comble-t-elle selon l'auteur ?", options: [], answers: ["le trajet de trois kilomètres", "trois kilomètres", "3 km", "le trajet de 3 kilomètres"], explain: "« Le trajet de trois kilomètres, trop long à pied, trop court en voiture. »"),
                            Exercise(id: "fr-read-tribune-trotinettes-q3", kind: "choice", prompt: "Quelles mesures l'auteur propose-t-il ?", options: ["Stations obligatoires, vitesse bridée, amende", "Une interdiction la nuit", "Des trottinettes gratuites", "Plus de pistes cyclables seulement"], answers: ["Stations obligatoires, vitesse bridée, amende"], explain: "« Des stations obligatoires, une vitesse bridée… une amende qui pique. »"),
                            Exercise(id: "fr-read-tribune-trotinettes-q4", kind: "written", prompt: "Que constatent les villes qui ont imposé ces règles ?", options: [], answers: ["des trottoirs rendus aux piétons", "les trottoirs rendus aux piétons", "trottoirs rendus aux piétons"], explain: "« Des trottoirs rendus aux piétons sans faire disparaître l'offre. »"),
                            Exercise(id: "fr-read-tribune-trotinettes-q5", kind: "choice", prompt: "Avec quelle maxime l'auteur conclut-il ?", options: ["Corriger avant de condamner", "Interdire pour protéger", "Laisser faire le marché", "Punir les piétons"], answers: ["Corriger avant de condamner"], explain: "« C'est le devoir… de corriger avant de condamner. »")], skills: ["reading:inference", "writing:argument", "grammar:second-conditional", "grammar:connectors"]),
    ReadingText(id: "fr-read-negociation-scene-ouverte", languageID: "fr", title: "Dossier : une scène ouverte au marché couvert", level: "B2", topic: "négociation", unitID: "fr-foundations-u7",
        text: "Le marché couvert pourrait accueillir une scène ouverte le samedi soir. Le dossier, porté par l'association Les Commerçants debout, prévoit deux heures de musique par semaine, dix-huit heures de montage assurées par des bénévoles et une jauge limitée à deux cents personnes. La chambre des commerçants pose ses conditions : le stationnement des vendeurs doit rester possible jusqu'à midi, le bruit doit cesser à vingt-deux heures précises et l'association devra souscrire une assurance responsabilité civile. En échange, la mairie étudie une prise en charge du nettoyage du dimanche matin, à condition que la scène teste son projet pendant six mois. Si le bilan s'avère positif — fréquentation des étals, aucun incident, Budget respecté —, la convention sera reconduite pour une année complète. Le vote aura lieu le mois prochain ; les riverains seront invités à s'exprimer avant, parce qu'une scène ouverte se négocie aussi avec ceux qui dorment au-dessus.",
        questions: [
                            Exercise(id: "fr-read-negociation-scene-ouverte-q1", kind: "written", prompt: "Combien de personnes la jauge limite-t-elle ?", options: [], answers: ["deux cents", "200", "deux cents personnes", "200 personnes"], explain: "« Une jauge limitée à deux cents personnes. »"),
                            Exercise(id: "fr-read-negociation-scene-ouverte-q2", kind: "choice", prompt: "Quelle condition concerne les vendeurs du marché ?", options: ["Leur stationnement reste possible jusqu'à midi", "Ils doivent animer la scène", "Ils paient la musique", "Ils ferment à dix-huit heures"], answers: ["Leur stationnement reste possible jusqu'à midi"], explain: "« Le stationnement des vendeurs doit rester possible jusqu'à midi. »"),
                            Exercise(id: "fr-read-negociation-scene-ouverte-q3", kind: "choice", prompt: "Que propose la mairie en échange ?", options: ["La prise en charge du nettoyage du dimanche", "Une subvention de dix mille euros", "Du matériel sonore", "Un local permanent"], answers: ["La prise en charge du nettoyage du dimanche"], explain: "« La mairie étudie une prise en charge du nettoyage du dimanche matin. »"),
                            Exercise(id: "fr-read-negociation-scene-ouverte-q4", kind: "written", prompt: "Pendant combien de temps le projet doit-il être testé ?", options: [], answers: ["six mois", "6 mois", "pendant six mois"], explain: "« À condition que la scène teste son projet pendant six mois. »"),
                            Exercise(id: "fr-read-negociation-scene-ouverte-q5", kind: "choice", prompt: "Pourquoi les riverains seront-ils consultés ?", options: ["Parce qu'ils vivent au-dessus du marché", "Parce qu'ils financent le projet", "Parce que la loi l'exige", "Parce qu'ils sont opposés au projet"], answers: ["Parce qu'ils vivent au-dessus du marché"], explain: "« Une scène ouverte se négocie aussi avec ceux qui dorment au-dessus. »")], skills: ["reading:inference", "function:negotiate", "grammar:first-conditional", "grammar:connectors"]),
    ReadingText(id: "it-read-gruppo-camminata", languageID: "it", title: "Il gruppo di camminata", level: "A1", topic: "salute", unitID: "it-foundations-u2",
        text: "Il martedì, il quartiere organizza una camminata gratis. Parte alle nove dalla piazza e arriva fino al fiume. Il gruppo è misto: ci sono studenti, famiglie e pensionati. Nessuno corre; l'idea è camminare e parlare. Alla fine, chi vuole fa colazione insieme in un bar del mercato. Giulia ci va da un mese e ha già tre amici nuovi. Dice che è il momento più tranquillo della sua settimana.",
        questions: [
                            Exercise(id: "it-read-gruppo-camminata-q1", kind: "choice", prompt: "Quando c'è la camminata ?", options: ["Il martedì", "Il lunedì", "Il sabato", "Tutti i giorni"], answers: ["Il martedì"], explain: "Il martedì, il quartiere organizza una camminata gratis."),
                            Exercise(id: "it-read-gruppo-camminata-q2", kind: "written", prompt: "A che ora parte ?", options: [], answers: ["alle nove", "le nove", "nove"], explain: "Parte alle nove dalla piazza."),
                            Exercise(id: "it-read-gruppo-camminata-q3", kind: "choice", prompt: "Chi partecipa ?", options: ["Studenti, famiglie e pensionati", "Solo studenti", "Solo pensionati", "Solo famiglie"], answers: ["Studenti, famiglie e pensionati"], explain: "Il gruppo è misto."),
                            Exercise(id: "it-read-gruppo-camminata-q4", kind: "choice", prompt: "Cosa fa chi vuole alla fine ?", options: ["Fa colazione insieme", "Corre al fiume", "Torna a casa", "Prende l'autobus"], answers: ["Fa colazione insieme"], explain: "Fa colazione insieme in un bar del mercato."),
                            Exercise(id: "it-read-gruppo-camminata-q5", kind: "written", prompt: "Da quanto tempo ci va Giulia ?", options: [], answers: ["un mese", "1 mese"], explain: "Giulia ci va da un mese.")], skills: ["reading:detail", "reading:scan", "grammar:present-simple", "vocab:daily-routine"]),
    ReadingText(id: "it-read-annuncio-appartamento", languageID: "it", title: "L'annuncio dell'appartamento", level: "A2", topic: "appartamenti", unitID: "it-foundations-u4",
        text: "Appartamento luminoso di due camere in affitto da settembre. È al terzo piano, con ascensore, e ha un balcone che dà sul cortile, quindi è tranquillo. Il salotto è più grande della cucina, ma la cucina ha la finestra. Il quartiere ha il mercato il sabato e la fermata della metro è a cinque minuti. Non è il meno costoso della zona, ma è il migliore illuminato. Si chiede un mese di caparra e si preferisce qualcuno che lavori da casa, come gli attuali proprietari.",
        questions: [
                            Exercise(id: "it-read-annuncio-appartamento-q1", kind: "choice", prompt: "Quando è disponibile ?", options: ["Da settembre", "Da agosto", "Subito", "A gennaio"], answers: ["Da settembre"], explain: "In affitto da settembre."),
                            Exercise(id: "it-read-annuncio-appartamento-q2", kind: "choice", prompt: "Perché è tranquillo ?", options: ["Dà sul cortile", "È al piano terra", "Non ha vicini", "È in campagna"], answers: ["Dà sul cortile"], explain: "Il balcone dà sul cortile, quindi è tranquillo."),
                            Exercise(id: "it-read-annuncio-appartamento-q3", kind: "written", prompt: "A quanti minuti c'è la metro ?", options: [], answers: ["cinque minuti", "5 minuti", "cinque"], explain: "La fermata della metro è a cinque minuti."),
                            Exercise(id: "it-read-annuncio-appartamento-q4", kind: "choice", prompt: "Com'è rispetto alla zona ?", options: ["Non il meno costoso, ma il migliore illuminato", "Il meno costoso", "Il meno illuminato", "Il più piccolo"], answers: ["Non il meno costoso, ma il migliore illuminato"], explain: "Non è il meno costoso, ma è il migliore illuminato."),
                            Exercise(id: "it-read-annuncio-appartamento-q5", kind: "choice", prompt: "Chi preferiscono i proprietari ?", options: ["Qualcuno che lavori da casa", "Studenti", "Famiglie con bambini", "Pensionati"], answers: ["Qualcuno che lavori da casa"], explain: "Si preferisce qualcuno che lavori da casa.")], skills: ["reading:detail", "reading:inference", "grammar:comparatives"], exposureSkills: ["grammar:superlatives"]),
    ReadingText(id: "it-read-viaggio-indimenticabile", languageID: "it", title: "Il viaggio indimenticabile", level: "B1", topic: "viaggi", unitID: "it-foundations-u6",
        text: "L'estate scorsa ho fatto il viaggio dei miei sogni: quindici giorni in Perù. Avevo già visitato il Messico e l'Argentina, ma il Sud America mi ha ancora sorpreso. Il terzo giorno sono salito al Machu Picchu. C'era nebbia, così all'inizio non si vedeva niente. Poi, poco a poco, è uscito il sole ed è apparsa la città intera. Non ho detto niente; sono rimasto a guardare. Sul treno del ritorno ho conosciuto una famiglia di Cusco, e mi hanno invitato a cena. « I viaggiatori dicono sempre la stessa cosa », ha riso la nonna, « ma questa zuppa è vera ». Aveva ragione: è stata la migliore cena del viaggio. Da allora, ogni volta che qualcuno chiede una destinazione, io rispondo il Perù.",
        questions: [
                            Exercise(id: "it-read-viaggio-indimenticabile-q1", kind: "choice", prompt: "Quanto è durato il viaggio ?", options: ["Quindici giorni", "Dieci giorni", "Un mese", "Tre giorni"], answers: ["Quindici giorni"], explain: "Quindici giorni in Perù."),
                            Exercise(id: "it-read-viaggio-indimenticabile-q2", kind: "written", prompt: "Quali paesi aveva già visitato ?", options: [], answers: ["messico e argentina", "il messico e l'argentina"], explain: "Avevo già visitato il Messico e l'Argentina."),
                            Exercise(id: "it-read-viaggio-indimenticabile-q3", kind: "choice", prompt: "Perché non si vedeva niente all'inizio ?", options: ["C'era nebbia", "Era chiuso", "Pioveva forte", "Era di notte"], answers: ["C'era nebbia"], explain: "C'era nebbia, così non si vedeva niente."),
                            Exercise(id: "it-read-viaggio-indimenticabile-q4", kind: "choice", prompt: "Con chi ha cenato il narratore ?", options: ["Con una famiglia di Cusco", "Con la nonna dell'albergo", "Da solo", "Con amici del treno"], answers: ["Con una famiglia di Cusco"], explain: "Ho conosciuto una famiglia di Cusco e mi hanno invitato a cena."),
                            Exercise(id: "it-read-viaggio-indimenticabile-q5", kind: "written", prompt: "Cosa risponde ora quando gli chiedono una destinazione ?", options: [], answers: ["peru", "perù", "il peru", "il perù"], explain: "Io rispondo il Perù.")], skills: ["reading:inference", "grammar:present-perfect", "grammar:connectors", "vocab:travel"]),
    ReadingText(id: "it-read-colonna-pedonale", languageID: "it", title: "Colonna: pedonalizziamo", level: "B2", topic: "opinione", unitID: "it-foundations-u8",
        text: "Penso che dovremmo pedonalizzare il centro. Da un lato, calerebbe il rumore: i residenti della piazza chiedono silenzio da anni. Dall'altro, calerebbe l'inquinamento, che supera già i limiti legali. È vero che i negozianti temono di perdere clienti, ma i numeri di altre città dicono il contrario: dove sparisce l'auto, la gente cammina di più e compra di più. La società il cui rapporto è stato pubblicato il mese scorso ha calcolato un 15 % di vendite in più nelle strade senza traffico. Per tutto questo, difendo la misura: se avessimo il coraggio di provarla un anno, non vorremmo più tornare indietro.",
        questions: [
                            Exercise(id: "it-read-colonna-pedonale-q1", kind: "choice", prompt: "Qual è la tesi della colonna ?", options: ["Pedonalizzare il centro", "Allargare l'autostrada", "Vietare le bici", "Costruire un parcheggio"], answers: ["Pedonalizzare il centro"], explain: "« Penso che dovremmo pedonalizzare il centro »."),
                            Exercise(id: "it-read-colonna-pedonale-q2", kind: "written", prompt: "Cosa supera già i limiti legali ?", options: [], answers: ["l'inquinamento", "inquinamento"], explain: "L'inquinamento supera i limiti legali."),
                            Exercise(id: "it-read-colonna-pedonale-q3", kind: "choice", prompt: "Di cosa hanno paura i negozianti ?", options: ["Di perdere clienti", "Di pagare più tasse", "Di chiudere d'estate", "Di traslocare"], answers: ["Di perdere clienti"], explain: "Temono di perdere clienti."),
                            Exercise(id: "it-read-colonna-pedonale-q4", kind: "written", prompt: "Quanto in più venderebbero le strade senza traffico ?", options: [], answers: ["15%", "un 15%", "quindici per cento", "15 per cento"], explain: "Un 15 % di vendite in più."),
                            Exercise(id: "it-read-colonna-pedonale-q5", kind: "choice", prompt: "Cosa propone l'autore alla fine ?", options: ["Provarla un anno", "Dimenticare il piano", "Multare di più", "Votare ancora"], answers: ["Provarla un anno"], explain: "« Se avessimo il coraggio di provarla un anno ».")], skills: ["reading:inference", "writing:argument", "grammar:connectors", "grammar:second-conditional"]),
    ReadingText(id: "it-read-saggio-citta", languageID: "it", title: "Saggio: la città che cammina", level: "C1", topic: "città", unitID: "it-foundations-u9",
        text: "La città che cammina è, per così dire, una città che pensa. Negli ultimi decenni abbiamo sacrificato lo spazio pubblico alla velocità: parcheggi dove potevano crescere alberi, corsie dove potevano stare i bambini. Non si tratta di nostalgia, bensì di equilibrio. Le città che hanno ridotto il traffico nel centro storico — Oslo, Pontevedra — non hanno registrato il collasso commerciale temuto; hanno anzi visto crescere i piccoli commerci, che vivono di passanti lenti. A mio avviso, il vero ostacolo non è economico ma culturale: confondiamo la libertà di muoversi in auto con la libertà di abitare la città. In sintesi, ridisegnare le strade significa decidere chi le strade devono servire: se la risposta sono le persone, il resto è tecnica.",
        questions: [
                            Exercise(id: "it-read-saggio-citta-q1", kind: "choice", prompt: "Qual è la tesi centrale del saggio?", options: ["Ridisegnare le strade per le persone", "Difendere la velocità in auto", "Tornare al passato per nostalgia", "Spostare i negozi fuori città"], answers: ["Ridisegnare le strade per le persone"], explain: "« Ridisegnare le strade significa decidere chi devono servire »."),
                            Exercise(id: "it-read-saggio-citta-q2", kind: "choice", prompt: "Come definisce l'autore il vero ostacolo?", options: ["Culturale, non economico", "Economico, non culturale", "Tecnico e inevitabile", "Politico e temporaneo"], answers: ["Culturale, non economico"], explain: "« Il vero ostacolo non è economico ma culturale »."),
                            Exercise(id: "it-read-saggio-citta-q3", kind: "written", prompt: "Cosa hanno visto crescere le città che hanno ridotto il traffico?", options: [], answers: ["i piccoli commerci", "piccoli commerci", "i piccoli esercizi commerciali"], explain: "Hanno visto crescere i piccoli commerci."),
                            Exercise(id: "it-read-saggio-citta-q4", kind: "choice", prompt: "Quali città vengono citate come esempio?", options: ["Oslo e Pontevedra", "Roma e Milano", "Parigi e Berlino", "Osaka e Kyoto"], answers: ["Oslo e Pontevedra"], explain: "Citati Oslo e Pontevedra."),
                            Exercise(id: "it-read-saggio-citta-q5", kind: "written", prompt: "Con cosa confondiamo, secondo l'autore, la libertà di abitare la città?", options: [], answers: ["con la liberta di muoversi in auto", "con la libertà di muoversi in auto", "muoversi in auto"], explain: "Con la libertà di muoversi in auto."),
                            Exercise(id: "it-read-saggio-citta-q6", kind: "choice", prompt: "Che funzione ha « bensì » nel testo?", options: ["Contrastare dopo una negazione", "Aggiungere un esempio", "Introdurre una causa", "Chiudere il ragionamento"], answers: ["Contrastare dopo una negazione"], explain: "« Non… bensì »: correzione dopo la negazione.")], skills: ["reading:inference", "writing:argument", "grammar:connectors", "vocab:collocations"]),
    ReadingText(id: "it-read-lettera-dirigenza", languageID: "it", title: "Lettera alla dirigenza", level: "C1", topic: "lavoro", unitID: "it-foundations-u9",
        text: "Gentile Direzione, Le scrivo per conto del gruppo operativo per sottoporreLe una proposta sul lavoro ibrido. Nei sei mesi di sperimentazione, i rilasci sono stati puntuali e i tempi di risposta sono rimasti stabili; peraltro, il sondaggio interno mostra un netto miglioramento del benessere dichiarato. È vero che alcuni processi, per così dire faccia a faccia, richiedono presenza: pertanto proponiamo tre giorni in sede per i team di produzione e due per gli altri reparti. In sintesi, chiediamo di rendere strutturale quanto finora sperimentato, con una revisione semestrale. Restiamo a Sua completa disposizione per presentare i dati in riunione e La ringraziamo sin d'ora per l'attenzione. Distinti saluti, Il gruppo operativo.",
        questions: [
                            Exercise(id: "it-read-lettera-dirigenza-q1", kind: "choice", prompt: "Cosa chiede il gruppo operativo?", options: ["Rendere strutturale il lavoro ibrido", "Tornare tutti in ufficio cinque giorni", "Assumere nuovo personale", "Posticipare la sperimentazione"], answers: ["Rendere strutturale il lavoro ibrido"], explain: "« Chiediamo di rendere strutturale quanto finora sperimentato »."),
                            Exercise(id: "it-read-lettera-dirigenza-q2", kind: "written", prompt: "Quanti giorni in sede propongono per i team di produzione?", options: [], answers: ["tre", "3", "tre giorni"], explain: "Tre giorni in sede."),
                            Exercise(id: "it-read-lettera-dirigenza-q3", kind: "choice", prompt: "Quali dati portano a favore?", options: ["Rilasci puntuali e tempi di risposta stabili", "Vendite raddoppiate", "Meno ferie richieste", "Più clienti acquisiti"], answers: ["Rilasci puntuali e tempi di risposta stabili"], explain: "Rilasci puntuali, tempi stabili, benessere in crescita."),
                            Exercise(id: "it-read-lettera-dirigenza-q4", kind: "choice", prompt: "Quale concessione fa la lettera?", options: ["Alcuni processi richiedono la presenza", "Il sondaggio è inaffidabile", "I tempi sono peggiorati", "La proposta è solo teorica"], answers: ["Alcuni processi richiedono la presenza"], explain: "« È vero che alcuni processi richiedono presenza »."),
                            Exercise(id: "it-read-lettera-dirigenza-q5", kind: "written", prompt: "Con quale frequenza chiedono la revisione?", options: [], answers: ["semestrale", "ogni sei mesi", "una revisione semestrale"], explain: "Revisione semestrale."),
                            Exercise(id: "it-read-lettera-dirigenza-q6", kind: "choice", prompt: "Che funzione ha « peraltro »?", options: ["Aggiungere un argomento a favore", "Contrastare quanto detto", "Annunciare la conclusione", "Esprimere un dubbio"], answers: ["Aggiungere un argomento a favore"], explain: "Peraltro: argomento aggiuntivo.")], skills: ["reading:detail", "reading:scan", "vocab:work", "grammar:connectors"]),
    ReadingText(id: "it-read-recensione-critica", languageID: "it", title: "Recensione critica", level: "C1", topic: "cultura", unitID: "it-foundations-u9",
        text: "Al debutto, il romanzo di Vera Antonelli affascina: una voce netta, un quartiere di periferia ricostruito con precisione chirurgica. A metà libro, però, la trama incrina: la protagonista, che aveva deciso da sola, improvvisamente si affida al caso, e il lettore perde il gusto di accompagnarla. Non è un difetto minore, perché la forza del romanzo stava proprio in quella volontà. In un certo senso, l'autrice ha scelto la strada più comoda proprio quando il lettore le aveva concesso la più difficile. Eppure il finale riesce: le ultime trenta pagine, quasi senza dialoghi, tengono insieme ciò che il centro aveva disfatto. A mio avviso, Antonelli è una scrittrice da seguire: questo romanzo è una promessa più che un risultato, ma di promesse così se ne vedono poche.",
        questions: [
                            Exercise(id: "it-read-recensione-critica-q1", kind: "choice", prompt: "Che difetto segnala la recensora a metà libro?", options: ["La protagonista si affida al caso", "Troppi dialoghi", "Un finale frettoloso", "Un'ambientazione confusa"], answers: ["La protagonista si affida al caso"], explain: "La protagonista improvvisamente si affida al caso."),
                            Exercise(id: "it-read-recensione-critica-q2", kind: "choice", prompt: "Come giudica il finale?", options: ["Riesce a tenere insieme il romanzo", "Rovina tutto", "È troppo lungo", "Manca del tutto"], answers: ["Riesce a tenere insieme il romanzo"], explain: "« Il finale riesce » e tiene insieme il romanzo."),
                            Exercise(id: "it-read-recensione-critica-q3", kind: "written", prompt: "Quante pagine finali tengono insieme il romanzo?", options: [], answers: ["trenta", "30", "le ultime trenta pagine"], explain: "Le ultime trenta pagine."),
                            Exercise(id: "it-read-recensione-critica-q4", kind: "choice", prompt: "Che senso ha « una promessa più che un risultato »?", options: ["Il talento c'è, ma il libro non lo esaurisce", "Il libro è un fallimento", "È un libro per giovani lettori", "È una biografia"], answers: ["Il talento c'è, ma il libro non lo esaurisce"], explain: "Talento reale, risultato non ancora pieno."),
                            Exercise(id: "it-read-recensione-critica-q5", kind: "written", prompt: "Dove stava la forza del romanzo secondo la recensora?", options: [], answers: ["nella volonta della protagonista", "nella volontà della protagonista", "nella determinazione della protagonista"], explain: "Nella volontà della protagonista."),
                            Exercise(id: "it-read-recensione-critica-q6", kind: "choice", prompt: "Che tono ha la recensione?", options: ["Critico ma benevolo", "Ostile", "Entusiasta senza riserve", "Indifferente"], answers: ["Critico ma benevolo"], explain: "Rilievi severi, chiusura incoraggiante.")], skills: ["reading:inference", "reading:detail", "function:express-opinion", "vocab:collocations"]),
    ReadingText(id: "it-read-annuncio-coinquilino", languageID: "it", title: "Cerco un coinquilino", level: "A1", topic: "casa", unitID: "it-foundations-u10",
        text: "CERCO COINQUILINO — L'appartamento è in via Verdi 10, vicino al parco. Ci sono due camere, una cucina e un bagno. La mia camera è piccola; la tua camera è grande e luminosa. C'è un divano nel soggiorno e ci sono due bici nel balcone. Il mio gatto si chiama Micio. Io lavoro in una libreria e sono tranquillo. Il tuo affitto è di 300 euro. Scrivimi a micio@posta.it !",
        questions: [
                            Exercise(id: "it-read-annuncio-coinquilino-q1", kind: "choice", prompt: "Quante camere ci sono nell'appartamento ?", options: ["Due", "Una", "Tre", "Quattro"], answers: ["Due"], explain: "« Ci sono due camere, una cucina e un bagno »."),
                            Exercise(id: "it-read-annuncio-coinquilino-q2", kind: "choice", prompt: "Com'è la camera del nuovo coinquilino ?", options: ["Grande e luminosa", "Piccola e scura", "Piccola e luminosa", "Senza finestre"], answers: ["Grande e luminosa"], explain: "« La tua camera è grande e luminosa »."),
                            Exercise(id: "it-read-annuncio-coinquilino-q3", kind: "written", prompt: "Com'è la camera di chi scrive ?", options: [], answers: ["piccola", "e piccola", "la camera e piccola"], explain: "« La mia camera è piccola »."),
                            Exercise(id: "it-read-annuncio-coinquilino-q4", kind: "written", prompt: "Dov'è l'appartamento ?", options: [], answers: ["in via Verdi 10", "via Verdi 10", "in via Verdi dieci"], explain: "« L'appartamento è in via Verdi 10 »."),
                            Exercise(id: "it-read-annuncio-coinquilino-q5", kind: "choice", prompt: "Quanto costa l'affitto ?", options: ["300 euro", "30 euro", "350 euro", "Non è scritto"], answers: ["300 euro"], explain: "« Il tuo affitto è di 300 euro ».")], skills: ["reading:detail", "reading:scan", "grammar:possessives", "vocab:home", "function:describe-people"]),
    ReadingText(id: "it-read-messaggio-gruppo", languageID: "it", title: "Il gruppo del weekend", level: "A1", topic: "weekend", unitID: "it-foundations-u13",
        text: "GRUPPO « WEEKEND » — Giulia: Ragazzi, sabato c'è il sole ! Che facciamo ? Marco: Io di solito nuoto la mattina, ma questo sabato sono libero dopo le quattro. Giulia: Allora bicicletta al parco alle cinque ? Anna: Mi piace ! Io corro spesso al parco, ma in bici non vado mai. Marco: Perfetto. Dopo, pizza da Franco ? Anna: Sì ! Il sabato mangio sempre la pizza. Giulia: D'accordo: bici alle cinque e pizza alle otto !",
        questions: [
                            Exercise(id: "it-read-messaggio-gruppo-q1", kind: "choice", prompt: "Che tempo fa sabato ?", options: ["C'è il sole", "Piove", "Nevica", "Fa freddo"], answers: ["C'è il sole"], explain: "« Sabato c'è il sole »."),
                            Exercise(id: "it-read-messaggio-gruppo-q2", kind: "written", prompt: "Cosa fa di solito Marco la mattina ?", options: [], answers: ["nuota", "nuoto", "nuotare"], explain: "« Io di solito nuoto la mattina »."),
                            Exercise(id: "it-read-messaggio-gruppo-q3", kind: "choice", prompt: "Che cosa fa spesso Anna al parco ?", options: ["Corre", "Va in bici", "Legge", "Nuota"], answers: ["Corre"], explain: "« Io corro spesso al parco »."),
                            Exercise(id: "it-read-messaggio-gruppo-q4", kind: "written", prompt: "Cosa non fa mai Anna ?", options: [], answers: ["va in bici", "andare in bici", "vado in bici"], explain: "« Ma in bici non vado mai »."),
                            Exercise(id: "it-read-messaggio-gruppo-q5", kind: "choice", prompt: "A che ora è la pizza ?", options: ["Alle otto", "Alle cinque", "Alle quattro", "Alle nove"], answers: ["Alle otto"], explain: "« Bici alle cinque e pizza alle otto ».")], skills: ["reading:detail", "reading:scan", "vocab:hobbies", "vocab:daily-routine", "grammar:frequency-adverbs"]),
    ReadingText(id: "it-read-orari-metro", languageID: "it", title: "Gli orari della metro", level: "A1", topic: "trasporti", unitID: "it-foundations-u14",
        text: "Gli orari della metro. La metro apre alle sei del mattino e chiude a mezzanotte. La mattina i treni partono ogni cinque minuti: alle 6:00, alle 6:05, alle 6:10. La sera partono ogni dieci minuti. Il viaggio da Porta Nuova a Lingotto dura dieci minuti. Il biglietto costa un euro e settanta: lo compri alla macchinetta, poi lo passi alla barriera. A che ora parte il prossimo treno ? Guarda il tabellone giallo: lì trovi tutti gli orari.",
        questions: [
                            Exercise(id: "it-read-orari-metro-q1", kind: "choice", prompt: "A che ora apre la metro ?", options: ["Alle sei", "Alle sette", "A mezzanotte", "Alle otto"], answers: ["Alle sei"], explain: "« La metro apre alle sei del mattino »."),
                            Exercise(id: "it-read-orari-metro-q2", kind: "choice", prompt: "Ogni quanti minuti partono i treni la mattina ?", options: ["Ogni cinque minuti", "Ogni dieci minuti", "Ogni venti minuti", "Ogni ora"], answers: ["Ogni cinque minuti"], explain: "« La mattina i treni partono ogni cinque minuti »."),
                            Exercise(id: "it-read-orari-metro-q3", kind: "written", prompt: "Quanto dura il viaggio da Porta Nuova a Lingotto ?", options: [], answers: ["Dieci minuti", "10 minuti"], explain: "« Il viaggio dura dieci minuti »."),
                            Exercise(id: "it-read-orari-metro-q4", kind: "written", prompt: "Quanto costa il biglietto ?", options: [], answers: ["Un euro e settanta", "1 euro e 70", "Un euro e settanta centesimi"], explain: "« Il biglietto costa un euro e settanta »."),
                            Exercise(id: "it-read-orari-metro-q5", kind: "choice", prompt: "Dove trovi tutti gli orari ?", options: ["Sul tabellone giallo", "Sul biglietto", "Alla barriera", "Sulla macchinetta"], answers: ["Sul tabellone giallo"], explain: "« Guarda il tabellone giallo: lì trovi tutti gli orari ».")], skills: ["reading:detail", "reading:scan", "vocab:transport", "function:tell-time"]),
    ReadingText(id: "it-read-fila-messaggi", languageID: "it", title: "La fila di messaggi", level: "A2", topic: "inviti", unitID: "it-foundations-u17",
        text: "Sara: Ciao Marco ! Sabato è il compleanno di Giulia. Le facciamo una sorpresa ? / Marco: Volentieri ! Cosa le regaliamo ? / Sara: Le piace la fotografia. Vado a cercare un libro di foto. Tu ? / Marco: Io vado a preparare la torta al cioccolato. Peccato: sabato lavoro fino alle sette. / Sara: Nessun problema: la festa è alle otto, da Luca. / Marco: Perfetto, ci sono ! Ma Giulia non sa niente, vero ? / Sara: Shh… è una sorpresa !",
        questions: [
                            Exercise(id: "it-read-fila-messaggi-q1", kind: "choice", prompt: "Chi compie gli anni ?", options: ["Giulia", "Sara", "Marco", "Luca"], answers: ["Giulia"], explain: "Sabato è il compleanno di Giulia."),
                            Exercise(id: "it-read-fila-messaggi-q2", kind: "choice", prompt: "Cosa va a preparare Marco ?", options: ["La torta al cioccolato", "Un libro di foto", "I fiori", "La musica"], answers: ["La torta al cioccolato"], explain: "Io vado a preparare la torta al cioccolato."),
                            Exercise(id: "it-read-fila-messaggi-q3", kind: "written", prompt: "A che ora è la festa ?", options: [], answers: ["alle otto", "otto", "8"], explain: "La festa è alle otto, da Luca."),
                            Exercise(id: "it-read-fila-messaggi-q4", kind: "choice", prompt: "Perché Marco dice « peccato » ?", options: ["Lavora fino alle sette", "Non ha la macchina", "È a letto malato", "Viene in ritardo"], answers: ["Lavora fino alle sette"], explain: "Peccato: sabato lavoro fino alle sette."),
                            Exercise(id: "it-read-fila-messaggi-q5", kind: "choice", prompt: "Giulia sa della festa ?", options: ["No, è una sorpresa", "Sì, organizza lei", "Sì, ha scritto lei", "Solo Luca lo sa"], answers: ["No, è una sorpresa"], explain: "« Giulia non sa niente, vero ? » « Shh… è una sorpresa ! »")], skills: ["reading:detail", "reading:inference", "vocab:social-expressions", "grammar:going-to"]),
    ReadingText(id: "it-read-recensione-guasto", languageID: "it", title: "La recensione della macchina guasta", level: "A2", topic: "recensioni", unitID: "it-foundations-u20",
        text: "Due stelle. Ho comprato questa macchina per il caffè il mese scorso e all’inizio funzionava bene. Poi, lunedì, si è rotta: l’acqua non saliva più e il caffè era freddo. Ho chiamato il servizio clienti tre volte, ma nessuno ha risposto. Alla fine ho scritto un’email e in due giorni ho ricevuto una risposta gentile: una macchina nuova arriva questa settimana. Meno male ! Il caffè, poi, era buono. Se la nuova funziona, cambio la recensione. Consigliata solo a chi ha pazienza.",
        questions: [
                            Exercise(id: "it-read-recensione-guasto-q1", kind: "choice", prompt: "Che cosa si è rotta ?", options: ["La macchina per il caffè", "Il telefono", "La lavatrice", "L’email"], answers: ["La macchina per il caffè"], explain: "« Si è rotta: l’acqua non saliva più »."),
                            Exercise(id: "it-read-recensione-guasto-q2", kind: "written", prompt: "Quante volte ha chiamato il servizio clienti ?", options: [], answers: ["tre volte", "3 volte"], explain: "« Ho chiamato il servizio clienti tre volte »."),
                            Exercise(id: "it-read-recensione-guasto-q3", kind: "choice", prompt: "Che soluzione ha ricevuto ?", options: ["Una macchina nuova", "Un rimborso", "Un tecnico a casa", "Un caffè gratis"], answers: ["Una macchina nuova"], explain: "« Una macchina nuova arriva questa settimana »."),
                            Exercise(id: "it-read-recensione-guasto-q4", kind: "choice", prompt: "Quando è arrivata la risposta gentile ?", options: ["In due giorni", "In tre ore", "In una settimana", "Dopo un mese"], answers: ["In due giorni"], explain: "« In due giorni ho ricevuto una risposta gentile »."),
                            Exercise(id: "it-read-recensione-guasto-q5", kind: "choice", prompt: "Come giudica il caffè, la recensora ?", options: ["Buono", "Brutto", "Freddo", "Non lo dice"], answers: ["Buono"], explain: "« Il caffè, poi, era buono ».")], skills: ["reading:detail", "reading:inference", "function:solve-problems", "grammar:past-simple-regular"]),
    ReadingText(id: "it-read-lista-valigia", languageID: "it", title: "La lista della valigia", level: "A2", topic: "liste e viaggi", unitID: "it-foundations-u25",
        text: "Parto sabato per Lisbona e questa è la mia lista. Documenti: passaporto, carta d’identità e prenotazioni dell’albergo, già stampate. Vestiti: due magliette, un maglione leggero e una giacca, perché ad ottobre piove spesso. Cose tecniche: telefono, caricatore e adattatore — l’anno scorso l’ho dimenticato a casa e ho pagato troppo per uno nuovo. Salute: cerotti e le medicine per la testa. La regola della casa: la valigia pesa meno di venti chili, quindi metto solo l’indispensabile. Domani faccio il check-in online e controllo i biglietti un’ultima volta. Venerdì sera chiudo tutto e vado a letto presto: due ore prima all’aeroporto non si sbaglia.",
        questions: [
                            Exercise(id: "it-read-lista-valigia-q1", kind: "choice", prompt: "Quando parte il viaggiatore ?", options: ["Sabato", "Venerdì", "Domenica", "Lunedì"], answers: ["Sabato"], explain: "« Parto sabato per Lisbona »."),
                            Exercise(id: "it-read-lista-valigia-q2", kind: "written", prompt: "Che cosa ha dimenticato l’anno scorso ?", options: [], answers: ["l’adattatore", "l adattatore", "adattatore"], explain: "« L’anno scorso l’ho dimenticato a casa »."),
                            Exercise(id: "it-read-lista-valigia-q3", kind: "choice", prompt: "Perché porta un maglione leggero ?", options: ["Perché ad ottobre piove spesso", "Perché fa caldo", "Perché va in montagna", "Perché l’albergo è freddo"], answers: ["Perché ad ottobre piove spesso"], explain: "« Una giacca, perché ad ottobre piove spesso »."),
                            Exercise(id: "it-read-lista-valigia-q4", kind: "written", prompt: "Quanto può pesare la valigia ?", options: [], answers: ["meno di venti chili", "venti chili", "20 chili", "meno di 20 chili"], explain: "« La valigia pesa meno di venti chili »."),
                            Exercise(id: "it-read-lista-valigia-q5", kind: "choice", prompt: "Che cosa fa domani ?", options: ["Il check-in online", "La valigia nuova", "I biglietti nuovi", "Le fotocopie"], answers: ["Il check-in online"], explain: "« Domani faccio il check-in online ».")], skills: ["reading:detail", "reading:scan", "grammar:going-to", "vocab:travel"]),
    ReadingText(id: "it-read-locandina-quartiere", languageID: "it", title: "La locandina dell’assemblea", level: "B1", topic: "città e partecipazione", unitID: "it-foundations-u26",
        text: "LA PIAZZA CHE VOGLIAMO — Assemblea aperta, giovedì alle 18.30, cortile della scuola Garibaldi. Il comitato propone: zona pedonale nella piazza Nucci dal venerdì alla domenica, trenta nuovi posti auto in via Ferretti e cinquanta alberi nei cortili interni. Perché ? Perché oggi il settanta per cento dei clienti arriva a piedi o in bici, ma i negozi temono per il weekend. Da un lato meno traffico e più spazio per i bambini; dall’altro il timore dei commercianti. Per questo proponiamo un test di sei mesi: poi si valuta con i numeri, non con le opinioni. Venite numerosi: il quartiere si costruisce anche con le vostre firme. Informazioni: comitato@quartierenucci.it",
        questions: [
                            Exercise(id: "it-read-locandina-quartiere-q1", kind: "written", prompt: "In che giorno e a che ora si tiene l’assemblea ?", options: [], answers: ["giovedì alle 18.30", "giovedi alle 18.30", "giovedì alle 18:30", "giovedi alle 18:30"], explain: "« Assemblea aperta, giovedì alle 18.30 »."),
                            Exercise(id: "it-read-locandina-quartiere-q2", kind: "choice", prompt: "Che cosa propone il comitato per i weekend ?", options: ["La zona pedonale nella piazza", "Il mercato al coperto", "Più fermate del bus", "Nuove strade"], answers: ["La zona pedonale nella piazza"], explain: "« Zona pedonale nella piazza Nucci dal venerdì alla domenica »."),
                            Exercise(id: "it-read-locandina-quartiere-q3", kind: "written", prompt: "Quanti posti auto nuovi sono previsti e dove ?", options: [], answers: ["trenta in via ferretti", "trenta posti in via ferretti", "30 in via ferretti", "trenta posti nuovi in via ferretti"], explain: "« Trenta nuovi posti auto in via Ferretti »."),
                            Exercise(id: "it-read-locandina-quartiere-q4", kind: "choice", prompt: "Quanto dura il test proposto ?", options: ["Sei mesi", "Tre mesi", "Un anno", "Sei settimane"], answers: ["Sei mesi"], explain: "« Un test di sei mesi »."),
                            Exercise(id: "it-read-locandina-quartiere-q5", kind: "choice", prompt: "Che cosa chiede la locandina ai residenti ?", options: ["Di firmare", "Di votare online", "Di portare sedie", "Di pagare una quota"], answers: ["Di firmare"], explain: "« Il quartiere si costruisce anche con le vostre firme ».")], skills: ["reading:inference", "function:express-opinion", "grammar:connectors", "writing:argument"]),
    ReadingText(id: "it-read-bar-sottocasa", languageID: "it", title: "Il bar sotto casa", level: "A1", topic: "al bar", unitID: "it-foundations-u27",
        text: "Il bar è sotto casa mia, all'angolo. La mattina c'è sempre fila: tutti vogliono il caffè e il cornetto. Al bancone c'è Franco, il barista: parla con tutti e sa i nomi di tutti. Io prendo sempre un cappuccino e un cornetto alla crema, e pago due euro e venti. Marta, la mia collega, preferisce il tè con il latte. Al bar c'è anche il giornale del giorno e, la domenica, i cornetti alla marmellata finiscono presto. Il bar chiude a mezzanotte, ma la mattina apre alle sei: per i lavoratori del quartiere è il primo amico della giornata.",
        questions: [
                            Exercise(id: "it-read-bar-sottocasa-q1", kind: "choice", prompt: "Dove si trova il bar?", options: ["Sotto casa della scrittrice", "Vicino all'ufficio", "In stazione", "In centro"], answers: ["Sotto casa della scrittrice"], explain: "« Il bar è sotto casa mia, all'angolo »."),
                            Exercise(id: "it-read-bar-sottocasa-q2", kind: "written", prompt: "Che cosa prende la scrittrice al bancone?", options: [], answers: ["un cappuccino e un cornetto alla crema", "cappuccino e cornetto alla crema", "un cappuccino e un cornetto"], explain: "« Io prendo sempre un cappuccino e un cornetto alla crema »."),
                            Exercise(id: "it-read-bar-sottocasa-q3", kind: "written", prompt: "Quanto paga?", options: [], answers: ["due euro e venti", "2 euro e 20", "2,20 euro"], explain: "« Pago due euro e venti »."),
                            Exercise(id: "it-read-bar-sottocasa-q4", kind: "choice", prompt: "Che cosa preferisce Marta?", options: ["Il tè con il latte", "Il caffè amaro", "Il cornetto integrale", "Il succo d'arancia"], answers: ["Il tè con il latte"], explain: "« Marta… preferisce il tè con il latte »."),
                            Exercise(id: "it-read-bar-sottocasa-q5", kind: "choice", prompt: "Quando apre il bar?", options: ["Alle sei", "Alle otto", "A mezzanotte", "Alle nove"], answers: ["Alle sei"], explain: "« La mattina apre alle sei ».")], skills: ["reading:detail", "reading:scan", "vocab:food", "grammar:present-simple"]),
    ReadingText(id: "it-read-invito-festa", languageID: "it", title: "L'invito alla festa", level: "A1", topic: "feste", unitID: "it-foundations-u22",
        text: "Ciao Anna! Ti scrivo per la festa di sabato. La festa è a casa mia, in Via Roma numero dodici, al quarto piano. Iniziamo alle otto della sera e la musica finisce a mezzanotte: i vicini sono gentili, ma a mezzanotte il palazzo dorme! Io preparo la pizza in casa e Luca porta il dolce. Tu porti da bere? Non serve il regalo: la tua presenza è il regalo! Ci sono anche Marco e Paola, i vicini nuovi. Per entrare, il citofono è « Rossi ». A sabato, e porta le tue canzoni preferite! Un abbraccio, Sara.",
        questions: [
                            Exercise(id: "it-read-invito-festa-q1", kind: "choice", prompt: "Dov'è la festa?", options: ["A casa di Sara", "A casa di Anna", "A casa di Luca", "Al bar di Marco"], answers: ["A casa di Sara"], explain: "« La festa è a casa mia », scrive Sara."),
                            Exercise(id: "it-read-invito-festa-q2", kind: "written", prompt: "A che ora inizia la festa?", options: [], answers: ["alle otto", "otto", "alle 8"], explain: "« Iniziamo alle otto della sera »."),
                            Exercise(id: "it-read-invito-festa-q3", kind: "choice", prompt: "Che cosa porta Luca?", options: ["Il dolce", "La pizza", "Le canzoni", "Da bere"], answers: ["Il dolce"], explain: "« Luca porta il dolce »."),
                            Exercise(id: "it-read-invito-festa-q4", kind: "written", prompt: "Che cosa chiede Sara ad Anna?", options: [], answers: ["da bere", "di portare da bere", "porta da bere"], explain: "« Tu porti da bere? »."),
                            Exercise(id: "it-read-invito-festa-q5", kind: "written", prompt: "Qual è il nome sul citofono?", options: [], answers: ["rossi", "Rossi"], explain: "« Il citofono è « Rossi » ».")], skills: ["reading:detail", "reading:scan", "vocab:social-expressions", "grammar:present-simple"]),
    ReadingText(id: "it-read-annuncio-lavoro", languageID: "it", title: "L'annuncio di lavoro", level: "B1", topic: "lavoro", unitID: "it-foundations-u21",
        text: "Il caffè letterario Aurora cerca barista per il punto vendita in centro storico. Orario: dal lunedì al venerdì, sei ore al giorno, turno mattutino. Contratto iniziale di sei mesi, con possibilità di stabilizzazione. Richieste: esperienza di almeno un anno alla macchina del caffè, buona mano con la pasticceria fresca e una vera passione per i clienti; l'inglese è utile ma non obbligatorio. Offriamo: uno stipendio in linea con il contratto, sconti sui prodotti e un ambiente di squadra. Se vi riconoscete in questa descrizione, mandate il curriculum e tre righe su di voi entro il 15 del mese all'indirizzo aurora@caffeletterario.it: i colloqui si svolgono la settimana successiva, in città. Solo candidature scritte, per favore: al telefono non riusciamo a rispondere a tutti.",
        questions: [
                            Exercise(id: "it-read-annuncio-lavoro-q1", kind: "choice", prompt: "Che tipo di contratto offre il caffè?", options: ["Sei mesi, con possibilità di stabilizzazione", "Un anno non rinnovabile", "Solo weekend", "Stagionale estivo"], answers: ["Sei mesi, con possibilità di stabilizzazione"], explain: "« Contratto iniziale di sei mesi, con possibilità di stabilizzazione »."),
                            Exercise(id: "it-read-annuncio-lavoro-q2", kind: "written", prompt: "Quante ore al giorno si lavora?", options: [], answers: ["sei ore", "6 ore"], explain: "« Sei ore al giorno, turno mattutino »."),
                            Exercise(id: "it-read-annuncio-lavoro-q3", kind: "choice", prompt: "Che cosa è obbligatorio?", options: ["L'esperienza alla macchina del caffè", "L'inglese perfetto", "Il diploma di cucina", "La macchina propria"], answers: ["L'esperienza alla macchina del caffè"], explain: "« Esperienza di almeno un anno alla macchina del caffè »."),
                            Exercise(id: "it-read-annuncio-lavoro-q4", kind: "written", prompt: "Entro quando bisogna mandare il curriculum?", options: [], answers: ["entro il 15", "il 15", "entro il 15 del mese"], explain: "« Entro il 15 del mese »."),
                            Exercise(id: "it-read-annuncio-lavoro-q5", kind: "choice", prompt: "Perché chiedono solo candidature scritte?", options: ["Non riescono a rispondere al telefono a tutti", "Il telefono è rotto", "Il direttore è in trasferta", "Le telefonate costano troppo"], answers: ["Non riescono a rispondere al telefono a tutti"], explain: "« Al telefono non riusciamo a rispondere a tutti ».")], skills: ["reading:scan", "reading:detail", "vocab:work", "function:talk-about-work"]),
    ReadingText(id: "it-read-diario-viaggio", languageID: "it", title: "Dal diario: il treno per Bolzano", level: "B1", topic: "viaggi", unitID: "it-foundations-u18",
        text: "Sabato 14 giugno. Oggi è il giorno del grande errore. Eravamo in treno per Bolzano e io controllavo i biglietti ogni dieci minuti: i miei, quelli di Luca, anche quelli della signora accanto. Alla stazione di Verona scendiamo per prendere un caffè e, quando il treno riparte, io resto sul binario: la porta si chiude con Luca dentro e io fuori. Il capotreno mi guarda e ride: « Il prossimo passa alle sedici e dieci ». Luca mi scrive: « Ti aspetto a Bolzano, ma il caffè lo paghi tu ». Prendo il treno delle sedici e dieci e, alle sette della sera, ridevamo tutti e due di questa avventura. Morale: controllare i biglietti è utile, ma guardare le porte è meglio.",
        questions: [
                            Exercise(id: "it-read-diario-viaggio-q1", kind: "choice", prompt: "Dove vanno in treno?", options: ["A Bolzano", "A Verona", "A Roma", "A Trieste"], answers: ["A Bolzano"], explain: "« Eravamo in treno per Bolzano »."),
                            Exercise(id: "it-read-diario-viaggio-q2", kind: "written", prompt: "Che cosa succede a Verona?", options: [], answers: ["rimane sul binario", "la porta si chiude con luca dentro e lei fuori", "perde il treno"], explain: "« La porta si chiude con Luca dentro e io fuori »."),
                            Exercise(id: "it-read-diario-viaggio-q3", kind: "choice", prompt: "A che ora passa il treno successivo?", options: ["Alle sedici e dieci", "Alle sei e dieci", "Alle sette", "Alle sedici"], answers: ["Alle sedici e dieci"], explain: "« Il prossimo passa alle sedici e dieci »."),
                            Exercise(id: "it-read-diario-viaggio-q4", kind: "written", prompt: "Chi paga il caffè, secondo Luca?", options: [], answers: ["lei", "la scrivente", "il caffè lo paga lei"], explain: "« Ti aspetto a Bolzano, ma il caffè lo paghi tu »."),
                            Exercise(id: "it-read-diario-viaggio-q5", kind: "choice", prompt: "Che morale trae la scrittrice?", options: ["Guardare le porte è meglio che controllare i biglietti", "I treni sono sempre in ritardo", "Non viaggiare con Luca", "Il caffè di Verona è caro"], answers: ["Guardare le porte è meglio che controllare i biglietti"], explain: "« Controllare i biglietti è utile, ma guardare le porte è meglio ».")], skills: ["reading:inference", "reading:detail", "function:tell-a-story", "grammar:past-continuous"]),
    ReadingText(id: "it-read-colonna-social", languageID: "it", title: "Colonna: mangiare insieme, guardarsi altrove", level: "B2", topic: "social", unitID: "it-foundations-u8",
        text: "Ogni sera la stessa scena: quattro persone a tavola, quattro schermi accesi. Non è un dramma, lo scrivo subito: il telefono non ha mangiato nessuno. Ma forse vale la pena nominare quello che perdiamo. La conversazione a tavola non è intrattenimento: è la palestra dove impariamo ad aspettare il nostro turno, a dissentire senza alzare la voce, a fare domande vere. I social ci danno mille conversazioni parallele e nessuna profondità: rispondere a tutto significa non approfondire niente. La mia proposta non è il divieto, che dura il tempo di un sermone, ma una piccola asimmetria volontaria: il telefono lontano durante il pasto, ritrovato dopo il dolce. Sono quaranta minuti. Chi ha davvero bisogno di noi può chiamare due volte; chi scrive « urgente » alle nove di sera, forse non ha capito cosa sia l'urgenza.",
        questions: [
                            Exercise(id: "it-read-colonna-social-q1", kind: "choice", prompt: "Come definisce l'autrice la conversazione a tavola?", options: ["Una palestra di ascolto", "Un intrattenimento leggero", "Una perdita di tempo", "Un'abitudine antica"], answers: ["Una palestra di ascolto"], explain: "« La conversazione a tavola… è la palestra dove impariamo ad aspettare il nostro turno »."),
                            Exercise(id: "it-read-colonna-social-q2", kind: "written", prompt: "Che cosa manca alle mille conversazioni parallele dei social?", options: [], answers: ["profondità", "la profondità", "nessuna profondità"], explain: "« I social ci danno mille conversazioni parallele e nessuna profondità »."),
                            Exercise(id: "it-read-colonna-social-q3", kind: "choice", prompt: "Che cosa propone l'autrice?", options: ["Il telefono lontano durante il pasto", "Vietare i telefoni ai figli", "Cenare sempre fuori", "Spegnere il wifi di casa"], answers: ["Il telefono lontano durante il pasto"], explain: "« Una piccola asimmetria volontaria: il telefono lontano durante il pasto »."),
                            Exercise(id: "it-read-colonna-social-q4", kind: "written", prompt: "Chi può chiamare due volte?", options: [], answers: ["chi ha davvero bisogno di noi", "chi ha bisogno di noi"], explain: "« Chi ha davvero bisogno di noi può chiamare due volte »."),
                            Exercise(id: "it-read-colonna-social-q5", kind: "choice", prompt: "Che tono ha la colonna?", options: ["Critico ma moderato, senza drammi", "Indignato e ironico", "Nostalgico e triste", "Neutro e giornalistico"], answers: ["Critico ma moderato, senza drammi"], explain: "« Non è un dramma, lo scrivo subito »: l'autrice critica senza drammatizzare.")], skills: ["reading:inference", "reading:gist", "function:express-opinion", "writing:argument"]),
    ReadingText(id: "it-read-controproposta-affitto", languageID: "it", title: "La controproposta per l'affitto", level: "B2", topic: "affitto", unitID: "it-foundations-u7",
        text: "Oggetto: controproposta per il contratto di locazione, Via dei Mille 24.\nGentile signora Bruni, la ringrazio per la disponibilità di giovedì. L'appartamento mi convince: luce, zona e il terrazzo con vista. Rimane il prezzo: millequattrocento euro sono sopra il mio budget, e le sarò franco: a quella cifra il contratto non parte. Le propongo millecento per un impegno di ventiquattro mesi, con pagamento anticipato dell'ultimo mese a titolo di garanzia. In cambio, chiedo solo due interventi prima dell'ingresso: il boiler nuovo, che ha già superato la vita utile, e una mano con le persiane del salotto. Se la proposta le sembra interessante, sono disponibile a un incontro in settimana, anche in videochiamata. Resto a disposizione e la ringrazio per la lettura. Cordiali saluti, Dario Ferri.",
        questions: [
                            Exercise(id: "it-read-controproposta-affitto-q1", kind: "choice", prompt: "Che cosa propone Dario come affitto?", options: ["Millecento per ventiquattro mesi", "Millequattrocento per un anno", "Millecento con ingresso immediato", "Mille se la signora ripara il boiler"], answers: ["Millecento per ventiquattro mesi"], explain: "« Le propongo millecento per un impegno di ventiquattro mesi »."),
                            Exercise(id: "it-read-controproposta-affitto-q2", kind: "written", prompt: "Che cosa offre come garanzia?", options: [], answers: ["il pagamento anticipato dell ultimo mese", "pagamento anticipato dell ultimo mese", "l ultimo mese anticipato"], explain: "« Con pagamento anticipato dell'ultimo mese a titolo di garanzia »."),
                            Exercise(id: "it-read-controproposta-affitto-q3", kind: "choice", prompt: "Quali interventi chiede prima dell'ingresso?", options: ["Il boiler nuovo e le persiane", "La verniciatura e il parquet", "Il condizionatore e le tende", "Solo il boiler"], answers: ["Il boiler nuovo e le persiane"], explain: "« Il boiler nuovo… e una mano con le persiane del salotto »."),
                            Exercise(id: "it-read-controproposta-affitto-q4", kind: "written", prompt: "Come dice Dario che si comporterà sul prezzo?", options: [], answers: ["franco", "sarò franco", "le sarò franco"], explain: "« Le sarò franco: a quella cifra il contratto non parte »."),
                            Exercise(id: "it-read-controproposta-affitto-q5", kind: "choice", prompt: "Che impressione dà la lettera?", options: ["Ferma e rispettosa, con argomenti chiari", "Aggressiva", "Indecisa e vaga", "Fredda e burocratica"], answers: ["Ferma e rispettosa, con argomenti chiari"], explain: "« Le sarò franco » e la chiusura cortese mostrano fermezza e rispetto.")], skills: ["reading:inference", "reading:detail", "function:negotiate", "writing:email"]),
    ReadingText(id: "pt-read-grupo-caminhada", languageID: "pt", title: "O grupo de caminhada", level: "A1", topic: "saúde", unitID: "pt-foundations-u2",
        text: "Às terças, o bairro organiza uma caminhada grátis. Começa às nove na praça e termina no rio. O grupo é misto: tem estudantes, famílias e aposentados. Ninguém corre; a ideia é caminhar e conversar. No fim, quem quiser toma café da manhã junto num bar da feira. Bia participa faz um mês e já tem três amigos novos. Ela diz que é a hora mais tranquila da semana dela.",
        questions: [
                            Exercise(id: "pt-read-grupo-caminhada-q1", kind: "choice", prompt: "Quando é a caminhada ?", options: ["Às terças", "Às segundas", "Aos sábados", "Todos os dias"], answers: ["Às terças"], explain: "Às terças, o bairro organiza uma caminhada grátis."),
                            Exercise(id: "pt-read-grupo-caminhada-q2", kind: "written", prompt: "A que horas começa ?", options: [], answers: ["as nove", "às nove", "nove horas"], explain: "Começa às nove na praça."),
                            Exercise(id: "pt-read-grupo-caminhada-q3", kind: "choice", prompt: "Quem participa ?", options: ["Estudantes, famílias e aposentados", "Só estudantes", "Só aposentados", "Só famílias"], answers: ["Estudantes, famílias e aposentados"], explain: "O grupo é misto."),
                            Exercise(id: "pt-read-grupo-caminhada-q4", kind: "choice", prompt: "O que faz quem quiser no fim ?", options: ["Toma café da manhã junto", "Corre até o rio", "Volta para casa", "Pega o ônibus"], answers: ["Toma café da manhã junto"], explain: "Toma café da manhã junto num bar da feira."),
                            Exercise(id: "pt-read-grupo-caminhada-q5", kind: "written", prompt: "Há quanto tempo a Bia participa ?", options: [], answers: ["um mes", "um mês", "1 mês", "1 mes"], explain: "A Bia participa faz um mês.")], skills: ["reading:detail", "reading:scan", "grammar:present-simple", "vocab:daily-routine"]),
    ReadingText(id: "pt-read-anuncio-apartamento", languageID: "pt", title: "O anúncio do apartamento", level: "A2", topic: "apartamentos", unitID: "pt-foundations-u4",
        text: "Apartamento claro de dois quartos para alugar a partir de setembro. Fica no terceiro andar, com elevador, e tem uma varanda para o pátio, então é tranquilo. A sala é maior que a cozinha, mas a cozinha tem janela. O bairro tem feira aos sábados e a estação de metrô fica a cinco minutos. Não é o mais barato da região, mas é o melhor iluminado. Pedem um mês de caução e preferem alguém que trabalhe de casa, como os atuais donos.",
        questions: [
                            Exercise(id: "pt-read-anuncio-apartamento-q1", kind: "choice", prompt: "Quando está disponível ?", options: ["A partir de setembro", "A partir de agosto", "Agora", "Em janeiro"], answers: ["A partir de setembro"], explain: "Para alugar a partir de setembro."),
                            Exercise(id: "pt-read-anuncio-apartamento-q2", kind: "choice", prompt: "Por que é tranquilo ?", options: ["Varanda para o pátio", "Fica no térreo", "Não tem vizinhos", "Fica no campo"], answers: ["Varanda para o pátio"], explain: "A varanda dá para o pátio, então é tranquilo."),
                            Exercise(id: "pt-read-anuncio-apartamento-q3", kind: "written", prompt: "A quantos minutos fica o metrô ?", options: [], answers: ["cinco minutos", "5 minutos", "cinco"], explain: "A estação de metrô fica a cinco minutos."),
                            Exercise(id: "pt-read-anuncio-apartamento-q4", kind: "choice", prompt: "Como é comparado com a região ?", options: ["Não é o mais barato, mas é o melhor iluminado", "É o mais barato", "É o pior iluminado", "É o menor"], answers: ["Não é o mais barato, mas é o melhor iluminado"], explain: "Não é o mais barato, mas é o melhor iluminado."),
                            Exercise(id: "pt-read-anuncio-apartamento-q5", kind: "choice", prompt: "Quem os donos preferem ?", options: ["Alguém que trabalhe de casa", "Estudantes", "Famílias com crianças", "Aposentados"], answers: ["Alguém que trabalhe de casa"], explain: "Preferem alguém que trabalhe de casa.")], skills: ["reading:detail", "reading:inference", "grammar:comparatives"], exposureSkills: ["grammar:superlatives"]),
    ReadingText(id: "pt-read-viagem-inesquecivel", languageID: "pt", title: "A viagem inesquecível", level: "B1", topic: "viagens", unitID: "pt-foundations-u6",
        text: "No ano passado fiz a viagem dos meus sonhos: quinze dias no Peru. Já tinha conhecido o México e a Argentina, mas a América do Sul ainda me surpreendeu. No terceiro dia subi ao Machu Picchu. Estava com neblina, então no começo não dava para ver nada. Depois, aos poucos, o sol apareceu e a cidade inteira surgiu. Não disse nada; fiquei olhando. No trem de volta conheci uma família de Cusco, e me chamaram para jantar. « Os viajantes sempre dizem a mesma coisa », riu a avó, « mas essa sopa é de verdade ». Ela tinha razão: foi o melhor jantar da viagem. Desde então, quando alguém pergunta por um destino, eu digo Peru.",
        questions: [
                            Exercise(id: "pt-read-viagem-inesquecivel-q1", kind: "choice", prompt: "Quanto durou a viagem ?", options: ["Quinze dias", "Dez dias", "Um mês", "Três dias"], answers: ["Quinze dias"], explain: "Quinze dias no Peru."),
                            Exercise(id: "pt-read-viagem-inesquecivel-q2", kind: "written", prompt: "Que países ele já tinha conhecido ?", options: [], answers: ["mexico e argentina", "méxico e argentina"], explain: "Já tinha conhecido o México e a Argentina."),
                            Exercise(id: "pt-read-viagem-inesquecivel-q3", kind: "choice", prompt: "Por que não dava para ver nada no começo ?", options: ["Estava com neblina", "Estava fechado", "Chovia forte", "Era de noite"], answers: ["Estava com neblina"], explain: "Estava com neblina, então não se via nada."),
                            Exercise(id: "pt-read-viagem-inesquecivel-q4", kind: "choice", prompt: "Com quem jantou o narrador ?", options: ["Com uma família de Cusco", "Com a avó do hotel", "Sozinho", "Com amigos do trem"], answers: ["Com uma família de Cusco"], explain: "Conheci uma família de Cusco e me chamaram para jantar."),
                            Exercise(id: "pt-read-viagem-inesquecivel-q5", kind: "written", prompt: "O que ele diz agora quando perguntam por um destino ?", options: [], answers: ["peru", "eu digo peru", "digo peru"], explain: "Eu digo Peru.")], skills: ["reading:inference", "grammar:present-perfect", "grammar:connectors", "vocab:travel"]),
    ReadingText(id: "pt-read-coluna-peatonal", languageID: "pt", title: "Coluna: peatonalizemos", level: "B2", topic: "opinião", unitID: "pt-foundations-u8",
        text: "Acho que deveríamos peatonalizar o centro. Por um lado, o barulho cairia: os moradores da praça pedem silêncio há anos. Por outro, a poluição cairia — ela já passa dos limites legais. É verdade que o comércio teme perder clientes, mas os números de outras cidades dizem o contrário: onde o carro desaparece, a gente caminha mais e compra mais. A empresa cujo relatório foi publicado no mês passado calculou 15 % mais vendas nas ruas sem carros. Por tudo isso, defendo a medida: se tivéssemos coragem de testá-la por um ano, não ia querer voltar atrás.",
        questions: [
                            Exercise(id: "pt-read-coluna-peatonal-q1", kind: "choice", prompt: "Qual é a tese da coluna ?", options: ["Peatonalizar o centro", "Alargar a rodovia", "Proibir bicicletas", "Construir um estacionamento"], answers: ["Peatonalizar o centro"], explain: "« Deveríamos peatonalizar o centro »."),
                            Exercise(id: "pt-read-coluna-peatonal-q2", kind: "written", prompt: "O que já passa dos limites legais ?", options: [], answers: ["a poluicao", "a poluição"], explain: "A poluição já passa dos limites legais."),
                            Exercise(id: "pt-read-coluna-peatonal-q3", kind: "choice", prompt: "De que o comércio teme ?", options: ["Perder clientes", "Pagar mais impostos", "Fechar no verão", "Mudar de cidade"], answers: ["Perder clientes"], explain: "O comércio teme perder clientes."),
                            Exercise(id: "pt-read-coluna-peatonal-q4", kind: "written", prompt: "Quanto mais vendas nas ruas sem carros ?", options: [], answers: ["15%", "15 %", "quinze por cento"], explain: "15 % mais vendas."),
                            Exercise(id: "pt-read-coluna-peatonal-q5", kind: "choice", prompt: "O que o autor propõe no fim ?", options: ["Testar por um ano", "Esquecer o plano", "Multar mais", "Votar de novo"], answers: ["Testar por um ano"], explain: "« Testá-la por um ano ».")], skills: ["reading:inference", "writing:argument", "grammar:connectors", "grammar:second-conditional"]),
    ReadingText(id: "pt-read-ensaio-cidade", languageID: "pt", title: "Ensaio: a língua na praça", level: "C1", topic: "opinião", unitID: "pt-foundations-u9",
        text: "Costuma-se dizer que a internet empobrece a língua. Na minha visão, o diagnóstico é apressado. É verdade que o teclado abrevia — « vc », « pq », « hj » —, mas abreviar não é destruir; por assim dizer, a escrita digital criou um registro novo, oral na sintaxe e escrito na forma. De certa forma, o português sempre fez isso: o que se falava na praça há um século entrou nos romances de hoje. Além disso, nunca se escreveu tanto quanto agora — mensagens, comentários, resenhas. O problema não é a variedade; é a distância entre quem domina os registros e quem fica preso em um só. Por isso, em vez de condenar o « pq », ensinemos quando ele cabe — e quando, no e-mail para a diretoria, precisa virar fórmula formal: visto que o registro é, antes de tudo, uma escolha.",
        questions: [
                            Exercise(id: "pt-read-ensaio-cidade-q1", kind: "choice", prompt: "Qual é a tese do ensaio ?", options: ["A internet não empobrece a língua", "A internet destrói a escrita", "É preciso proibir abreviações", "Ninguém escreve mais"], answers: ["A internet não empobrece a língua"], explain: "O autor considera apressado dizer que a internet empobrece a língua."),
                            Exercise(id: "pt-read-ensaio-cidade-q2", kind: "written", prompt: "Que abreviações o texto cita ?", options: [], answers: ["vc pq hj", "vc, pq e hj"], explain: "« vc », « pq », « hj »."),
                            Exercise(id: "pt-read-ensaio-cidade-q3", kind: "choice", prompt: "O que, segundo o autor, já acontecia há um século ?", options: ["A fala da praça entrava nos livros", "Ninguém sabia escrever", "Os romances eram orais", "A escola proibia gírias"], answers: ["A fala da praça entrava nos livros"], explain: "« O que se falava na praça há um século entrou nos romances de hoje »."),
                            Exercise(id: "pt-read-ensaio-cidade-q4", kind: "written", prompt: "Qual é, para o autor, o verdadeiro problema ?", options: [], answers: ["a distancia entre quem domina os registros e quem fica preso em um so", "a distância entre quem domina os registros", "ficar preso em um só registro"], explain: "« A distância entre quem domina os registros e quem fica preso em um só »."),
                            Exercise(id: "pt-read-ensaio-cidade-q5", kind: "choice", prompt: "O que o autor propõe no final ?", options: ["Ensinar quando cada registro cabe", "Banir o « pq » da escola", "Escrever só e-mails formais", "Parar de usar a internet"], answers: ["Ensinar quando cada registro cabe"], explain: "Em vez de condenar, ensinar quando o registro cabe.")], skills: ["reading:inference", "writing:argument", "grammar:connectors", "vocab:collocations"]),
    ReadingText(id: "pt-read-carta-diretoria", languageID: "pt", title: "Carta da diretoria", level: "C1", topic: "trabalho", unitID: "pt-foundations-u9",
        text: "Prezadas equipes, confirmamos com esta carta o regime híbrido vigente a partir de 3 de março: três dias presenciais, reservados à colaboração e às reuniões de time. Solicitamos que as áreas publiquem seus calendários até 20 de fevereiro, visto que as salas serão alocadas por ordem de registro. Segue em anexo o guia de boas práticas; dele constam as exceções — licenças, saúde e prazos críticos. Registramos, no entanto, que nenhuma decisão do programa reduzirá o trabalho remoto já contratado. Agradecemos desde já o empenho de todos na transição e permanecemos à disposição para esclarecimentos pelos canais habituais. Atenciosamente, Diretoria de Pessoas.",
        questions: [
                            Exercise(id: "pt-read-carta-diretoria-q1", kind: "choice", prompt: "Quando começa o regime híbrido ?", options: ["3 de março", "20 de fevereiro", "3 de fevereiro", "Em anexo"], answers: ["3 de março"], explain: "« Vigente a partir de 3 de março »."),
                            Exercise(id: "pt-read-carta-diretoria-q2", kind: "written", prompt: "Até quando as áreas devem publicar os calendários ?", options: [], answers: ["20 de fevereiro", "ate 20 de fevereiro"], explain: "« Até 20 de fevereiro »."),
                            Exercise(id: "pt-read-carta-diretoria-q3", kind: "choice", prompt: "Como as salas serão alocadas ?", options: ["Por ordem de registro", "Por sorteio", "Por antiguidade", "Por indicação"], answers: ["Por ordem de registro"], explain: "« As salas serão alocadas por ordem de registro »."),
                            Exercise(id: "pt-read-carta-diretoria-q4", kind: "written", prompt: "O que segue em anexo na carta ?", options: [], answers: ["o guia de boas praticas", "guia de boas práticas", "o guia"], explain: "Segue em anexo o guia de boas práticas."),
                            Exercise(id: "pt-read-carta-diretoria-q5", kind: "choice", prompt: "O que a carta garante sobre o trabalho remoto ?", options: ["Nada do programa o reduz", "Ele acaba em março", "Só diretores o mantêm", "Depende do cliente"], answers: ["Nada do programa o reduz"], explain: "« Nenhuma decisão do programa reduzirá o trabalho remoto já contratado ».")], skills: ["reading:scan", "reading:detail", "vocab:work", "grammar:connectors"]),
    ReadingText(id: "pt-read-resenha-critica", languageID: "pt", title: "Resenha: Vozes do prédio", level: "C1", topic: "cultura", unitID: "pt-foundations-u9",
        text: "Diria que « Vozes do prédio » não é um romance fácil — e é justamente aí que mora o seu valor. A trama é mínima: uma síndica, três inquilinos e uma carta que ninguém quer ter escrito. De certa forma, nada acontece; por assim dizer, o livro inteiro é uma conversa à porta do elevador. E, no entanto, cada capítulo afia um registro: o formal da síndica, o coloquial do porteiro, o burocrático das circulares. Na minha visão, o segundo ato vacila — a autora explica o que o leitor já havia inferido. Não deixa de ser leitura imprescindível: raramente a prosa brasileira escutou tão bem quem fala como pode. Resumindo: um romance sobre registros que é, ele próprio, uma aula de registros.",
        questions: [
                            Exercise(id: "pt-read-resenha-critica-q1", kind: "choice", prompt: "Onde mora o valor do romance, segundo a resenha ?", options: ["Na sua dificuldade", "No seu final feliz", "No seu tamanho", "No seu preço"], answers: ["Na sua dificuldade"], explain: "« Não é um romance fácil — e é justamente aí que mora o seu valor »."),
                            Exercise(id: "pt-read-resenha-critica-q2", kind: "written", prompt: "Quantos personagens centrais a trama tem ?", options: [], answers: ["tres", "três", "quatro com a carta"], explain: "Uma síndica e três inquilinos: três personagens."),
                            Exercise(id: "pt-read-resenha-critica-q3", kind: "choice", prompt: "O que a resenha critica no segundo ato ?", options: ["A autora explica o inferido", "Faltam capítulos", "O porteiro desaparece", "A carta é falsa"], answers: ["A autora explica o inferido"], explain: "« A autora explica o que o leitor já havia inferido »."),
                            Exercise(id: "pt-read-resenha-critica-q4", kind: "choice", prompt: "O veredito final da resenhista é que a leitura é:", options: ["Imprescindível", "Descartável", "Confusa", "Inacabada"], answers: ["Imprescindível"], explain: "« Não deixa de ser leitura imprescindível »."),
                            Exercise(id: "pt-read-resenha-critica-q5", kind: "written", prompt: "Como a resenhista resume o livro ?", options: [], answers: ["um romance sobre registros que e uma aula de registros", "um romance sobre registros", "uma aula de registros"], explain: "« Um romance sobre registros que é, ele próprio, uma aula de registros ».")], skills: ["reading:inference", "function:express-opinion", "writing:argument"]),
    ReadingText(id: "pt-read-anuncio-colega", languageID: "pt", title: "Anúncio: procuro colega de casa", level: "A1", topic: "casa", unitID: "pt-foundations-u10",
        text: "Procuro uma colega de casa para o meu apartamento na Vila Madalena. O apartamento tem dois quartos: o meu é pequeno e o seu é grande, com uma janela para a rua. A sala é clara e tem um sofá confortável. Eu sou o Pedro, tenho vinte e seis anos, sou professor e cozinho nos fins de semana. Minha rotina é tranquila: trabalho de manhã e leio à noite. Você é organizada e não fuma ? Manda uma mensagem para mim!",
        questions: [
                            Exercise(id: "pt-read-anuncio-colega-q1", kind: "choice", prompt: "Quantos quartos tem o apartamento?", options: ["Dois", "Um", "Três", "Quatro"], answers: ["Dois"], explain: "O apartamento tem dois quartos."),
                            Exercise(id: "pt-read-anuncio-colega-q2", kind: "choice", prompt: "Como é o quarto do Pedro?", options: ["É pequeno", "É grande", "Não tem janela", "É escuro"], answers: ["É pequeno"], explain: "O meu é pequeno e o seu é grande, com uma janela para a rua."),
                            Exercise(id: "pt-read-anuncio-colega-q3", kind: "choice", prompt: "Qual é o trabalho do Pedro?", options: ["Professor", "Médico", "Estudante", "Garçom"], answers: ["Professor"], explain: "Eu sou o Pedro, tenho vinte e seis anos, sou professor."),
                            Exercise(id: "pt-read-anuncio-colega-q4", kind: "written", prompt: "O que o Pedro faz nos fins de semana?", options: [], answers: ["cozinha", "ele cozinha", "cozinha nos fins de semana"], explain: "Eu… cozinho nos fins de semana."),
                            Exercise(id: "pt-read-anuncio-colega-q5", kind: "written", prompt: "Quando o Pedro lê?", options: [], answers: ["à noite", "a noite", "de noite"], explain: "Trabalho de manhã e leio à noite.")], skills: ["reading:detail", "reading:scan", "grammar:possessives", "vocab:home", "function:describe-people"]),
    ReadingText(id: "pt-read-mensagem-grupo", languageID: "pt", title: "Mensagens do grupo para o fim de semana", level: "A1", topic: "fim de semana", unitID: "pt-foundations-u13",
        text: "Mensagens do grupo « Os amigos ». Ana: Chove no sábado ! O que a gente faz ? Leo: Eu caminho de manhã, mas só quando não chove. Bia: Eu gosto de filmes. Vem para casa ! Leo: Boa ! Eu levo o bolo. Nunca como doce, mas sábado é dia. Ana: Eu não gosto de frio. Levo o suco. Até sábado !",
        questions: [
                            Exercise(id: "pt-read-mensagem-grupo-q1", kind: "choice", prompt: "Como está o tempo no sábado?", options: ["Chove", "Faz calor", "Neva", "Está quente"], answers: ["Chove"], explain: "Ana: Chove no sábado !"),
                            Exercise(id: "pt-read-mensagem-grupo-q2", kind: "choice", prompt: "Quando o Leo caminha?", options: ["De manhã", "À noite", "À tarde", "Nunca"], answers: ["De manhã"], explain: "Eu caminho de manhã, mas só quando não chove."),
                            Exercise(id: "pt-read-mensagem-grupo-q3", kind: "choice", prompt: "O que a Bia gosta de fazer?", options: ["Ver filmes", "Cozinhar", "Caminhar", "Ler"], answers: ["Ver filmes"], explain: "Bia: Eu gosto de filmes. Vem para casa !"),
                            Exercise(id: "pt-read-mensagem-grupo-q4", kind: "written", prompt: "O que o Leo leva para a casa da Bia?", options: [], answers: ["o bolo", "ele leva o bolo", "levo o bolo"], explain: "Eu levo o bolo, diz o Leo."),
                            Exercise(id: "pt-read-mensagem-grupo-q5", kind: "written", prompt: "O que a Ana leva?", options: [], answers: ["o suco", "ela leva o suco", "levo o suco"], explain: "Levo o suco, diz a Ana."),
                            Exercise(id: "pt-read-mensagem-grupo-q6", kind: "written", prompt: "O que o Leo nunca come?", options: [], answers: ["doce", "doce nunca", "nunca como doce"], explain: "Nunca como doce, mas sábado é dia.")], skills: ["reading:detail", "reading:scan", "vocab:hobbies", "grammar:frequency-adverbs"]),
    ReadingText(id: "pt-read-horario-metro", languageID: "pt", title: "O horário do metrô", level: "A1", topic: "horários", unitID: "pt-foundations-u14",
        text: "Este é o horário do metrô da Linha Verde, da estação São João. De manhã, os trens saem às seis, às seis e meia, às sete e às sete e meia. À tarde, saem às treze, às quatorze e às quinze. O Leo trabalha perto da estação Central. Ele pega o trem das sete e chega às sete e vinte. Nos fins de semana, os trens saem só a cada meia hora. O horário fica na parede da estação.",
        questions: [
                            Exercise(id: "pt-read-horario-metro-q1", kind: "choice", prompt: "De que estação é o horário ?", options: ["Da estação São João", "Da estação Central", "Da estação Leste", "Do centro"], answers: ["Da estação São João"], explain: "Este é o horário do metrô da Linha Verde, da estação São João."),
                            Exercise(id: "pt-read-horario-metro-q2", kind: "choice", prompt: "Qual trem sai às sete e meia ?", options: ["Um trem de manhã", "Um trem da tarde", "Um trem da noite", "Nenhum trem"], answers: ["Um trem de manhã"], explain: "De manhã, os trens saem às seis, às seis e meia, às sete e às sete e meia."),
                            Exercise(id: "pt-read-horario-metro-q3", kind: "choice", prompt: "Qual trem o Leo pega ?", options: ["O trem das sete", "O trem das seis", "O trem das treze", "O trem das quinze"], answers: ["O trem das sete"], explain: "Ele pega o trem das sete e chega às sete e vinte."),
                            Exercise(id: "pt-read-horario-metro-q4", kind: "choice", prompt: "A que horas o Leo chega ?", options: ["Às sete e vinte", "Às sete", "Às sete e meia", "Às oito"], answers: ["Às sete e vinte"], explain: "Ele pega o trem das sete e chega às sete e vinte."),
                            Exercise(id: "pt-read-horario-metro-q5", kind: "written", prompt: "Quantos trens saem à tarde ?", options: [], answers: ["três", "tres", "3"], explain: "À tarde, saem às treze, às quatorze e às quinze."),
                            Exercise(id: "pt-read-horario-metro-q6", kind: "written", prompt: "Onde fica o horário ?", options: [], answers: ["na parede da estação", "na parede da estacao", "na parede", "parede da estacao"], explain: "O horário fica na parede da estação.")], skills: ["reading:detail", "reading:scan", "vocab:transport", "function:tell-time"]),
    ReadingText(id: "pt-read-fila-mensagens", languageID: "pt", title: "A fila de mensagens da festa", level: "A2", topic: "mensagens", unitID: "pt-foundations-u17",
        text: "Mensagens do grupo « Festa da Bia ». Duda: Pessoal, a festa vai ser sábado, na minha casa. Eu vou fazer o bolo de chocolate. Téo: Que legal ! Eu vou comprar as bebidas. Que horas começamos ? Lu: Que pena, gente… não posso sábado, vou visitar meus pais no interior. Duda: Que pena, Lu ! Outro dia a gente comemora juntos. Téo: Combinado. A Bia não pode saber — vai ser uma surpresa ! Lu: Ela vai amar. Boa festa pra vocês !",
        questions: [
                            Exercise(id: "pt-read-fila-mensagens-q1", kind: "choice", prompt: "Quando vai ser a festa ?", options: ["No sábado", "No domingo", "Na sexta", "No interior"], answers: ["No sábado"], explain: "A festa vai ser sábado, na casa da Duda."),
                            Exercise(id: "pt-read-fila-mensagens-q2", kind: "written", prompt: "O que a Duda vai fazer ?", options: [], answers: ["o bolo", "o bolo de chocolate", "fazer o bolo"], explain: "Eu vou fazer o bolo de chocolate."),
                            Exercise(id: "pt-read-fila-mensagens-q3", kind: "choice", prompt: "Por que a Lu não pode ir ?", options: ["Vai visitar os pais", "Vai trabalhar", "Vai estudar", "Vai ao médico"], answers: ["Vai visitar os pais"], explain: "Não posso sábado, vou visitar meus pais no interior."),
                            Exercise(id: "pt-read-fila-mensagens-q4", kind: "choice", prompt: "Quantas pessoas vão à festa ?", options: ["Duas", "Três", "Quatro", "Nenhuma"], answers: ["Duas"], explain: "A Lu não vai: só a Duda e o Téo vão à festa."),
                            Exercise(id: "pt-read-fila-mensagens-q5", kind: "written", prompt: "O que a Bia não pode saber ?", options: [], answers: ["a festa", "da festa", "a surpresa", "que tem festa"], explain: "A Bia não pode saber: vai ser uma surpresa !")], skills: ["reading:detail", "reading:inference", "vocab:social-expressions", "grammar:going-to"]),
    ReadingText(id: "pt-read-avaliacao-defeito", languageID: "pt", title: "A avaliação do defeito", level: "A2", topic: "problemas", unitID: "pt-foundations-u20",
        text: "Avaliação: Liquidificador Vermelho 500 — nota: duas estrelas. Comprei o aparelho na semana passada e ele quebrou no terceiro uso. Primeiro, fez um barulho estranho; depois, parou de girar. Liguei para a loja e a atendente foi tranquila: pediu a nota fiscal e marcou a troca para o sábado. Trouxe a nota e o aparelho e recebi um novo na hora. A troca foi rápida, mas o produto não durou. Minha dica: guarde sempre a nota fiscal — ela resolve a reclamação.",
        questions: [
                            Exercise(id: "pt-read-avaliacao-defeito-q1", kind: "choice", prompt: "Quantas estrelas tem a avaliação ?", options: ["Duas", "Três", "Quatro", "Cinco"], answers: ["Duas"], explain: "Nota: duas estrelas."),
                            Exercise(id: "pt-read-avaliacao-defeito-q2", kind: "written", prompt: "Quando o aparelho quebrou ?", options: [], answers: ["no terceiro uso", "terceiro uso"], explain: "Ele quebrou no terceiro uso."),
                            Exercise(id: "pt-read-avaliacao-defeito-q3", kind: "choice", prompt: "O que aconteceu primeiro ?", options: ["Fez um barulho estranho", "Parou de girar", "Vazou água", "Não ligou"], answers: ["Fez um barulho estranho"], explain: "Primeiro, fez um barulho estranho; depois, parou de girar."),
                            Exercise(id: "pt-read-avaliacao-defeito-q4", kind: "written", prompt: "O que a atendente pediu ?", options: [], answers: ["a nota fiscal", "a nota", "nota fiscal"], explain: "A atendente pediu a nota fiscal e marcou a troca para o sábado."),
                            Exercise(id: "pt-read-avaliacao-defeito-q5", kind: "choice", prompt: "O que o autor recomenda no fim ?", options: ["Guardar a nota fiscal", "Não comprar de novo", "Trocar de loja", "Ligar todo dia"], answers: ["Guardar a nota fiscal"], explain: "Guarde sempre a nota fiscal — ela resolve a reclamação.")], skills: ["reading:detail", "reading:inference", "function:solve-problems", "grammar:past-simple-regular"]),
    ReadingText(id: "pt-read-lista-mala", languageID: "pt", title: "A lista da mala", level: "A2", topic: "viagem", unitID: "pt-foundations-u25",
        text: "Mensagem no grupo da viagem — Duda: « Gente, a lista da mala está pronta ! Primeiro confiro os documentos: passaporte, reserva do hotel e passagem. Depois vem a mala de mão: três camisetas, uma calça, um casaco leve e o carregador. Não vou esquecer o remédio nem o guarda-chuva; a previsão diz chuva no domingo. O voo é de manhã, às sete, então vou dormir cedo na sexta. Quem quiser, manda a sua lista aqui para conferirmos juntos na véspera. »",
        questions: [
                            Exercise(id: "pt-read-lista-mala-q1", kind: "choice", prompt: "O que a Duda confere primeiro ?", options: ["Os documentos", "As camisetas", "O carregador", "O guarda-chuva"], answers: ["Os documentos"], explain: "Primeiro confiro os documentos: passaporte, reserva do hotel e passagem."),
                            Exercise(id: "pt-read-lista-mala-q2", kind: "written", prompt: "A que horas é o voo ?", options: [], answers: ["às sete", "as sete", "sete horas"], explain: "O voo é de manhã, às sete."),
                            Exercise(id: "pt-read-lista-mala-q3", kind: "choice", prompt: "Por que ela leva guarda-chuva ?", options: ["A previsão diz chuva", "O hotel não tem", "É presente", "Chove todo dia"], answers: ["A previsão diz chuva"], explain: "A previsão diz chuva no domingo."),
                            Exercise(id: "pt-read-lista-mala-q4", kind: "written", prompt: "Quantas camisetas vão na mala ?", options: [], answers: ["três", "tres", "3"], explain: "Três camisetas, uma calça, um casaco leve e o carregador."),
                            Exercise(id: "pt-read-lista-mala-q5", kind: "written", prompt: "Quando o grupo confere as listas juntas ?", options: [], answers: ["na véspera", "na vespera", "véspera", "vespera"], explain: "Para conferirmos juntos na véspera.")], skills: ["reading:detail", "reading:scan", "vocab:travel", "grammar:going-to"]),
    ReadingText(id: "pt-read-cartaz-vizinhanca", languageID: "pt", title: "O cartaz da vizinhança", level: "B1", topic: "bairro", unitID: "pt-foundations-u26",
        text: "Cartaz na praça — « Vizinhança que cuida ». Na quinta, às 19h, a associação apresenta a proposta da horta comunitária. Por um lado, ocupamos um canto vazio da praça; por outro, ganhamos comida fresca e um lugar de encontro. Além disso, a feira do sábado vai funcionar sem plástico: traga sua sacola. Na nossa opinião, comprar menos e melhor também é cuidar do bairro. Embora o começo exija trabalho, o resultado pertence a todos. Venha opinar — sua voz muda a rua.",
        questions: [
                            Exercise(id: "pt-read-cartaz-vizinhanca-q1", kind: "written", prompt: "Quando e a que horas é a reunião ?", options: [], answers: ["na quinta às 19h", "na quinta as 19h", "quinta às 19h", "quinta as 19h", "às 19h", "as 19h"], explain: "Na quinta, às 19h, a associação apresenta a proposta da horta comunitária."),
                            Exercise(id: "pt-read-cartaz-vizinhanca-q2", kind: "choice", prompt: "O que acontece com o canto vazio da praça ?", options: ["Vira horta comunitária", "Vira estacionamento", "Fecham para obras", "Vira área de plástico"], answers: ["Vira horta comunitária"], explain: "Por um lado, ocupamos um canto vazio da praça; por outro, ganhamos comida fresca e um lugar de encontro."),
                            Exercise(id: "pt-read-cartaz-vizinhanca-q3", kind: "choice", prompt: "O que a feira do sábado pede ?", options: ["Traga sua sacola", "Pague em dinheiro", "Chegue cedo", "Leve um vizinho"], answers: ["Traga sua sacola"], explain: "A feira do sábado vai funcionar sem plástico: traga sua sacola."),
                            Exercise(id: "pt-read-cartaz-vizinhanca-q4", kind: "written", prompt: "Qual é o lema do consumo no cartaz ?", options: [], answers: ["comprar menos e melhor", "comprar menos", "menos e melhor"], explain: "Comprar menos e melhor também é cuidar do bairro."),
                            Exercise(id: "pt-read-cartaz-vizinhanca-q5", kind: "choice", prompt: "Como o cartaz reconhece o esforço ?", options: ["O começo exige trabalho", "É grátis e fácil", "Só a prefeitura trabalha", "Ninguém precisa ajudar"], answers: ["O começo exige trabalho"], explain: "Embora o começo exija trabalho, o resultado pertence a todos.")], skills: ["reading:inference", "reading:detail", "grammar:connectors", "function:express-opinion"]),
    ReadingText(id: "pt-read-biscoito-chega", languageID: "pt", title: "O Biscoito chega", level: "A1", topic: "bicho", unitID: "pt-foundations-u27",
        text: "O Biscoito chegou na terça, de presente do tio Rafa. Ele é um gatinho preto, pequeno, com os olhos verdes. A Nina tem sete anos e cuida dele todos os dias: a água fresca fica na cozinha e a ração, no potinho vermelho. O Biscoito dorme muito, mas acorda cedo e brinca com a bolinha azul. À tarde, ele senta na janela e olha os pássaros. A avó já pergunta ao telefone: « e o Biscoito, está comportado ? ». A Nina responde que sim — mais ou menos.",
        questions: [
                            Exercise(id: "pt-read-biscoito-chega-q1", kind: "choice", prompt: "Quem dá o gatinho de presente ?", options: ["O tio Rafa", "A avó", "O vizinho", "O pai da Nina"], answers: ["O tio Rafa"], explain: "« De presente do tio Rafa »."),
                            Exercise(id: "pt-read-biscoito-chega-q2", kind: "written", prompt: "Como é o Biscoito ? (a cor)", options: [], answers: ["preto", "é preto", "preto e pequeno", "gatinho preto"], explain: "« Ele é um gatinho preto, pequeno »."),
                            Exercise(id: "pt-read-biscoito-chega-q3", kind: "choice", prompt: "Onde fica a ração ?", options: ["No potinho vermelho", "Na sala", "Na janela", "No sofá"], answers: ["No potinho vermelho"], explain: "« A ração, no potinho vermelho »."),
                            Exercise(id: "pt-read-biscoito-chega-q4", kind: "choice", prompt: "Com o que o Biscoito brinca ?", options: ["Com a bolinha azul", "Com o novelo", "Com a caixa", "Com os pássaros"], answers: ["Com a bolinha azul"], explain: "« Brinca com a bolinha azul »."),
                            Exercise(id: "pt-read-biscoito-chega-q5", kind: "written", prompt: "O que a avó pergunta ao telefone ?", options: [], answers: ["se está comportado", "está comportado", "se o biscoito está comportado"], explain: "« E o Biscoito, está comportado ? »")], skills: ["reading:detail", "reading:scan", "grammar:present-simple", "vocab:family"]),
    ReadingText(id: "pt-read-cardapio-domingo", languageID: "pt", title: "Almoço de domingo", level: "A1", topic: "cardápio", unitID: "pt-foundations-u16",
        text: "Almoço de domingo — Casa da Lu. Para começar: sopa de legumes ou salada verde. Pratos principais: frango assado com arroz, lasanha da casa e moqueca de peixe. O frango vem com farofa; a lasanha, com pão de alho. Sobremesas: pudim, mousse de maracujá e sorvete de coco. Bebidas: suco de laranja, refrigerante e água. Preços: a sopa custa doze reais, os pratos, trinta e dois, e as sobremesas, dez. Crianças até seis anos não pagam. Para pedir, chame a Lu na cozinha ou mande mensagem até as onze da manhã.",
        questions: [
                            Exercise(id: "pt-read-cardapio-domingo-q1", kind: "choice", prompt: "Quais são os pratos principais ?", options: ["Frango, lasanha e moqueca", "Sopa e salada", "Pudim e sorvete", "Pão de alho e farofa"], answers: ["Frango, lasanha e moqueca"], explain: "« Frango assado com arroz, lasanha da casa e moqueca de peixe »."),
                            Exercise(id: "pt-read-cardapio-domingo-q2", kind: "written", prompt: "Quanto custa um prato principal ?", options: [], answers: ["trinta e dois reais", "trinta e dois", "32 reais", "r\$ 32"], explain: "« Os pratos, trinta e dois »."),
                            Exercise(id: "pt-read-cardapio-domingo-q3", kind: "choice", prompt: "O que acompanha a lasanha ?", options: ["Pão de alho", "Farofa", "Arroz", "Salada verde"], answers: ["Pão de alho"], explain: "« A lasanha, com pão de alho »."),
                            Exercise(id: "pt-read-cardapio-domingo-q4", kind: "choice", prompt: "Quem não paga o almoço ?", options: ["Crianças até seis anos", "Quem pede sopa", "A família da Lu", "Ninguém"], answers: ["Crianças até seis anos"], explain: "« Crianças até seis anos não pagam »."),
                            Exercise(id: "pt-read-cardapio-domingo-q5", kind: "written", prompt: "Até que horas se faz o pedido ?", options: [], answers: ["até as onze", "às onze", "as onze da manhã", "11h"], explain: "« Mande mensagem até as onze da manhã ».")], skills: ["reading:scan", "reading:detail", "vocab:food", "function:order-food"]),
    ReadingText(id: "pt-read-mensagem-entrevista", languageID: "pt", title: "A entrevista remarcada", level: "B1", topic: "trabalho", unitID: "pt-foundations-u21",
        text: "Conversa do time — segunda-feira. Marta: gente, a entrevista do Bruno é amanhã às dez, na sala grande, certo ? Caio: era. A recrutadora pediu para mudar para as quatorze, porque às dez ela está em outro processo. Marta: ok. Bruno, você confirmou a hora com ela ? Bruno: confirmei. Mandei também a versão final do portfólio ontem à noite; ela respondeu que vai ler hoje. Caio: bom. Lembram que a próxima etapa é prática: uma simulação de atendimento. Quem avalia é a gerente da loja. Marta: então vocês ensaiam com ele hoje à tarde, sim ? Quanto mais treino, menos frio na barriga. Bruno: combinado. Às dezesseis na copa, levo o roteiro impresso.",
        questions: [
                            Exercise(id: "pt-read-mensagem-entrevista-q1", kind: "choice", prompt: "A que horas fica a entrevista ?", options: ["Às quatorze", "Às dez", "Às dezesseis", "Às nove"], answers: ["Às quatorze"], explain: "« Pediu para mudar para as quatorze »."),
                            Exercise(id: "pt-read-mensagem-entrevista-q2", kind: "written", prompt: "Por que a hora mudou ?", options: [], answers: ["ela está em outro processo", "a recrutadora está em outro processo", "outro processo"], explain: "« Porque às dez ela está em outro processo »."),
                            Exercise(id: "pt-read-mensagem-entrevista-q3", kind: "choice", prompt: "O que o Bruno enviou ontem ?", options: ["A versão final do portfólio", "O roteiro impresso", "O currículo antigo", "A lista de referências"], answers: ["A versão final do portfólio"], explain: "« Mandei também a versão final do portfólio ontem à noite »."),
                            Exercise(id: "pt-read-mensagem-entrevista-q4", kind: "choice", prompt: "Quem avalia a etapa prática ?", options: ["A gerente da loja", "A recrutadora", "A Marta", "O Caio"], answers: ["A gerente da loja"], explain: "« Quem avalia é a gerente da loja »."),
                            Exercise(id: "pt-read-mensagem-entrevista-q5", kind: "written", prompt: "Onde e quando o time ensaia ?", options: [], answers: ["na copa às dezesseis", "às dezesseis na copa", "na copa", "16h na copa"], explain: "« Às dezesseis na copa, levo o roteiro impresso ».")], skills: ["reading:inference", "reading:detail", "vocab:work", "function:talk-about-work"]),
    ReadingText(id: "pt-read-virada-bicicleta", languageID: "pt", title: "A bicicleta da virada", level: "B1", topic: "histórias", unitID: "pt-foundations-u18",
        text: "A bicicleta alugada mudou o meu ano. No começo de fevereiro eu perdi o emprego e, com ele, o crédito do transporte. Para não ficar em casa, comecei a pedalar: alugava a bike por duas horas e conhecia um bairro diferente por dia. Numa dessas voltas, parei numa padaria e reclamei do mapa da cidade com o dono; ele riu e me chamou para conversar. Ele procurava alguém para organizar as entregas de bicicleta — exatamente o que eu tinha aprendido a fazer, sem querer. Comecei na semana seguinte, com três rotas e uma sacola térmica. Seis meses depois, eu coordenava dez ciclistas e não pego mais ônibus. Não foi sorte: foi a bicicleta que me levou até a porta certa.",
        questions: [
                            Exercise(id: "pt-read-virada-bicicleta-q1", kind: "choice", prompt: "Por que o narrador começou a pedalar ?", options: ["Porque perdeu o crédito do transporte", "Porque gostava de esporte", "Porque a padaria ficava longe", "Porque o médico recomendou"], answers: ["Porque perdeu o crédito do transporte"], explain: "« Perdi o emprego e, com ele, o crédito do transporte »."),
                            Exercise(id: "pt-read-virada-bicicleta-q2", kind: "written", prompt: "O que o dono da padaria procurava ?", options: [], answers: ["alguém para organizar as entregas", "alguem para organizar as entregas", "organizador de entregas de bicicleta"], explain: "« Ele procurava alguém para organizar as entregas de bicicleta »."),
                            Exercise(id: "pt-read-virada-bicicleta-q3", kind: "choice", prompt: "Como o narrador conseguiu o trabalho ?", options: ["Conversando na padaria", "Por um anúncio na internet", "Por indicação da irmã", "Num processo seletivo"], answers: ["Conversando na padaria"], explain: "« Ele riu e me chamou para conversar »."),
                            Exercise(id: "pt-read-virada-bicicleta-q4", kind: "written", prompt: "O que ele fazia seis meses depois ?", options: [], answers: ["coordenava dez ciclistas", "coordenava ciclistas", "coordenava dez ciclistas da entrega"], explain: "« Seis meses depois, eu coordenava dez ciclistas »."),
                            Exercise(id: "pt-read-virada-bicicleta-q5", kind: "choice", prompt: "Qual é a conclusão da história ?", options: ["A bicicleta o levou à porta certa", "Ele voltou ao emprego antigo", "A sorte resolveu tudo", "Ele largou a bicicleta"], answers: ["A bicicleta o levou à porta certa"], explain: "« Foi a bicicleta que me levou até a porta certa ».")], skills: ["reading:inference", "grammar:past-simple-irregular", "function:tell-a-story", "grammar:connectors"]),
    ReadingText(id: "pt-read-artigo-energia", languageID: "pt", title: "A solução está no telhado", level: "B2", topic: "atualidade", unitID: "pt-foundations-u8",
        text: "A cidade gasta uma fortuna em luz — e a solução está no telhado. Enquanto discutimos tarifas, os prédios públicos continuam com lajes vazias, expostas a um sol que não mandamos cobrar. O programa aprovado pela câmara aponta o caminho: painéis nos telhados, kits nas escolas e técnicos treinados aqui, não trazidos de fora. É verdade que o custo inicial assusta e que os prazos anunciados parecem otimistas; todo programa novo carrega esses riscos. Mas o cálculo muda quando olhamos dez anos: a conta que cairia trinta por cento paga a instalação sozinha. Além do dinheiro, há um ganho invisível — vizinhanças que aprendem a produzir a própria energia discutem melhor qualquer outro serviço público. Se o edital sair claro e auditável, apoiar o programa não é aposta; é matemática.",
        questions: [
                            Exercise(id: "pt-read-artigo-energia-q1", kind: "choice", prompt: "Qual é a tese do artigo ?", options: ["O programa solar deve ser apoiado", "As tarifas devem subir", "As lajes devem virar jardins", "O edital deve ser cancelado"], answers: ["O programa solar deve ser apoiado"], explain: "« Apoiar o programa não é aposta; é matemática »."),
                            Exercise(id: "pt-read-artigo-energia-q2", kind: "written", prompt: "O que o autor reconhece como risco ?", options: [], answers: ["o custo inicial", "os prazos otimistas", "o custo inicial e os prazos otimistas", "custo e prazo"], explain: "« O custo inicial assusta e os prazos… parecem otimistas »."),
                            Exercise(id: "pt-read-artigo-energia-q3", kind: "choice", prompt: "Qual ganho invisível o artigo cita ?", options: ["Vizinhanças que aprendem a produzir energia", "Desconto na taxa de água", "Mais vagas de estacionamento", "Menos trânsito no centro"], answers: ["Vizinhanças que aprendem a produzir energia"], explain: "« Vizinhanças que aprendem a produzir a própria energia »."),
                            Exercise(id: "pt-read-artigo-energia-q4", kind: "written", prompt: "Em quanto tempo a instalação se paga, segundo o autor ?", options: [], answers: ["em dez anos", "dez anos", "10 anos"], explain: "« Quando olhamos dez anos: a conta… paga a instalação sozinha »."),
                            Exercise(id: "pt-read-artigo-energia-q5", kind: "choice", prompt: "Que condição o autor coloca para apoiar ?", options: ["Um edital claro e auditável", "Desconto para os deputados", "Kits só para escolas", "Técnicos de fora"], answers: ["Um edital claro e auditável"], explain: "« Se o edital sair claro e auditável ».")], skills: ["reading:inference", "writing:argument", "grammar:connectors", "grammar:first-conditional"]),
    ReadingText(id: "pt-read-email-fornecedor", languageID: "pt", title: "Negociando a proposta", level: "B2", topic: "negociação",
        text: "Assunto: proposta 2027 — prazo e volumes. Prezada equipe Vetriz, agradecemos a proposta recebida na segunda. A qualidade dos catálogos continua sendo o nosso principal motivo para renovar, e é justamente por isso que vamos direto aos dois pontos que travam o acordo: o prazo e o volume mínimo. Sobre o prazo: precisamos da primeira remessa até 15 de fevereiro; a data de março proposta atrasa nossa campanha de verão. Sobre o volume: mil unidades por pedido é muito para uma rede do nosso tamanho; oferecemos seiscentas, com compromisso de quatro pedidos no ano. Em troca dessas duas concessões, aceitamos o reajuste de sete por cento e antecipamos o pagamento da primeira remessa. Se essas condições fizerem sentido até sexta, marcamos a reunião de assinatura na próxima semana. Atenciosamente, Bia Camargo — Rede Estreita.",
        questions: [
                            Exercise(id: "pt-read-email-fornecedor-q1", kind: "choice", prompt: "Qual é o principal motivo para renovar com a Vetriz ?", options: ["A qualidade dos catálogos", "O preço baixo", "O prazo longo", "O frete grátis"], answers: ["A qualidade dos catálogos"], explain: "« A qualidade dos catálogos continua sendo o nosso principal motivo »."),
                            Exercise(id: "pt-read-email-fornecedor-q2", kind: "written", prompt: "Que prazo a rede precisa ?", options: [], answers: ["15 de fevereiro", "15/02", "primeira remessa até 15 de fevereiro", "quinze de fevereiro"], explain: "« Precisamos da primeira remessa até 15 de fevereiro »."),
                            Exercise(id: "pt-read-email-fornecedor-q3", kind: "choice", prompt: "Quantas unidades a rede oferece por pedido ?", options: ["Seiscentas", "Mil", "Quatrocentas", "Mil e duzentas"], answers: ["Seiscentas"], explain: "« Oferecemos seiscentas, com compromisso de quatro pedidos no ano »."),
                            Exercise(id: "pt-read-email-fornecedor-q4", kind: "written", prompt: "O que a rede aceita em troca ?", options: [], answers: ["o reajuste de sete por cento", "reajuste de 7%", "sete por cento", "7%"], explain: "« Aceitamos o reajuste de sete por cento »."),
                            Exercise(id: "pt-read-email-fornecedor-q5", kind: "choice", prompt: "O que acontece se as condições forem aceitas até sexta ?", options: ["Marcam a reunião de assinatura", "Cancelam a proposta", "Pedem novo catálogo", "Esperam março"], answers: ["Marcam a reunião de assinatura"], explain: "« Marcamos a reunião de assinatura na próxima semana ».")], skills: ["reading:inference", "function:negotiate", "writing:email", "grammar:connectors"])
    ]
}
